-- Anki-IPC-3108 (numbered, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: OSPF Router ID</div><p>The router ID identifies the router in LSAs and in DR (Designated Router)/BDR (Backup Designated Router) elections. OSPF (Open Shortest Path First) picks it in a fixed order: a manually configured ID wins first, then the highest loopback IP (Internet Protocol), then the highest physical interface IP.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Manual configuration</strong>: Manual configuration is the first, highest-priority method for choosing the OSPF router ID.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Lowest IP address on a loopback interface</strong>: OSPF uses the highest, not the lowest, loopback address.</li><li><span class="opt-tag wrong">Option B</span> <strong>Highest IP address on a physical interface</strong>: That is the third priority, used only if there is no manual ID and no loopback.</li><li><span class="opt-tag wrong">Option D</span> <strong>Highest IP address on a loopback interface</strong>: That is the second priority, used only if no manual router ID is configured.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><p>Router ID order:</p><ul><li>manual,</li><li>highest loopback,</li><li>highest physical.</li></ul><p>Manual always wins.</p></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 26 Flashcards - OSPF (Part 1)</div></div></div>' WHERE question_no = 'Anki-IPC-3108';

-- Anki-IPC-3109 (numbered, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: OSPF Router ID</div><p>The router ID identifies the router in LSAs and in DR (Designated Router)/BDR (Backup Designated Router) elections. OSPF (Open Shortest Path First) picks it in a fixed order: a manually configured ID wins first, then the highest loopback IP (Internet Protocol), then the highest physical interface IP.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Highest IP address on a loopback interface</strong>: The highest IP address on a loopback interface is the second priority for the router ID, used when no manual ID is configured.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Manual configuration</strong>: That is the first priority, not the second.</li><li><span class="opt-tag wrong">Option B</span> <strong>Highest IP address on a physical interface</strong>: That is the third priority, used only when there is no loopback interface.</li><li><span class="opt-tag wrong">Option D</span> <strong>Lowest IP address on a loopback interface</strong>: OSPF uses the highest, not the lowest, loopback address.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><p>Router ID order:</p><ul><li>manual,</li><li>highest loopback,</li><li>highest physical.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 26 Flashcards - OSPF (Part 1)</div></div></div>' WHERE question_no = 'Anki-IPC-3109';

-- Anki-IPC-3110 (numbered, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: OSPF Router ID</div><p>The router ID identifies the router in LSAs and in DR (Designated Router)/BDR (Backup Designated Router) elections. OSPF (Open Shortest Path First) picks it in a fixed order: a manually configured ID wins first, then the highest loopback IP (Internet Protocol), then the highest physical interface IP.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>Highest IP address on a physical interface</strong>: The highest IP address on a physical interface is the third priority for the router ID, used only when there is no manual ID and no loopback.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Manual configuration</strong>: That is the first priority, not the third.</li><li><span class="opt-tag wrong">Option C</span> <strong>Highest IP address on a loopback interface</strong>: That is the second priority, used before any physical interface is considered.</li><li><span class="opt-tag wrong">Option D</span> <strong>Lowest IP address on a physical interface</strong>: OSPF uses the highest, not the lowest, physical interface address.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><p>Router ID order:</p><ul><li>manual,</li><li>highest loopback,</li><li>highest physical.</li></ul><p>Loopbacks are preferred because they never go down.</p></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 26 Flashcards - OSPF (Part 1)</div></div></div>' WHERE question_no = 'Anki-IPC-3110';

-- Question #164 (numbered, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card">
    <div class="section-title-concept">📌 Core Concept: VLAN Hopping Attack Mitigation (Switch Spoofing & Double Tagging)</div>
    <p>VLAN hopping occurs when an unauthorized attacker transmits frames that bypass Layer 2 switch boundaries to inject packets into a different VLAN.</p>
  </div>

  <div class="expl-card correct-card">
    <h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4>
    <ul>
      <li><span class="opt-tag correct">Option C</span> <strong>manually implement trunk ports and disable DTP</strong>:
        <ul>
          <li><strong>Switch Spoofing</strong> exploits Cisco Dynamic Trunking Protocol (DTP) to negotiate a trunk link with the switch. Disabling DTP (<code>switchport nonegotiate</code>) and explicitly setting ports to access mode (<code>switchport mode access</code>) completely prevents switch spoofing.</li>
          <li>For remaining trunk ports: Statically configure them (<code>switchport mode trunk</code>) and change the <strong>Native VLAN</strong> to an unused ID to defeat Double Tagging attacks.</li>
        </ul>
      </li>
    </ul>
  </div>

  <div class="expl-card incorrect-card">
    <h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4>
    <ul>
      <li><span class="opt-tag wrong">Option A</span>: Extended VLANs (VLAN IDs 1006-4094) have identical tagging mechanisms and offer no inherent protection against VLAN hopping.</li>
      <li><span class="opt-tag wrong">Option B</span>: Activating all ports in default VLAN 1 makes the entire network vulnerable to double-tagging attacks.</li>
      <li><span class="opt-tag wrong">Option D</span>: Dynamic ARP Inspection (DAI) prevents ARP spoofing/poisoning, not Layer 2 802.1Q VLAN hopping.</li>
    </ul>
  </div>

  <div class="expl-card tip-card">
    <h4 class="section-title-tip">💡 CCNA Exam Tip:</h4>
    <p>To prevent VLAN Hopping:</p><ul><li>Disable DTP negotiation (<code>switchport nonegotiate</code>).</li><li>Explicitly configure <code>switchport mode access</code> on all client ports.</li><li>Change the <strong>Native VLAN</strong> on trunk links to an unused ID.</li></ul>
  </div>
</div>' WHERE question_no = 'Question #164';

-- Question #177 (numbered, 2 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card">
    <div class="section-title-concept">📌 Core Concept: Mandatory WPA3 Security Requirements (IEEE 802.11w)</div>
    <p>Wi-Fi Protected Access 3 (WPA3) enforces stricter mandatory baseline security standards to protect wireless communications from eavesdropping and disruption.</p>
  </div>

  <div class="expl-card correct-card">
    <h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4>
    <ul>
      <li><span class="opt-tag correct">Option C</span> <strong>Protected Management Frame</strong>: In the WPA3 standard (both WPA3-Personal and WPA3-Enterprise), <strong>Protected Management Frames (PMF, IEEE 802.11w)</strong> is <strong>mandatory</strong>. PMF cryptographically authenticates and encrypts management frames (such as Deauthentication and Disassociation frames), protecting clients against wireless denial of service attacks.</li>
    </ul>
  </div>

  <div class="expl-card incorrect-card">
    <h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4>
    <ul>
      <li><span class="opt-tag wrong">Option A</span> <strong>Fast Transition</strong>: IEEE 802.11r roaming is optional in WPA3.</li>
      <li><span class="opt-tag wrong">Option B & D</span> <strong>Opportunistic Wireless Encryption / Enhanced Open</strong>: OWE (RFC 8110) provides unauthenticated encryption for open public hotspots, not WPA3-Personal which uses Pre-Shared Keys with SAE.</li>
    </ul>
  </div>

  <div class="expl-card tip-card">
    <h4 class="section-title-tip">💡 CCNA Exam Tip:</h4>
    <p>Two Non-Negotiable Requirements in WPA3-Personal:</p><ul><li><strong>SAE (Simultaneous Authentication of Equals)</strong>.</li><li><strong>Mandatory PMF (Protected Management Frames, 802.11w)</strong>.</li></ul>
  </div>
</div>' WHERE question_no = 'Question #177';

-- Question #19 (numbered, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card">
    <div class="section-title-concept">📌 Core Concept: Spine-and-Leaf (Clos) Fabric Topology</div>
    <p>Spine-and-leaf architecture is the standard design for modern data centers. It delivers predictable, low-latency east-west traffic flow across a non-blocking fabric.</p>
  </div>

  <div class="expl-card correct-card">
    <h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4>
    <ul>
      <li><span class="opt-tag correct">Option A</span> <strong>A leaf switch is added with connections to every spine switch</strong>: In a spine-and-leaf fabric, all endpoints (servers, storage) connect to leaf switches. To scale access port capacity, a new leaf switch is added and must be uplinked to <strong>every single spine switch</strong>.</li>
    </ul>
  </div>

  <div class="expl-card incorrect-card">
    <h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4>
    <ul>
      <li><span class="opt-tag wrong">Option B</span>: Uplinking to only one spine violates Clos architecture, creates an oversubscription bottleneck, and introduces a single point of failure.</li>
      <li><span class="opt-tag wrong">Option C</span>: Adding spine switches scales aggregate fabric throughput/bandwidth, but does not provide access ports for servers.</li>
      <li><span class="opt-tag wrong">Option D</span>: Leaves never connect to other leaves, and spines never connect to other spines.</li>
    </ul>
  </div>

  <div class="expl-card tip-card">
    <h4 class="section-title-tip">💡 CCNA Exam Tip:</h4>
    <p>Spine-and-Leaf Rules:</p><ul><li>Every Leaf connects to EVERY Spine.</li><li>Spines never connect to Spines.</li><li>Leaves never connect to Leaves.</li><li>Every endpoint is exactly 2 hops away.</li></ul>
  </div>
</div>' WHERE question_no = 'Question #19';

-- Question #191 (numbered, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card">
    <div class="section-title-concept">📌 Core Concept: Longest Prefix Match (LPM) Rule</div>
    <p>When a router has multiple routes covering a packet''s destination IP address, it always forwards traffic according to the route with the <strong>longest subnet mask</strong> (most specific prefix), regardless of administrative distance or routing protocol.</p>
  </div>

  <div class="expl-card correct-card">
    <h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4>
    <ul>
      <li><span class="opt-tag correct">Option D</span> <strong>192.168.16.0/27</strong>:
        <ul>
          <li>Destination IP address: <code>192.168.16.27</code>.</li>
          <li>Looking at the routing table in the exhibit:
            <br/>• <code>192.168.16.0/21</code> (Mask length: 21)
            <br/>• <code>192.168.16.0/24</code> (Mask length: 24)
            <br/>• <code>192.168.16.0/26</code> (Mask length: 26, range: .0 - .63)
            <br/>• <code>192.168.16.0/27</code> (Mask length: 27, range: .0 - .31)
          </li>
          <li>All four routes encompass the IP <code>192.168.16.27</code>. Because <strong>/27</strong> has the longest prefix (27 network bits), the router chooses <strong>192.168.16.0/27</strong> via 192.168.1.4.</li>
        </ul>
      </li>
    </ul>
  </div>

  <div class="expl-card incorrect-card">
    <h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4>
    <ul>
      <li><span class="opt-tag wrong">Option A</span> <strong>/21</strong>: Less specific than /24, /26, and /27.</li>
      <li><span class="opt-tag wrong">Option B</span> <strong>/24</strong>: Less specific than /26 and /27.</li>
      <li><span class="opt-tag wrong">Option C</span> <strong>/26</strong>: Less specific than /27. Although EIGRP (AD 90) has a lower administrative distance than IS-IS (AD 115), <strong>prefix length is evaluated FIRST</strong> before AD!</li>
    </ul>
  </div>

  <div class="expl-card tip-card">
    <h4 class="section-title-tip">💡 CCNA Exam Tip:</h4>
    <p>Route Selection Order:</p><ul><li><strong>Longest Prefix Match (Subnet Mask)</strong>. Always wins first!</li><li><strong>Administrative Distance (AD)</strong>. Only evaluated if masks are identical.</li><li><strong>Metric</strong>. Evaluated if protocol and masks are identical.</li></ul>
  </div>
</div>' WHERE question_no = 'Question #191';

-- Question #2 (numbered, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card">
    <div class="section-title-concept">📌 Core Concept: Longest Prefix Match (LPM) Routing</div>
    <p>When forwarding an IP packet, a router examines all matching routes in its routing table and selects the path with the <strong>most specific prefix (longest subnet mask)</strong>, regardless of administrative distance or metric.</p>
  </div>

  <div class="expl-card correct-card">
    <h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4>
    <ul>
      <li><span class="opt-tag correct">Option C</span> <strong>10.35.47.17</strong>:
        <ul>
          <li>Target destination: <code>172.16.153.154</code>.</li>
          <li><code>172.16.153.153 255.255.255.255</code> (/32) does NOT match (it only matches host .153).</li>
          <li><code>172.16.153.0 255.255.255.0</code> (/24) covers range <code>172.16.153.0 - 172.16.153.255</code>, which <strong>matches</strong>!</li>
          <li><code>172.16.0.0 255.255.0.0</code> (/16) and <code>172.0.0.0 255.0.0.0</code> (/8) also match, but have shorter prefix lengths (/16 and /8).</li>
          <li>Under Longest Prefix Match, <strong>/24 beats /16 and /8</strong>. The next hop for <code>172.16.153.0/24</code> is <strong>10.35.47.17</strong>.</li>
        </ul>
      </li>
    </ul>
  </div>

  <div class="expl-card incorrect-card">
    <h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4>
    <ul>
      <li><span class="opt-tag wrong">Option A</span> <strong>10.56.22.23</strong>: Next hop for <code>172.16.0.0/16</code>, which is less specific than the /24 route.</li>
      <li><span class="opt-tag wrong">Option B</span> <strong>10.65.34.19</strong>: Next hop for host route <code>172.16.153.153/32</code>. Since the destination is .154, this route does not match.</li>
      <li><span class="opt-tag wrong">Option D</span> <strong>10.12.13.14</strong>: Next hop for <code>172.0.0.0/8</code>, the least specific matching prefix.</li>
    </ul>
  </div>

  <div class="expl-card tip-card">
    <h4 class="section-title-tip">💡 CCNA Exam Tip:</h4>
    <p>Routing Table Order of Precedence:</p><ul><li><strong>Longest Prefix Match (Subnet Mask)</strong></li><li>Administrative Distance (AD)</li><li>Metric.</li></ul>
  </div>
</div>' WHERE question_no = 'Question #2';

-- Question #206 (numbered, 5 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card">
    <div class="section-title-concept">📌 Core Concept: Cisco IOS Secure Remote Access (SSHv2) Configuration</div>
    <p>To replace insecure clear-text Telnet with Secure Shell (SSH), a Cisco switch requires: hostname, domain name, RSA crypto keys, a local user account, and configuring VTY lines to accept only SSH transport.</p>
  </div>

  <div class="expl-card correct-card">
    <h4 class="section-title-correct">✓ Why the Correct Answers (Options A & C) are Correct:</h4>
    <ul>
      <li><span class="opt-tag correct">Option A</span> <code>SW1(config)# ip ssh version 2</code>: Enforces SSH version 2, which eliminates known security vulnerabilities present in SSH version 1.</li>
      <li><span class="opt-tag correct">Option C</span> <code>SW1(config)# line vty 0 15</code> followed by <code>SW1(config-line)# transport input ssh</code>:
        <ul>
          <li>The exhibit shows that <code>line vty 0 4</code> and <code>line vty 5 15</code> currently have <code>transport input telnet</code> configured.</li>
          <li>Changing this to <code>transport input ssh</code> restricts remote management access exclusively to encrypted SSH connections and blocks unencrypted Telnet.</li>
        </ul>
      </li>
    </ul>
  </div>

  <div class="expl-card incorrect-card">
    <h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4>
    <ul>
      <li><span class="opt-tag wrong">Option B</span>: A local username (<code>username CCNA privilege 1 password 0 cisco123</code>) already exists in the running configuration.</li>
      <li><span class="opt-tag wrong">Option D</span>: <code>show crypto key mypubkey rsa</code> at the bottom of the exhibit demonstrates that an RSA key pair (<code>SW1.CCNA-test</code>) is <strong>already generated</strong>. Regenerating it is unnecessary.</li>
      <li><span class="opt-tag wrong">Option E</span>: Configuring interface F0/1 as a VLAN trunk does not secure remote management access to the switch.</li>
    </ul>
  </div>

  <div class="expl-card tip-card">
    <h4 class="section-title-tip">💡 CCNA Exam Tip:</h4>
    <p>Essential SSH Configuration Steps:</p><ul><li><code>hostname [name]</code> & <code>ip domain-name [domain]</code></li><li><code>crypto key generate rsa</code> (already done in exhibit)</li><li><code>username [user] secret [pass]</code></li><li><strong><code>ip ssh version 2</code></strong></li><li><strong><code>line vty 0 15</code> > <code>transport input ssh</code></strong></li></ul>
  </div>
</div>' WHERE question_no = 'Question #206';

-- Question #26 (numbered, 2 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card">
    <div class="section-title-concept">📌 Core Concept: Physical Layer & Access Port Security</div>
    <p>Unsecured Ethernet ports located in public areas (hallways, shared offices, conference rooms) represent a significant vector for rogue device insertion and physical network intrusion.</p>
  </div>

  <div class="expl-card correct-card">
    <h4 class="section-title-correct">✓ Why the Correct Answers (Options C and D) are Correct:</h4>
    <ul>
      <li><span class="opt-tag correct">Option C</span> <strong>shut down unused ports</strong>: Administratively disabling unused access switch ports (<code>shutdown</code>) physically prevents unauthorized rogue devices from simply plugging into an active Ethernet jack.</li>
      <li><span class="opt-tag correct">Option D</span> <strong>implement port-based authentication</strong>: Deploying <strong>IEEE 802.1X</strong> requires any device connected to an active port to authenticate against a RADIUS server (e.g. Cisco ISE) using valid credentials or digital certificates before the port transitions to the forwarding state.</li>
    </ul>
  </div>

  <div class="expl-card incorrect-card">
    <h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4>
    <ul>
      <li><span class="opt-tag wrong">Option A</span>: Static ARP entries are impractical to scale in office environments and do not prevent unauthorized physical network attachment.</li>
      <li><span class="opt-tag wrong">Option B</span>: Hardcoding port speed and duplex is a transmission setting that offers zero security or access control.</li>
      <li><span class="opt-tag wrong">Option E</span>: PortFast immediately transitions access ports to the forwarding state to bypass listening/learning, but provides no security.</li>
    </ul>
  </div>

  <div class="expl-card tip-card">
    <h4 class="section-title-tip">💡 CCNA Exam Tip:</h4>
    <p>Two essential switch port security best practices:</p><ul><li><strong>Shutdown</strong> all unused switch ports and place them in a dedicated ''Blackhole'' / Parking VLAN.</li><li>Use <strong>802.1X (port-based authentication)</strong> for all active user-facing ports.</li></ul>
  </div>
</div>' WHERE question_no = 'Question #26';

-- Question #5 (numbered, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card">
    <div class="section-title-concept">📌 Core Concept: QoS Modular Architecture (Classification vs. Marking)</div>
    <p>Cisco Modular QoS CLI (MQC) partitions quality of service operations into logical stages: <strong>Classification</strong>, <strong>Marking</strong>, and <strong>Congestion Management / Queuing</strong>.</p>
  </div>

  <div class="expl-card correct-card">
    <h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4>
    <ul>
      <li><span class="opt-tag correct">Option D</span> <strong>identifies the type of traffic that will receive a particular treatment</strong>: Classification is the fundamental process of inspecting incoming packets using criteria (ACLs, NBAR, DSCP/CoS values, protocols) to identify and categorize traffic into distinct classes.</li>
    </ul>
  </div>

  <div class="expl-card incorrect-card">
    <h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4>
    <ul>
      <li><span class="opt-tag wrong">Option A</span>: Writing or modifying the class identifier in the packet header (such as DSCP or CoS) is defined as <strong>Marking</strong> (Coloring).</li>
      <li><span class="opt-tag wrong">Option B</span>: Configuring rules is the administrative setup of class maps, but not the operational purpose of classification itself.</li>
      <li><span class="opt-tag wrong">Option C</span>: Servicing traffic according to its class is <strong>Queuing / Scheduling</strong> (e.g., Low Latency Queuing - LLQ).</li>
    </ul>
  </div>

  <div class="expl-card tip-card">
    <h4 class="section-title-tip">💡 CCNA Exam Tip:</h4>
    <p>QoS Lifecycle:</p><ul><li><strong>Classify</strong> (identify traffic)</li><li><strong>Mark</strong> (tag packet header with DSCP/CoS)</li><li><strong>Queue & Schedule</strong> (prioritize or shape).</li></ul>
  </div>
</div>' WHERE question_no = 'Question #5';

-- Question #6 (numbered, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card">
    <div class="section-title-concept">📌 Core Concept: Cisco IOS Secure Shell (SSHv2) Requirements</div>
    <p>To establish secure SSHv2 administrative access on a Cisco router, several foundational cryptographic and system parameters must be configured in sequence.</p>
  </div>

  <div class="expl-card correct-card">
    <h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4>
    <ul>
      <li><span class="opt-tag correct">Option D</span>:
        <ul>
          <li><code>hostname R15</code>: Must change default name ''Router'' before generating RSA keys.</li>
          <li><code>ip domain-name cisco.com</code>: Required to formulate the router''s Fully Qualified Domain Name (FQDN) for the RSA key pair.</li>
          <li><code>crypto key generate rsa general-keys modulus 1024</code>: Generates the RSA key pair (modulus &ge; 768 bits is required for SSHv2; 1024 or higher recommended).</li>
          <li><code>ip ssh version 2</code>: Enforces SSH version 2.</li>
          <li><code>line vty 0 15</code> &rarr; <code>transport input ssh</code>: Disables insecure Telnet and restricts incoming management sessions to SSH.</li>
        </ul>
      </li>
    </ul>
  </div>

  <div class="expl-card incorrect-card">
    <h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4>
    <ul>
      <li><span class="opt-tag wrong">Option A</span>: Lacks <code>hostname</code> and <code>ip domain-name</code>, which causes key generation to fail with error <em>"% Please define a domain-name first"</em>.</li>
      <li><span class="opt-tag wrong">Option B</span>: Uses <code>transport input all</code> (allowing unencrypted Telnet) and fails to set a unique hostname.</li>
      <li><span class="opt-tag wrong">Option C</span>: Omits <code>ip domain-name</code> and <code>ip ssh version 2</code>.</li>
    </ul>
  </div>

  <div class="expl-card tip-card">
    <h4 class="section-title-tip">💡 CCNA Exam Tip:</h4>
    <p>SSH Prerequisites Mnemonic: <strong>Host, Domain, Crypto, VTY</strong>.<br/>(</p><ul><li>Hostname</li><li>IP domain-name</li><li>Crypto key generate</li><li>Transport input ssh).</li></ul>
  </div>
</div>' WHERE question_no = 'Question #6';

-- Question #81 (numbered, 2 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card">
    <div class="section-title-concept">📌 Core Concept: SSH Hardening & 2048-bit RSA Modulus</div>
    <p>Modern security baselines mandate phasing out insecure Telnet in favor of SSH with strong RSA asymmetric key encryption of at least 2048 bits.</p>
  </div>

  <div class="expl-card correct-card">
    <h4 class="section-title-correct">✓ Why the Correct Answers (Options C and E) are Correct:</h4>
    <ul>
      <li><span class="opt-tag correct">Option C</span> <code>crypto key generate rsa modulus 2048</code>: Generates a cryptographically strong 2048-bit RSA public/private key pair used for SSH session key exchange and host authentication.</li>
      <li><span class="opt-tag correct">Option E</span> <code>transport input ssh</code>: Configured on the VTY lines (<code>line vty 0 15</code>) to block unencrypted Telnet connections and restrict incoming remote management exclusively to SSH.</li>
    </ul>
  </div>

  <div class="expl-card incorrect-card">
    <h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4>
    <ul>
      <li><span class="opt-tag wrong">Option A</span>: Specifies a <code>modulus 1024</code>, which does not meet the 2048-bit requirement.</li>
      <li><span class="opt-tag wrong">Option B</span>: <code>usage-keys</code> generates separate keys for signing and encryption, but does not specify the required 2048-bit modulus.</li>
      <li><span class="opt-tag wrong">Option D</span>: <code>transport input all</code> permits both Telnet and SSH, failing the requirement to eliminate Telnet.</li>
    </ul>
  </div>

  <div class="expl-card tip-card">
    <h4 class="section-title-tip">💡 CCNA Exam Tip:</h4>
    <p>Secure VTY Configuration:</p><ul><li><code>crypto key generate rsa modulus 2048</code> (Strong key)</li><li><code>line vty 0 15</code> &rarr; <code>transport input ssh</code> (Only allow SSH).</li></ul>
  </div>
</div>' WHERE question_no = 'Question #81';

-- Anki-AUTO-6013 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: The Southbound Interface (SBI)</div><p>The southbound interface is the link between the SDN (Software-Defined Networking) controller and the network devices it controls. OpenFlow, OpFlex, onePK and NETCONF are all southbound interfaces.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>Southbound Interface</strong>: SBI stands for Southbound Interface. The interface facing &#x27;south&#x27; from the controller down to the devices.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Southbound Integration</strong>: The last word is Interface, not Integration.</li><li><span class="opt-tag wrong">Option C</span> <strong>System Bound Interface</strong>: The first word is Southbound, not System Bound.</li><li><span class="opt-tag wrong">Option D</span> <strong>Southern Boundary Interface</strong>: The exam term is Southbound, not Southern Boundary.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Southbound = controller to devices (down).</li><li>Northbound = controller to applications (up).</li><li>Direction is the whole trick.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 59 Flashcards - Network Automation)</div></div></div>' WHERE question_no = 'Anki-AUTO-6013';

-- Anki-AUTO-6019 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: The Southbound Interface in Use</div><p>The controller needs a way to tell the devices what to do. That link is the southbound interface. OpenFlow, OpFlex, onePK and NETCONF all do this job.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>South</strong>: The interface between the SDN (Software-Defined Networking) controller and the devices it controls is, by definition, the southbound interface.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>West</strong>: There is no westbound interface in the SDN model used by the exam.</li><li><span class="opt-tag wrong">Option B</span> <strong>East</strong>: There is no eastbound interface in the SDN model used by the exam.</li><li><span class="opt-tag wrong">Option C</span> <strong>North</strong>: Northbound is the interface between the controller and applications, not devices.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Controller to devices = southbound.</li><li>Controller to applications = northbound.</li><li>Learn the pair and you cannot go wrong.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 59 Flashcards - Network Automation)</div></div></div>' WHERE question_no = 'Anki-AUTO-6019';

-- Anki-AUTO-6027 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Whitespace in JSON</div><p>JSON (JavaScript Object Notation) ignores whitespace: spaces, tabs and newlines between tokens change nothing about the data. That is why JSON can be pretty-printed or minified and still mean the same thing.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>isn&#x27;t</strong>: In JSON, whitespace is not significant. You can add or remove spaces and the data stays identical.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>only in strings</strong>: Whitespace inside a string value is part of the string, but whitespace between tokens is ignored entirely.</li><li><span class="opt-tag wrong">Option B</span> <strong>is</strong>: That is YAML (YAML Ain''t Markup Language), not JSON. In JSON, whitespace does not change the meaning.</li><li><span class="opt-tag wrong">Option D</span> <strong>only between keys</strong>: Whitespace is ignored everywhere between tokens, not only between keys.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>JSON whitespace = not significant.</li><li>YAML whitespace = significant (indentation is the structure).</li><li>The exam tests this pair together.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 60 Flashcards - JSON, XML, &amp; YAML)</div></div></div>' WHERE question_no = 'Anki-AUTO-6027';

-- Anki-AUTO-6032 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: JSON String Values</div><p>In JSON (JavaScript Object Notation), a value in double quotes is a string. A text value. The key-value pair &quot;key&quot;:&quot;value&quot; has a quoted value, so its type is string.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>string</strong>: The value &quot;value&quot; is wrapped in double quotes, which makes it a JSON string.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>boolean</strong>: A boolean in JSON is true or false without quotes, like &quot;key&quot;:false.</li><li><span class="opt-tag wrong">Option C</span> <strong>object</strong>: An object value uses braces with key-value pairs inside, like &quot;key&quot;:{&quot;interface&quot;:&quot;gigabitethernet1/1&quot;}.</li><li><span class="opt-tag wrong">Option D</span> <strong>number</strong>: A number in JSON is written without quotes, like &quot;key&quot;:5.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Quotes around the value = string.</li><li>No quotes and digits = number.</li><li>true/false = boolean.</li><li>null = null.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 60 Flashcards - JSON, XML, &amp; YAML)</div></div></div>' WHERE question_no = 'Anki-AUTO-6032';

-- Anki-AUTO-6033 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: JSON Number Values</div><p>In JSON (JavaScript Object Notation), a bare numeric value is a number. The pair &quot;key&quot;:5 has the unquoted value 5, so its type is number.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>number</strong>: The value 5 is written without quotes, which makes it a JSON number.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>array</strong>: An array value uses square brackets with a list inside, like &quot;key&quot;:[&quot;yes&quot;, &quot;no&quot;].</li><li><span class="opt-tag wrong">Option B</span> <strong>string</strong>: A string value is wrapped in double quotes, like &quot;key&quot;:&quot;value&quot;.</li><li><span class="opt-tag wrong">Option D</span> <strong>boolean</strong>: A boolean in JSON is true or false, like &quot;key&quot;:false.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Bare digits with no quotes = number.</li><li>Quotes = string.</li><li>This is the easiest JSON type question on the exam.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 60 Flashcards - JSON, XML, &amp; YAML)</div></div></div>' WHERE question_no = 'Anki-AUTO-6033';

-- Anki-AUTO-6036 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: JSON Array Values</div><p>In JSON (JavaScript Object Notation), square brackets hold an array. An ordered series of values. The pair &quot;key&quot;:[&quot;yes&quot;, &quot;no&quot;] has a bracketed list, so its type is array.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>array</strong>: The value [&quot;yes&quot;, &quot;no&quot;] is a list in square brackets, which is a JSON array.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>number</strong>: A number is a bare numeric value, like &quot;key&quot;:5.</li><li><span class="opt-tag wrong">Option B</span> <strong>string</strong>: A string is a single quoted text value, like &quot;key&quot;:&quot;value&quot;.</li><li><span class="opt-tag wrong">Option D</span> <strong>object</strong>: An object uses braces with key-value pairs inside, like &quot;key&quot;:{&quot;interface&quot;:&quot;gigabitethernet1/1&quot;}.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Square brackets [ ] = array.</li><li>Curly braces { } = object.</li><li>Brackets are the fastest way to spot an array.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 60 Flashcards - JSON, XML, &amp; YAML)</div></div></div>' WHERE question_no = 'Anki-AUTO-6036';

-- Anki-AUTO-6037 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: JSON Object Values</div><p>In JSON (JavaScript Object Notation), curly braces hold an object. A set of key-value pairs. The pair &quot;key&quot;:{&quot;interface&quot;:&quot;gigabitethernet1/1&quot;} has a braced set of pairs, so its type is object.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>object</strong>: The value {&quot;interface&quot;:&quot;gigabitethernet1/1&quot;} is a set of key-value pairs in braces, which is a JSON object.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>string</strong>: A string is a single quoted text value, like &quot;key&quot;:&quot;value&quot;.</li><li><span class="opt-tag wrong">Option B</span> <strong>number</strong>: A number is a bare numeric value, like &quot;key&quot;:5.</li><li><span class="opt-tag wrong">Option D</span> <strong>array</strong>: An array is a list in square brackets, like &quot;key&quot;:[&quot;yes&quot;, &quot;no&quot;].</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Curly braces { } = object.</li><li>Square brackets [ ] = array.</li><li>Braces hold key-value pairs; brackets hold a list.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 60 Flashcards - JSON, XML, &amp; YAML)</div></div></div>' WHERE question_no = 'Anki-AUTO-6037';

-- Anki-AUTO-6043 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: JSON Array Type</div><p>A JSON (JavaScript Object Notation) array is a series of values wrapped in square brackets. It is one of the two structured JSON data types.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>array</strong>: A JSON array is a series of values. An ordered list in square brackets.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>object</strong>: An object is a list of key-value pairs in braces, not a series of values.</li><li><span class="opt-tag wrong">Option B</span> <strong>string</strong>: A string is a single text value in double quotes.</li><li><span class="opt-tag wrong">Option D</span> <strong>boolean</strong>: A boolean can only be true or false.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Array = series of values in [ ].</li><li>Object = key-value pairs in { }.</li><li>Brackets versus braces is the whole distinction.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 60 Flashcards - JSON, XML, &amp; YAML)</div></div></div>' WHERE question_no = 'Anki-AUTO-6043';

-- Anki-AUTO-6044 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: XML Format</div><p>XML (Extensible Markup Language) structures data with tags: &lt;key&gt;value&lt;/key&gt;. JSON (JavaScript Object Notation) uses &quot;key&quot;:&quot;value&quot; with quotes and braces, and YAML (YAML Ain''t Markup Language) uses key: value with indentation.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>XML</strong>: The &lt;key&gt;value&lt;/key&gt; tag format is XML. Only XML wraps data in angle-bracket tags.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>YAML</strong>: YAML uses the key: value format with indentation, not tags.</li><li><span class="opt-tag wrong">Option B</span> <strong>CSV</strong>: CSV uses comma-separated values on plain lines, not tags.</li><li><span class="opt-tag wrong">Option D</span> <strong>JSON</strong>: JSON uses the &quot;key&quot;:&quot;value&quot; format with quotes and braces, not angle-bracket tags.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Angle-bracket tags &lt; &gt; = XML.</li><li>Quoted keys with braces = JSON.</li><li>key: value with indentation = YAML.</li><li>Spot the format, name the language.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 60 Flashcards - JSON, XML, &amp; YAML)</div></div></div>' WHERE question_no = 'Anki-AUTO-6044';

-- Anki-AUTO-6048 (mapping, 5 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: YAML Key-Value Pairs</div><p>YAML (YAML Ain''t Markup Language) writes key-value pairs as key: value. The key, a colon, and the value. JSON (JavaScript Object Notation) uses &quot;key&quot;:&quot;value&quot; and XML (Extensible Markup Language) uses &lt;key&gt;value&lt;/key&gt;.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>key:value</strong>: YAML key-value pairs are represented as key:value. The colon format with no quotes or tags.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>key=value</strong>: The equals sign is not YAML syntax; YAML separates keys and values with a colon.</li><li><span class="opt-tag wrong">Option C</span> <strong>&lt;key&gt;value&lt;/key&gt;</strong>: That is the XML tag format, not YAML.</li><li><span class="opt-tag wrong">Option D</span> <strong>&quot;key&quot;:&quot;value&quot;</strong>: That is the JSON format, not YAML.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>YAML = key: value.</li><li>JSON = &quot;key&quot;:&quot;value&quot;.</li><li>XML = &lt;key&gt;value&lt;/key&gt;.</li><li>One format per language.</li><li>Do not mix them.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 60 Flashcards - JSON, XML, &amp; YAML)</div></div></div>' WHERE question_no = 'Anki-AUTO-6048';

-- Anki-AUTO-6050 (mapping, 5 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: CRUD Create and HTTP POST</div><p>In a REST (Representational State Transfer) API (Application Programming Interface), the CRUD (Create, Read, Update, Delete) Create operation maps to HTTP (Hypertext Transfer Protocol) POST. You POST a new resource to create it.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>Create</strong>: CRUD Create maps to HTTP POST, so the missing CRUD word for POST is Create.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>Read</strong>: Read maps to HTTP GET, not POST.</li><li><span class="opt-tag wrong">Option C</span> <strong>Delete</strong>: Delete maps to HTTP DELETE, not POST.</li><li><span class="opt-tag wrong">Option D</span> <strong>Update</strong>: Update maps to HTTP PUT or PATCH, not POST.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Create = POST.</li><li>Read = GET.</li><li>Update = PUT/PATCH.</li><li>Delete = DELETE.</li><li>Learn the four pairs as one set.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 61 Flashcards - REST APIs)</div></div></div>' WHERE question_no = 'Anki-AUTO-6050';

-- Anki-AUTO-6058 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: URI</div><p>A URI (Uniform Resource Identifier) is a string that identifies a resource. For example, the address of a REST (Representational State Transfer) API (Application Programming Interface) endpoint. URL (Uniform Resource Locator) is a specific kind of URI that also tells you where to find the resource.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Uniform Resource Identifier</strong>: URI stands for Uniform Resource Identifier. A uniform way to identify a resource.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Universal Resource Identifier</strong>: The first word is Uniform, not Universal.</li><li><span class="opt-tag wrong">Option B</span> <strong>Uniform Resource Locator</strong>: That is URL, not URI. A Locator gives a location, an Identifier only identifies.</li><li><span class="opt-tag wrong">Option D</span> <strong>Unified Resource Indicator</strong>: The first word is Uniform and the last is Identifier, not Unified Indicator.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>URI = Uniform Resource Identifier.</li><li>URL = Uniform Resource Locator.</li><li>URI identifies; URL locates.</li><li>The exam tests the pair.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 61 Flashcards - REST APIs)</div></div></div>' WHERE question_no = 'Anki-AUTO-6058';

-- Anki-AUTO-6059 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Parts of a URI - Scheme</div><p>A URI (Uniform Resource Identifier) has three main parts: the scheme (the protocol, before the colon), the authority (the host), and the path (the resource location after the host). In https://sandboxdnac.cisco.com/dna/intent/api/v1/network-device, the scheme is https.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>https</strong>: The scheme is the part before the colon. Here it is https, the protocol used to reach the resource.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>dna</strong>: That is just the first segment of the path, not the scheme.</li><li><span class="opt-tag wrong">Option B</span> <strong>sandboxdnac.cisco.com</strong>: That is the authority (the host), not the scheme.</li><li><span class="opt-tag wrong">Option D</span> <strong>/dna/intent/api/v1/network-device</strong>: That is the path, not the scheme.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Scheme = before the colon (https).</li><li>Authority = the host.</li><li>Path = everything after the host.</li><li>Read a URI left to right: scheme, authority, path.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 61 Flashcards - REST APIs)</div></div></div>' WHERE question_no = 'Anki-AUTO-6059';

-- Anki-AUTO-6095 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: SDN Underlay</div><p>The underlay is the physical network of devices and connections. The real switches, routers and links the overlay runs on.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>underlay</strong>: The underlay is the physical network of devices and connections. The real switches, routers and links the overlay runs on.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>overlay</strong>: Overlay is the virtual network built on top of the underlay.</li><li><span class="opt-tag wrong">Option B</span> <strong>control plane</strong>: Control plane is where forwarding decisions are made, not the physical network itself.</li><li><span class="opt-tag wrong">Option D</span> <strong>fabric</strong>: Fabric is the combination of underlay and overlay together.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Underlay = under = physical.</li><li>Overlay = over = virtual.</li><li>The words describe the position.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 62 Flashcards - SDN)</div></div></div>' WHERE question_no = 'Anki-AUTO-6095';

-- Anki-AUTO-6106 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Ansible</div><p>Ansible is written in Python, which is why it runs agentless over SSH (Secure Shell) and why its modules are Python scripts.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Python</strong>: Ansible is written in Python, which is why it runs agentless over SSH and why its modules are Python scripts.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Ruby</strong>: Ruby is the language Puppet and Chef are written in, not Ansible.</li><li><span class="opt-tag wrong">Option B</span> <strong>Go</strong>: Go is not the language Ansible is written in.</li><li><span class="opt-tag wrong">Option D</span> <strong>Java</strong>: Java is not the language Ansible is written in.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Ansible = Python.</li><li>Puppet and Chef = Ruby.</li><li>That one line answers three exam questions.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 63 Flashcards - Ansible, Puppet, Chef)</div></div></div>' WHERE question_no = 'Anki-AUTO-6106';

-- Anki-AUTO-6121 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Puppet Port 8140</div><p>Puppet clients use TCP (Transmission Control Protocol) port 8140 to communicate with the Puppet master. The agent&#x27;s HTTPS (Hypertext Transfer Protocol Secure) connection runs on this port.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Puppet</strong>: Puppet clients use TCP port 8140 to communicate with the Puppet master. The agent&#x27;s HTTPS connection runs on this port.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Ansible</strong>: Ansible uses SSH (Secure Shell) (port 22) and has no client agent or fixed application port like this.</li><li><span class="opt-tag wrong">Option B</span> <strong>SaltStack</strong>: SaltStack is a different automation tool. It does not use port 8140.</li><li><span class="opt-tag wrong">Option D</span> <strong>Chef</strong>: Chef uses TCP port 10002 for its push jobs, not 8140.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>8140 = Puppet.</li><li>10002 = Chef.</li><li>Learn the pair and the port questions answer themselves.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 63 Flashcards - Ansible, Puppet, Chef)</div></div></div>' WHERE question_no = 'Anki-AUTO-6121';

-- Anki-AUTO-6129 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Chef Ruby DSL</div><p>Chef files are written in a proprietary language based on Ruby. Recipes are Ruby code with Chef&#x27;s DSL on top.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>a proprietary langage based on Ruby.</strong>: Chef files are written in a proprietary language based on Ruby. Recipes are Ruby code with Chef&#x27;s DSL on top.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>a proprietary language (known as Puppet DSL)</strong>: Puppet DSL is Puppet&#x27;s language. Chef&#x27;s is based on Ruby.</li><li><span class="opt-tag wrong">Option C</span> <strong>YAML</strong>: YAML (YAML Ain''t Markup Language) is Ansible&#x27;s file language, not Chef&#x27;s.</li><li><span class="opt-tag wrong">Option D</span> <strong>Python</strong>: Python is Ansible&#x27;s language, not Chef&#x27;s.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Chef files = Ruby-based.</li><li>Puppet files = Puppet DSL.</li><li>Ansible files = YAML.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 63 Flashcards - Ansible, Puppet, Chef)</div></div></div>' WHERE question_no = 'Anki-AUTO-6129';

-- Anki-AUTO-6130 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Chef Port 10002</div><p>Chef uses TCP (Transmission Control Protocol) port 10002 to send configurations to clients. The Chef push-jobs service listens on this port.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>Chef</strong>: Chef uses TCP port 10002 to send configurations to clients. The Chef push-jobs service listens on this port.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Ansible</strong>: Ansible uses SSH (Secure Shell) (port 22) and has no fixed application port like this.</li><li><span class="opt-tag wrong">Option C</span> <strong>Puppet</strong>: Puppet uses TCP port 8140, not 10002.</li><li><span class="opt-tag wrong">Option D</span> <strong>SaltStack</strong>: SaltStack is a different automation tool. It does not use port 10002.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>10002 = Chef.</li><li>8140 = Puppet.</li><li>The two port numbers belong to the two agent-based tools.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Automation and Programmability (CCNA / Day 63 Flashcards - Ansible, Puppet, Chef)</div></div></div>' WHERE question_no = 'Anki-AUTO-6130';

-- Anki-IPC-3004 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Administrative Distance vs Metric</div><p>When a router learns routes to the same destination from different sources, it compares them in two steps: Administrative Distance (AD) first, to choose between different routing protocols, and metric second, to choose between routes from the same protocol.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>AD (Administrative Distance)</strong>: Routes from two different routing protocols are compared with Administrative Distance, and the route with the lower AD (Administrative Distance) wins and is placed in the routing table.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>next hop</strong>: The next hop is the neighbouring router a packet is forwarded to; it does not decide between two competing routes.</li><li><span class="opt-tag wrong">Option C</span> <strong>Metric</strong>: Metric is only used to compare routes learned from the same routing protocol.</li><li><span class="opt-tag wrong">Option D</span> <strong>longest prefix match</strong>: Longest prefix match decides between routes to different prefix lengths, not between routes from different protocols to the same destination.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Different protocols = AD.</li><li>Same protocol = metric.</li><li>Say it like a rule and you will never mix them up.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 24 Flashcards - Dynamic Routing)</div></div></div>' WHERE question_no = 'Anki-IPC-3004';

-- Anki-IPC-3005 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Administrative Distance vs Metric</div><p>Routes learned from the same routing protocol all have the same Administrative Distance, so AD (Administrative Distance) cannot separate them. The router then compares their metrics and installs the route with the lowest metric.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Metric</strong>: Both routes come from the same protocol, so the router compares their metrics and installs the route with the lower metric.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>AD (Administrative Distance)</strong>: Administrative Distance only separates routes from different routing protocols; it is identical for routes from the same protocol.</li><li><span class="opt-tag wrong">Option B</span> <strong>prefix length</strong>: Prefix length matters when routes cover different networks; here both routes go to the same destination.</li><li><span class="opt-tag wrong">Option D</span> <strong>hop count</strong>: Hop count is just one kind of metric (the one RIP uses), not the general concept used to compare routes.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Same protocol = metric.</li><li>Different protocols = AD.</li><li>The two are never swapped on the exam.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 24 Flashcards - Dynamic Routing)</div></div></div>' WHERE question_no = 'Anki-IPC-3005';

-- Anki-IPC-3008 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IGP and EGP</div><p>Routing protocols are grouped by where they run: Interior Gateway Protocols (IGPs) share routes inside one autonomous system, while Exterior Gateway Protocols (EGPs) share routes between autonomous systems.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>Interior Gateway Protocol</strong>: IGP stands for Interior Gateway Protocol, the group of protocols that run inside a single autonomous system.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>Interdomain Gateway Protocol</strong>: ''Interdomain'' describes routing between domains, which is the job of an EGP, not an IGP.</li><li><span class="opt-tag wrong">Option C</span> <strong>Internal Gateway Protocol</strong>: ''Internal'' is a common misreading, but the correct word is Interior, as in ''inside one AS''.</li><li><span class="opt-tag wrong">Option D</span> <strong>Internet Gateway Protocol</strong>: ''Internet Gateway Protocol'' is not a real term; IGP is about the interior of an autonomous system, not the Internet.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Interior = inside one AS.</li><li>Exterior = between ASes.</li><li>The first letter of the expansion is the whole question.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 24 Flashcards - Dynamic Routing)</div></div></div>' WHERE question_no = 'Anki-IPC-3008';

-- Anki-IPC-3016 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Distance Vector Protocols</div><p>Distance Vector protocols work by ''routing by rumour'': each router tells its neighbours the networks it knows and its metric to reach them. The two Distance Vector protocols in the CCNA are RIP (Routing Information Protocol) and EIGRP (Enhanced Interior Gateway Routing Protocol).</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>RIP EIGRP</strong>: The two Distance Vector routing protocols are RIP and EIGRP.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>EIGRP BGP</strong>: BGP (Border Gateway Protocol) is a Path Vector (EGP) protocol, not a Distance Vector protocol.</li><li><span class="opt-tag wrong">Option C</span> <strong>RIP OSPF</strong>: OSPF (Open Shortest Path First) is a Link State protocol, so pairing it with RIP mixes the two types.</li><li><span class="opt-tag wrong">Option D</span> <strong>OSPF IS-IS</strong>: OSPF and IS-IS (Intermediate System to Intermediate System) are Link State protocols, not Distance Vector.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Distance Vector = RIP and EIGRP.</li><li>Link State = OSPF and IS-IS.</li><li>Path Vector = BGP.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 24 Flashcards - Dynamic Routing)</div></div></div>' WHERE question_no = 'Anki-IPC-3016';

-- Anki-IPC-3024 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Distance Vector: Routing by Rumour</div><p>Distance Vector protocols are nicknamed ''routing by rumour'' because a router only knows what its neighbours tell it: the networks they know and their metric to reach them. It never sees the full network map.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>Distance Vector</strong>: Distance Vector protocols operate by ''routing by rumour'', passing second-hand route information from neighbour to neighbour.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Path Vector</strong>: Path Vector (BGP) carries the full AS path with the route, so it is not routing by rumour.</li><li><span class="opt-tag wrong">Option C</span> <strong>Link State</strong>: Link State protocols build a full map (LSDB) of the network, the opposite of routing by rumour.</li><li><span class="opt-tag wrong">Option D</span> <strong>Hybrid</strong>: ''Hybrid'' is a loose label sometimes used for EIGRP (Enhanced Interior Gateway Routing Protocol), not the name of the rumour-based type.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Rumour = Distance Vector.</li><li>Map = Link State.</li><li>Path = Path Vector.</li><li>The nickname is the question.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 24 Flashcards - Dynamic Routing)</div></div></div>' WHERE question_no = 'Anki-IPC-3024';

-- Anki-IPC-3036 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IS-IS Metric</div><p>IS-IS (Intermediate System to Intermediate System) is the odd one out among the metrics: by default every link has a cost of 10, whatever its speed. (Narrow metrics can be changed, but the CCNA default is 10 per link.)</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>IS-IS</strong>: In IS-IS, all links have a metric cost of 10 by default.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>OSPF</strong>: OSPF (Open Shortest Path First) calculates cost from bandwidth, so a 10 Mbps link costs 10 but a 100 Mbps link costs 1; not every link is 10.</li><li><span class="opt-tag wrong">Option B</span> <strong>EIGRP</strong>: EIGRP (Enhanced Interior Gateway Routing Protocol) uses a bandwidth-and-delay composite metric, not a fixed 10 per link.</li><li><span class="opt-tag wrong">Option D</span> <strong>RIP</strong>: RIP (Routing Information Protocol) uses hop count, so every link costs 1 hop, not 10.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>IS-IS = 10 per link, flat.</li><li>OSPF = cost from bandwidth.</li><li>RIP = 1 hop per link.</li><li>Three different ''10s'' to keep apart.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 24 Flashcards - Dynamic Routing)</div></div></div>' WHERE question_no = 'Anki-IPC-3036';

-- Anki-IPC-3037 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Administrative Distance vs Metric</div><p>Routes from the same routing protocol share the same Administrative Distance, so the router compares their metrics and installs the lowest-metric route.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>Metric</strong>: Metric is used to compare routes learned via the same routing protocol.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>prefix length</strong>: Prefix length decides between routes to different networks, not between routes from the same protocol.</li><li><span class="opt-tag wrong">Option C</span> <strong>hop count</strong>: Hop count is one specific metric (RIP''s), not the general concept used to compare routes.</li><li><span class="opt-tag wrong">Option D</span> <strong>AD (Administrative Distance)</strong>: AD (Administrative Distance) compares routes from different routing protocols, not from the same one.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Same protocol = metric.</li><li>Different protocols = AD.</li><li>Two sentences, zero confusion.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 24 Flashcards - Dynamic Routing)</div></div></div>' WHERE question_no = 'Anki-IPC-3037';

-- Anki-IPC-3049 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Administrative Distance Table</div><p>An AD (Administrative Distance) of 255 means the route is unusable: the router will never install it in the routing table. 255 is the maximum AD value and marks a route as not to be trusted at all.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>255</strong>: An unusable route has an AD of 255, the maximum value, which means it will never be used.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>170</strong>: 170 is the AD of external EIGRP (Enhanced Interior Gateway Routing Protocol), a real route, not an unusable one.</li><li><span class="opt-tag wrong">Option B</span> <strong>0</strong>: 0 is the AD of a directly connected route, the most trusted route of all, the opposite of unusable.</li><li><span class="opt-tag wrong">Option D</span> <strong>200</strong>: 200 is the AD of iBGP, a real (if barely trusted) route, not an unusable one.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>255 = unusable, never installed.</li><li>0 = connected, most trusted.</li><li>The AD scale runs 0 (best) to 255 (never use).</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 24 Flashcards - Dynamic Routing)</div></div></div>' WHERE question_no = 'Anki-IPC-3049';

-- Anki-IPC-3053 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: RIP Versions</div><p>RIP (Routing Information Protocol) has two IPv4 (Internet Protocol version 4) versions: RIPv1 (classful, broadcast, no VLSM) and RIPv2 (classless, multicast, supports VLSM). IPv6 (Internet Protocol version 6) uses a different version, RIPng.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>RIPv1 and RIPv2</strong>: The versions of RIP used for IPv4 are RIPv1 and RIPv2.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>RIPv2 and RIPng</strong>: RIPng is the IPv6 version of RIP, not an IPv4 version.</li><li><span class="opt-tag wrong">Option B</span> <strong>RIPng only</strong>: RIPng is for IPv6 only; it is never used for IPv4.</li><li><span class="opt-tag wrong">Option C</span> <strong>RIPv1 only</strong>: RIPv1 alone is not the full answer; RIPv2 is also used for IPv4.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>IPv4 = RIPv1 + RIPv2.</li><li>IPv6 = RIPng.</li><li>The ''ng'' (Next Generation) is the IPv6 one.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 25 Flashcards (1)</div></div></div>' WHERE question_no = 'Anki-IPC-3053';

-- Anki-IPC-3055 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: RIP Message Types</div><p>RIP (Routing Information Protocol) routers exchange routing information with two message types: Request (ask a neighbour for its routes) and Response (send your routes, either as a reply or as a periodic update).</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>Request Response</strong>: RIP uses two message types: Request and Response.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>Hello Update</strong>: Hello is an OSPF (Open Shortest Path First)/EIGRP (Enhanced Interior Gateway Routing Protocol) message used to discover neighbours, not a RIP message type.</li><li><span class="opt-tag wrong">Option C</span> <strong>Query Reply</strong>: Query and Reply are EIGRP messages, not RIP message types.</li><li><span class="opt-tag wrong">Option D</span> <strong>Request Acknowledge</strong>: There is no ''Acknowledge'' message in RIP; the reply to a Request is a Response.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>RIP = Request + Response.</li><li>EIGRP = Query + Reply.</li><li>OSPF = Hello + DBD + LSR + LSU + LSAck.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 25 Flashcards (1)</div></div></div>' WHERE question_no = 'Anki-IPC-3055';

-- Anki-IPC-3056 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: RIPv1 vs RIPv2</div><p>RIPv1 is classful: it only advertises classful addresses (Class A, B and C networks) and does not send subnet mask information, so it cannot support VLSM (Variable Length Subnet Mask) or CIDR (Classless Inter-Domain Routing).</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>1</strong>: RIPv1 only advertises classful addresses, because it does not include subnet mask information in its updates.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>3</strong>: There is no RIPv3.</li><li><span class="opt-tag wrong">Option C</span> <strong>ng</strong>: RIPng is the IPv6 (Internet Protocol version 6) version and is not the answer to a classful-address question.</li><li><span class="opt-tag wrong">Option D</span> <strong>2</strong>: RIPv2 is classless and does send mask information, so it is not limited to classful addresses.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>v1 = classful, broadcast, no VLSM.</li><li>v2 = classless, multicast, VLSM.</li><li>The version number is the whole difference.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 25 Flashcards (1)</div></div></div>' WHERE question_no = 'Anki-IPC-3056';

-- Anki-IPC-3071 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Unequal-Cost Load Balancing</div><p>OSPF (Open Shortest Path First) only installs equal-cost routes to the same destination and load-balances across them. It has no mechanism for sharing traffic across paths with different costs.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>can''t</strong>: OSPF can''t perform unequal-cost load-balancing; it only load-balances over equal-cost paths.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>can, but only with the variance command</strong>: The variance command belongs to EIGRP (Enhanced Interior Gateway Routing Protocol); OSPF has no variance command.</li><li><span class="opt-tag wrong">Option C</span> <strong>can, but only over two paths</strong>: OSPF cannot load-balance over two unequal-cost paths, or any number of them.</li><li><span class="opt-tag wrong">Option D</span> <strong>can</strong>: OSPF cannot share traffic across unequal-cost paths at all.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>OSPF = equal-cost only.</li><li>Unequal-cost = EIGRP only.</li><li>RIP (Routing Information Protocol) = equal-cost only.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 25 Flashcards (1)</div></div></div>' WHERE question_no = 'Anki-IPC-3071';

-- Anki-IPC-3073 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: ECMP: Maximum Paths</div><p>By default a router load-balances over up to 4 equal-cost paths (16 is the maximum in modern IOS). The ''maximum-paths'' command in router mode changes that number for the protocol.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>maximum-paths number</strong>: To modify the number of paths RIP (Routing Information Protocol) will perform ECMP (Equal-Cost Multi-Path) load-balancing over you type: maximum-paths number.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>variance number</strong>: ''variance'' controls unequal-cost load balancing in EIGRP (Enhanced Interior Gateway Routing Protocol); it does not set the number of equal-cost paths.</li><li><span class="opt-tag wrong">Option C</span> <strong>load-balance number</strong>: ''load-balance'' is not a command name; the path count is set with ''maximum-paths''.</li><li><span class="opt-tag wrong">Option D</span> <strong>maximum-routes number</strong>: ''maximum-routes'' is not a Cisco IOS command; the command is ''maximum-paths''.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>maximum-paths = how many equal-cost paths.</li><li>Default 4, maximum 16.</li><li>variance = unequal-cost (EIGRP only).</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 25 Flashcards (1)</div></div></div>' WHERE question_no = 'Anki-IPC-3073';

-- Anki-IPC-3100 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: OSPF Route Types</div><p>OSPF (Open Shortest Path First) marks routes by where the destination sits relative to the router: inside the same area, in another area, or outside the OSPF domain entirely. The route type shows up in the routing table as O, O IA, or O E1/E2.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>intra-area</strong>: A route to a destination inside the same OSPF area is an intra-area route, shown as O in the routing table.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>interarea</strong>: An interarea route goes to a destination in a different OSPF area, shown as O IA.</li><li><span class="opt-tag wrong">Option C</span> <strong>external</strong>: An external route comes from outside the OSPF domain via an ASBR (Autonomous System Boundary Router), shown as O E1 or O E2.</li><li><span class="opt-tag wrong">Option D</span> <strong>backbone</strong>: Backbone describes a router or area 0, not a route type.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Same area = intra-area (O).</li><li>Different area = interarea (O IA).</li><li>Outside OSPF = external (O E1/E2).</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 26 Flashcards - OSPF (Part 1)</div></div></div>' WHERE question_no = 'Anki-IPC-3100';

-- Anki-IPC-3101 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: OSPF Route Types</div><p>OSPF (Open Shortest Path First) marks routes by where the destination sits: inside the same area (intra-area, O), in another area (interarea, O IA), or outside the OSPF domain (external, O E1/E2).</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>interarea</strong>: A route to a destination in a different OSPF area is an interarea route, shown as O IA in the routing table.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>backbone</strong>: Backbone describes a router or area 0, not a route type.</li><li><span class="opt-tag wrong">Option C</span> <strong>external</strong>: An external route comes from outside the OSPF domain via an ASBR (Autonomous System Boundary Router), shown as O E1 or O E2.</li><li><span class="opt-tag wrong">Option D</span> <strong>intra-area</strong>: An intra-area route stays inside the same OSPF area, shown as O.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Same area = intra-area (O).</li><li>Different area = interarea (O IA).</li><li>Outside OSPF = external (O E1/E2).</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 26 Flashcards - OSPF (Part 1)</div></div></div>' WHERE question_no = 'Anki-IPC-3101';

-- Anki-IPC-3112 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: OSPF Acronyms</div><p>ASBR (Autonomous System Boundary Router) is one of the OSPF (Open Shortest Path First) router roles. It sits at the edge of the OSPF domain and brings in routes from outside, for example by redistributing from another routing protocol or static routes.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>Autonomous System Boundary Router</strong>: ASBR stands for Autonomous System Boundary Router.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Autonomous System Border Router</strong>: The last word is Boundary, not Border; only the ABR (Area Border Router) uses Border.</li><li><span class="opt-tag wrong">Option C</span> <strong>Area Border Router</strong>: That is ABR, the router between OSPF areas.</li><li><span class="opt-tag wrong">Option D</span> <strong>Area System Boundary Router</strong>: The first word is Autonomous, not Area.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>ASBR = Autonomous System Boundary Router.</li><li>ABR = Area Border Router.</li><li>One letter changes the whole meaning.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 26 Flashcards - OSPF (Part 1)</div></div></div>' WHERE question_no = 'Anki-IPC-3112';

-- Anki-IPC-3127 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: OSPF Cost</div><p>The bandwidth command only changes the logical bandwidth value that routing protocols use for metrics. The actual speed of the interface is set with the speed command.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>No (the speed command does)</strong>: No, the bandwidth command does not change the speed at which an interface operates; the speed command does.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Only on Ethernet interfaces</strong>: The rule is the same on every interface type: bandwidth never changes real speed.</li><li><span class="opt-tag wrong">Option C</span> <strong>Yes, it sets the physical speed</strong>: That is the job of the speed command, not the bandwidth command.</li><li><span class="opt-tag wrong">Option D</span> <strong>Yes</strong>: Bandwidth only changes the value routing protocols use for metrics.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>bandwidth = metric value only.</li><li>speed = real interface speed.</li><li>Do not confuse the two.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 27 Flashcards - OSPF (Part 2)</div></div></div>' WHERE question_no = 'Anki-IPC-3127';

-- Anki-IPC-3130 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: OSPF Multicast</div><p>OSPF (Open Shortest Path First) uses two well-known multicast addresses: 224.0.0.5 for all OSPF routers and 224.0.0.6 for the DR (Designated Router) and BDR (Backup Designated Router) only. Hellos go to 224.0.0.5.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>224.0.0.5</strong>: The multicast address for all OSPF routers (AllSPFRouters) is 224.0.0.5.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>224.0.0.9</strong>: That is the EIGRP (Enhanced Interior Gateway Routing Protocol) multicast address (224.0.0.10), not OSPF; 224.0.0.9 is RIPv2.</li><li><span class="opt-tag wrong">Option B</span> <strong>224.0.0.6</strong>: That is AllDRouters, the DR and BDR only, not all OSPF routers.</li><li><span class="opt-tag wrong">Option C</span> <strong>224.0.0.10</strong>: That is the EIGRP multicast address, not OSPF.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>224.0.0.5 = all OSPF routers.</li><li>224.0.0.6 = DR/BDR only.</li><li>224.0.0.10 = EIGRP.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 27 Flashcards - OSPF (Part 2)</div></div></div>' WHERE question_no = 'Anki-IPC-3130';

-- Anki-IPC-3137 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: OSPF Neighbor States</div><p>Down is the starting state: no Hello has been received from the neighbor yet, so the router has no information about it at all.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>Down</strong>: If no Hello messages have been received, the OSPF (Open Shortest Path First) neighbor state is Down.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Init</strong>: Init means a Hello was received, but the neighbor has not seen our router ID in it yet.</li><li><span class="opt-tag wrong">Option B</span> <strong>Exstart</strong>: Exstart comes much later, after the DR (Designated Router)/BDR (Backup Designated Router) election.</li><li><span class="opt-tag wrong">Option C</span> <strong>2-way</strong>: 2-way means both routers have seen each other in Hellos.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>No Hellos at all = Down.</li><li>One-way Hello = Init.</li><li>Two-way Hello = 2-way.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 27 Flashcards - OSPF (Part 2)</div></div></div>' WHERE question_no = 'Anki-IPC-3137';

-- Anki-IPC-3176 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: OSPF Network Types</div><p>OSPF (Open Shortest Path First) behaves differently depending on the link type. On multi-access networks like Ethernet, routers elect a DR (Designated Router) and BDR (Backup Designated Router) and use multicast Hellos; this is the Broadcast network type.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Broadcast</strong>: The Broadcast network type is enabled on Ethernet and FDDI interfaces by default.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Point-to-point</strong>: Point-to-point is the default on PPP and HDLC serial links, not on Ethernet.</li><li><span class="opt-tag wrong">Option B</span> <strong>Point-to-multipoint</strong>: Point-to-multipoint is never a default network type; it must be configured manually.</li><li><span class="opt-tag wrong">Option D</span> <strong>Non-broadcast</strong>: Non-broadcast is the default on Frame Relay and X.25, not on Ethernet.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Ethernet = Broadcast by default.</li><li>Serial PPP/HDLC = Point-to-point.</li><li>Frame Relay = Non-broadcast.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 28 Flashcards - OSPF (Part 3)</div></div></div>' WHERE question_no = 'Anki-IPC-3176';

-- Anki-IPC-3185 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: OSPF DR/BDR Election</div><p>On a broadcast segment with many routers, a full mesh of adjacencies would be wasteful. Instead one router is elected DR (Designated Router) and one BDR (Backup Designated Router), and all other routers (DROthers) peer only with them.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Yes</strong>: Yes, in the Broadcast network type a DR and a BDR are elected.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Only on NBMA networks</strong>: NBMA networks do elect a DR/BDR, but so does the Broadcast type; the question is about Broadcast.</li><li><span class="opt-tag wrong">Option B</span> <strong>Only a DR, no BDR</strong>: Both a DR and a BDR are always elected together on broadcast networks.</li><li><span class="opt-tag wrong">Option D</span> <strong>No</strong>: That is the Point-to-point type, where only two routers exist and no election is needed.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Broadcast = DR + BDR elected.</li><li>Point-to-point = no election.</li><li>The DR/BDR cut down adjacencies on multi-access links.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 28 Flashcards - OSPF (Part 3)</div></div></div>' WHERE question_no = 'Anki-IPC-3185';

-- Anki-IPC-3262 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Connected routes</div><p>A connected route points to the network that one of the router''s interfaces is attached to. It is added automatically when the interface gets an IP (Internet Protocol) address and has code C in the routing table.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>connected</strong>: A connected route is a route to the network the interface is connected to.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>static</strong>: A static route is configured manually; a connected route is added automatically.</li><li><span class="opt-tag wrong">Option B</span> <strong>local</strong>: A local route points to the exact IP address on the interface, not to the whole network.</li><li><span class="opt-tag wrong">Option C</span> <strong>direct</strong>: Direct is not a routing table term; the route to the attached network is the connected route.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Connected = the network.</li><li>Local = the address.</li><li>Both appear automatically when you configure an interface.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 11 (part 1)</div></div></div>' WHERE question_no = 'Anki-IPC-3262';

-- Anki-IPC-3267 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Connected route prefix length</div><p>A connected route covers the whole network the interface is attached to, so its prefix length is whatever was configured on the interface. For example a /24 if the interface is 192.168.1.1/24.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>The prefix length configured on the interface.</strong>: Connected routes use the prefix length configured on the interface.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>The prefix length of the longest matching route</strong>: Longest matching route is a forwarding concept, not how a connected route gets its prefix length.</li><li><span class="opt-tag wrong">Option B</span> <strong>/32</strong>: /32 is the prefix length of a local route (one address), not a connected route (a whole network).</li><li><span class="opt-tag wrong">Option D</span> <strong>/24</strong>: /24 is only correct if the interface was configured with a /24 mask; the rule is the configured prefix, whatever it is.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Connected = the interface''s own mask.</li><li>Local = always /32.</li><li>Keep the two apart.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Connectivity (CCNA / Day 11 (part 1)</div></div></div>' WHERE question_no = 'Anki-IPC-3267';

-- Anki-IPS-4016 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Viewing ACLs</div><p>show access-lists displays every ACL (Access Control List) on the device, standard, extended, IPv4 (Internet Protocol version 4) and IPv6 (Internet Protocol version 6), with their entries and match counts.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>show access-lists</strong>: show access-lists displays every ACL on the device, standard, extended, IPv4 and IPv6.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>show ip access-lists</strong>: that shows only IPv4 ACLs, not all ACLs</li><li><span class="opt-tag wrong">Option B</span> <strong>show access-group</strong>: not a valid command; access-group is the apply command, not a show command</li><li><span class="opt-tag wrong">Option D</span> <strong>show running-config | include access-list</strong>: that only greps the config text; it does not show match counters</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>show access-lists = all ACLs.</li><li>show ip access-lists = IPv4 only.</li><li>The exam tests this one-word difference.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 34 Flashcards - Standard ACLs)</div></div></div>' WHERE question_no = 'Anki-IPS-4016';

-- Anki-IPS-4018 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Standard ACL Placement</div><p>Standard ACLs match only the source address, so they are placed as close to the destination as possible. Placed near the source, they would block that source from reaching every destination.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>destination</strong>: Standard ACLs match only the source address, so placing them near the source would block traffic to all destinations; near the destination they affect only that destination.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>source</strong>: near the source is where extended ACLs go; a standard ACL (Access Control List) there would block the source everywhere</li><li><span class="opt-tag wrong">Option B</span> <strong>gateway</strong>: the gateway is usually near the source, the wrong end for a standard ACL</li><li><span class="opt-tag wrong">Option C</span> <strong>core</strong>: the core is the middle of the network, not a placement rule for standard ACLs</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Standard = close to destination.</li><li>Extended = close to source.</li><li>This is a classic exam question.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 34 Flashcards - Standard ACLs)</div></div></div>' WHERE question_no = 'Anki-IPS-4018';

-- Anki-IPS-4024 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Numbered ACL Limitations</div><p>Numbered ACL (Access Control List) entries configured in global config mode have no sequence numbers, so you cannot remove one entry. You must delete the whole ACL with no access-list &lt;number&gt; and recreate it.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>can''t</strong>: In global config mode, numbered ACL entries have no sequence numbers, so you cannot remove one entry; you must delete the whole ACL.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>can</strong>: without sequence numbers there is nothing to target for deletion</li><li><span class="opt-tag wrong">Option B</span> <strong>can, but only with resequence</strong>: resequence works on named ACLs, not on numbered ACLs in global config mode</li><li><span class="opt-tag wrong">Option D</span> <strong>can, but only standard ACLs</strong>: the limitation applies to all numbered ACLs, standard and extended</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Numbered = all or nothing.</li><li>Named = delete one line by number.</li><li>This is the big practical reason to use named ACLs.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 35 Flashcards - Extended ACLs)</div></div></div>' WHERE question_no = 'Anki-IPS-4024';

-- Anki-IPS-4049 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: The Software Clock</div><p>Cisco devices have two clocks: the software clock, which IOS uses, and the hardware clock (calendar), which is battery-backed. show clock displays the software clock.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>show clock</strong>: show clock displays the software clock, the time the IOS software is currently using.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>show time</strong>: not a valid IOS command</li><li><span class="opt-tag wrong">Option C</span> <strong>show calendar</strong>: that shows the hardware clock, the battery-backed calendar chip</li><li><span class="opt-tag wrong">Option D</span> <strong>show ntp status</strong>: that shows NTP (Network Time Protocol) sync status, not the current time</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>clock = software time.</li><li>calendar = hardware time.</li><li>The two can disagree.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 37 Flashcards - NTP)</div></div></div>' WHERE question_no = 'Anki-IPS-4049';

-- Anki-IPS-4056 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Device Logs</div><p>show logging displays the buffered log messages on the device, and the logging configuration (where logs are sent).</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>show logging</strong>: show logging displays the buffered log messages (and the logging configuration).</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>show history</strong>: that shows the command history, not device logs</li><li><span class="opt-tag wrong">Option B</span> <strong>show syslog</strong>: not a valid IOS command; syslog is the protocol, logging is the command</li><li><span class="opt-tag wrong">Option C</span> <strong>show log</strong>: not a valid IOS command</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Logging = logs.</li><li>History = commands you typed.</li><li>The exam swaps them.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 37 Flashcards - NTP)</div></div></div>' WHERE question_no = 'Anki-IPS-4056';

-- Anki-IPS-4059 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Synchronising the Two Clocks</div><p>clock read-calendar reads the hardware calendar into the software clock, so the software clock matches the hardware clock.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>clock read-calendar</strong>: clock read-calendar reads the hardware calendar into the software clock.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>clock update-calendar</strong>: that writes the software clock into the hardware calendar, the opposite direction</li><li><span class="opt-tag wrong">Option B</span> <strong>calendar read-clock</strong>: not a valid command</li><li><span class="opt-tag wrong">Option D</span> <strong>clock sync-calendar</strong>: not a valid command; the keyword is read-calendar</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>read = read FROM the calendar INTO the clock.</li><li>update = write the clock INTO the calendar.</li><li>The verb tells you the direction.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 37 Flashcards - NTP)</div></div></div>' WHERE question_no = 'Anki-IPS-4059';

-- Anki-IPS-4062 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Daylight Saving Time</div><p>clock summer-time &lt;name&gt; recurring &lt;start&gt; &lt;end&gt; [offset] configures daylight saving time that repeats every year. Start and end each need the week (first, last or a number), weekday, month and time.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>clock summer-time name recurring start end [ offset ] ( start and end require the week ( first , last , or number ), weekday, month, and time)</strong>: clock summer-time &lt;name&gt; recurring &lt;start&gt; &lt;end&gt; [offset] configures DST that repeats every year, with week, weekday, month and time for both the start and the end.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>clock daylight-saving name recurring start end</strong>: the IOS keyword is summer-time, not daylight-saving</li><li><span class="opt-tag wrong">Option B</span> <strong>clock summer-time name date start end</strong>: date is for a one-time DST change; recurring is for the yearly rule</li><li><span class="opt-tag wrong">Option D</span> <strong>clock timezone name recurring start end</strong>: clock timezone sets the base zone, not DST</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>summer-time = DST.</li><li>recurring = every year.</li><li>date = one specific year only.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 37 Flashcards - NTP)</div></div></div>' WHERE question_no = 'Anki-IPS-4062';

-- Anki-IPS-4068 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: NTP Stratum Levels</div><p>The reference clock itself, an atomic clock or GPS receiver, is NTP (Network Time Protocol) stratum 0. Servers that sync from it are stratum 1.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>0</strong>: The reference clock itself, an atomic clock or GPS receiver, is stratum 0.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>2</strong>: stratum 2 servers sync from stratum 1</li><li><span class="opt-tag wrong">Option B</span> <strong>1</strong>: stratum 1 servers sync directly from a stratum 0 reference</li><li><span class="opt-tag wrong">Option C</span> <strong>15</strong>: stratum 15 is nearly the last usable stratum; 16 is unsynchronised</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Stratum 0 = the clock itself.</li><li>Stratum 1 = directly connected to it.</li><li>Stratum 16 = unsynchronised.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 37 Flashcards - NTP)</div></div></div>' WHERE question_no = 'Anki-IPS-4068';

-- Anki-IPS-4075 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Viewing NTP Associations</div><p>show ntp associations lists the configured NTP (Network Time Protocol) servers and peers and their state, while show ntp status shows the overall NTP health summary.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>show ntp associations</strong>: show ntp associations lists the configured NTP servers/peers and their state.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>show ntp servers</strong>: not a valid IOS command</li><li><span class="opt-tag wrong">Option C</span> <strong>show ntp status</strong>: that shows the overall NTP status: stratum, offset, whether synced</li><li><span class="opt-tag wrong">Option D</span> <strong>show ntp peers</strong>: not a valid IOS command; the list command is associations</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>associations = the list of servers.</li><li>status = the health summary.</li><li>The exam swaps them.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 37 Flashcards - NTP)</div></div></div>' WHERE question_no = 'Anki-IPS-4075';

-- Anki-IPS-4079 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Making a Device an NTP Server</div><p>ntp master [stratum] makes the device serve its own clock as an NTP (Network Time Protocol) server at the given stratum. Without a stratum, the default is 8.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>ntp master [ stratum ]</strong>: ntp master [stratum] makes the device serve its own clock as an NTP server at the given stratum.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>ntp broadcast [ stratum ]</strong>: ntp broadcast enables broadcast mode on an interface; it does not make the device a master server</li><li><span class="opt-tag wrong">Option C</span> <strong>ntp server [ stratum ]</strong>: ntp server syncs FROM another server; it does not make this device a server</li><li><span class="opt-tag wrong">Option D</span> <strong>ntp peer [ stratum ]</strong>: ntp peer configures a symmetric peer</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>master = ''I am the server''.</li><li>server = ''sync from that server''.</li><li>The two words are opposites in NTP.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 37 Flashcards - NTP)</div></div></div>' WHERE question_no = 'Anki-IPS-4079';

-- Anki-IPS-4086 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Viewing NTP Status</div><p>show ntp status shows the NTP (Network Time Protocol) state: the stratum, the reference, the offset, and whether the clock is synchronised.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>show ntp status</strong>: show ntp status shows the NTP state, stratum, reference, offset, and whether the clock is synchronised.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>show ntp config</strong>: not a valid IOS command</li><li><span class="opt-tag wrong">Option B</span> <strong>show ntp associations</strong>: that lists the configured servers/peers</li><li><span class="opt-tag wrong">Option C</span> <strong>show clock detail</strong>: that shows the software clock and its source, not the NTP status</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>status = health summary.</li><li>associations = the list.</li><li>Same split as the earlier pair.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 37 Flashcards - NTP)</div></div></div>' WHERE question_no = 'Anki-IPS-4086';

-- Anki-IPS-4090 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Windows IP Configuration</div><p>On Windows, ipconfig shows the basic IP (Internet Protocol) configuration: the address, subnet mask, default gateway and DNS (Domain Name System) servers.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>ipconfig</strong>: ipconfig on Windows shows the basic IP configuration, address, mask, gateway and DNS servers.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>ifconfig</strong>: that is the Linux/Unix command, not Windows</li><li><span class="opt-tag wrong">Option C</span> <strong>ipconfig /all</strong>: that shows the detailed configuration including MAC (Media Access Control) addresses and DHCP (Dynamic Host Configuration Protocol)/lease info</li><li><span class="opt-tag wrong">Option D</span> <strong>ip address show</strong>: that is a Linux command, not Windows</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Windows = ipconfig.</li><li>Linux = ifconfig or ip addr.</li><li>The exam tests both.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 38 Flashcards - DNS)</div></div></div>' WHERE question_no = 'Anki-IPS-4090';

-- Anki-IPS-4092 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Windows DNS Cache</div><p>Windows keeps a local DNS (Domain Name System) resolver cache. ipconfig /displaydns shows its contents, so you can see which names have already been resolved.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>ipconfig /displaydns</strong>: ipconfig /displaydns shows the contents of the local DNS resolver cache.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>ipconfig /dns</strong>: not a valid switch</li><li><span class="opt-tag wrong">Option C</span> <strong>ipconfig /flushdns</strong>: that clears the cache; it does not display it</li><li><span class="opt-tag wrong">Option D</span> <strong>nslookup</strong>: that queries a DNS server directly; it does not show the local cache</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>display = show.</li><li>flush = clear.</li><li>Pair them and you cannot mix them up.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 38 Flashcards - DNS)</div></div></div>' WHERE question_no = 'Anki-IPS-4092';

-- Anki-IPS-4094 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Windows Ping</div><p>On Windows, ping -n &lt;count&gt; sends exactly that many echo requests to the given address.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>ping ip-address -n number</strong>: On Windows, ping -n &lt;count&gt; sends exactly that many echo requests.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>ping ip-address -c number</strong>: -c is the Linux count switch; Windows uses -n</li><li><span class="opt-tag wrong">Option C</span> <strong>ping -n number ip-address</strong>: the Windows syntax puts the address first, then the switches</li><li><span class="opt-tag wrong">Option D</span> <strong>ping ip-address -t number</strong>: -t on Windows means ping until stopped; it takes no number</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Windows ping -n = number.</li><li>Linux ping -c = count.</li><li>Same idea, different letter.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 38 Flashcards - DNS)</div></div></div>' WHERE question_no = 'Anki-IPS-4094';

-- Anki-IPS-4145 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: SNMP Message Classes</div><p>SNMP (Simple Network Management Protocol) messages fall into classes: read (ask for values), write (change values), notification (agent alerts), and response (answers). The read class holds the messages that retrieve values.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>Get GetNext GetBulk</strong>: The read message class contains Get, GetNext, and GetBulk.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>Trap Inform</strong>: Trap and Inform are in the notification class, not the read class.</li><li><span class="opt-tag wrong">Option C</span> <strong>Response</strong>: Response is in the response class, not the read class.</li><li><span class="opt-tag wrong">Option D</span> <strong>Set</strong>: Set is in the write class, not the read class.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Read = Get, GetNext, GetBulk.</li><li>Write = Set.</li><li>Notification = Trap, Inform.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 40 Flashcards - SNMP)</div></div></div>' WHERE question_no = 'Anki-IPS-4145';

-- Anki-IPS-4153 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: SNMP Messages</div><p>A Trap is an alert the agent sends on its own when something happens, and the manager does not acknowledge it, so the agent never knows if it arrived.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Trap</strong>: Trap is the unacknowledged notification sent from the agent to the manager.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Inform</strong>: Inform is also a notification, but it IS acknowledged by the manager.</li><li><span class="opt-tag wrong">Option B</span> <strong>Get</strong>: Get is a read request from the manager, not a notification from the agent.</li><li><span class="opt-tag wrong">Option D</span> <strong>Set</strong>: Set is a write request from the manager, not a notification from the agent.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Trap = unacknowledged.</li><li>Inform = acknowledged.</li><li>That is the only difference.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 40 Flashcards - SNMP)</div></div></div>' WHERE question_no = 'Anki-IPS-4153';

-- Anki-IPS-4157 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: SNMP Ports</div><p>SNMP (Simple Network Management Protocol) agents listen on UDP (User Datagram Protocol) port 161 for requests from the manager (Get, GetNext, GetBulk, Set).</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>161</strong>: SNMP Agents use UDP port 161.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>162</strong>: 162 is the port managers listen on for Trap and Inform notifications.</li><li><span class="opt-tag wrong">Option B</span> <strong>514</strong>: 514 is the Syslog port, not the SNMP agent port.</li><li><span class="opt-tag wrong">Option C</span> <strong>123</strong>: 123 is the NTP (Network Time Protocol) port, not the SNMP agent port.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>161 = agent.</li><li>162 = manager.</li><li>Remember the pair.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 40 Flashcards - SNMP)</div></div></div>' WHERE question_no = 'Anki-IPS-4157';

-- Anki-IPS-4160 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: SNMP Ports</div><p>SNMP (Simple Network Management Protocol) managers listen on UDP (User Datagram Protocol) port 162 for Trap and Inform notifications sent by agents.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>162</strong>: SNMP Managers use UDP port 162.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>123</strong>: 123 is the NTP (Network Time Protocol) port, not the SNMP manager port.</li><li><span class="opt-tag wrong">Option C</span> <strong>514</strong>: 514 is the Syslog port, not the SNMP manager port.</li><li><span class="opt-tag wrong">Option D</span> <strong>161</strong>: 161 is the port agents listen on for requests from the manager.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>162 = manager.</li><li>161 = agent.</li><li>Remember the pair.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 40 Flashcards - SNMP)</div></div></div>' WHERE question_no = 'Anki-IPS-4160';

-- Anki-IPS-4163 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: SNMP Configuration</div><p>A community string is like a password for SNMP (Simple Network Management Protocol). The read-only version lets the NMS read values but not change them.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>snmp-server community password ro</strong>: The command is snmp-server community password ro.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>snmp-server location location</strong>: snmp-server location sets the device location, not a community string.</li><li><span class="opt-tag wrong">Option C</span> <strong>snmp-server contact contact-info</strong>: snmp-server contact sets contact information, not a community string.</li><li><span class="opt-tag wrong">Option D</span> <strong>snmp-server community password rw</strong>: The rw keyword makes a read-write community string, which can also change values.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>ro = read-only.</li><li>rw = read-write.</li><li>ro is safer because it cannot change anything.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 40 Flashcards - SNMP)</div></div></div>' WHERE question_no = 'Anki-IPS-4163';

-- Anki-IPS-4164 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: SNMP Configuration</div><p>A community string is like a password for SNMP (Simple Network Management Protocol). The read-write version lets the NMS read values and change them.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>snmp-server community password rw</strong>: The command is snmp-server community password rw.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>snmp-server contact contact-info</strong>: snmp-server contact sets contact information, not a community string.</li><li><span class="opt-tag wrong">Option B</span> <strong>snmp-server community password ro</strong>: The ro keyword makes a read-only community string, which cannot change values.</li><li><span class="opt-tag wrong">Option D</span> <strong>snmp-server location location</strong>: snmp-server location sets the device location, not a community string.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>rw = read-write.</li><li>ro = read-only.</li><li>Only use rw where the NMS really needs to change things.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 40 Flashcards - SNMP)</div></div></div>' WHERE question_no = 'Anki-IPS-4164';

-- Anki-IPS-4196 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Syslog Port</div><p>Syslog servers listen on a well-known UDP (User Datagram Protocol) port. Devices send their log messages to that port on the Syslog server.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>514</strong>: Syslog servers listen on UDP port 514.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>161</strong>: 161 is the SNMP (Simple Network Management Protocol) agent port, not the Syslog port.</li><li><span class="opt-tag wrong">Option C</span> <strong>162</strong>: 162 is the SNMP manager port, not the Syslog port.</li><li><span class="opt-tag wrong">Option D</span> <strong>123</strong>: 123 is the NTP (Network Time Protocol) port, not the Syslog port.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>514 = Syslog.</li><li>161/162 = SNMP.</li><li>123 = NTP.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 41 Flashcards - Syslog)</div></div></div>' WHERE question_no = 'Anki-IPS-4196';

-- Anki-IPS-4198 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Syslog Configuration</div><p>The logging console command controls which severity levels are shown on the console line, for example logging console warnings shows level 4 and below.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>logging console level</strong>: The command is logging console level.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>logging trap level</strong>: logging trap controls what is sent to a Syslog server, not the console line.</li><li><span class="opt-tag wrong">Option B</span> <strong>logging buffered [ size ] level</strong>: logging buffered controls the local log buffer, not the console line.</li><li><span class="opt-tag wrong">Option C</span> <strong>logging monitor level</strong>: logging monitor controls the VTY lines, not the console line.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>console = the console line.</li><li>monitor = VTY lines.</li><li>buffered = the buffer.</li><li>trap = the Syslog server.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 41 Flashcards - Syslog)</div></div></div>' WHERE question_no = 'Anki-IPS-4198';

-- Anki-IPS-4199 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Syslog Configuration</div><p>The logging monitor command controls which severity levels are shown on the VTY lines (Telnet/SSH sessions), for example logging monitor warnings shows level 4 and below.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>logging monitor level</strong>: The command is logging monitor level.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>logging buffered [ size ] level</strong>: logging buffered controls the local log buffer, not the VTY lines.</li><li><span class="opt-tag wrong">Option C</span> <strong>logging console level</strong>: logging console controls the console line, not the VTY lines.</li><li><span class="opt-tag wrong">Option D</span> <strong>logging trap level</strong>: logging trap controls what is sent to a Syslog server, not the VTY lines.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>monitor = VTY lines.</li><li>console = the console line.</li><li>buffered = the buffer.</li><li>trap = the Syslog server.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 41 Flashcards - Syslog)</div></div></div>' WHERE question_no = 'Anki-IPS-4199';

-- Anki-IPS-4209 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Enabling login on a line</div><p>On a line, the login command enables password checking using the password configured on that line. Without it, the device will not ask for the line password at all.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>login</strong>: login tells the line to authenticate users with the password configured on that line.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>login local</strong>: This tells the line to authenticate against the local username database instead of the line password.</li><li><span class="opt-tag wrong">Option B</span> <strong>login authentication default</strong>: This applies a named AAA (Authentication, Authorization, and Accounting) authentication list; plain login uses the line password, not an AAA list.</li><li><span class="opt-tag wrong">Option D</span> <strong>no login</strong>: This disables password checking entirely, so anyone can connect without a password.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>login = use the line password.</li><li>login local = use local usernames and passwords.</li><li>The exam loves testing the difference.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 42 Flashcards - SSH)</div></div></div>' WHERE question_no = 'Anki-IPS-4209';

-- Anki-IPS-4213 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: What Telnet stands for</div><p>Telnet is one of the oldest remote-access protocols. Its name comes from teletype network, a reference to the teletype terminals it was built to connect.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>Teletype Network</strong>: Telnet stands for Teletype Network, named after the teletype terminals of the early ARPANET era.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Telecommunication Network</strong>: This is a plausible-sounding expansion, but it is not what the name stands for.</li><li><span class="opt-tag wrong">Option C</span> <strong>Telnet Network Protocol</strong>: This just repeats the name itself; it is not the expansion of the acronym.</li><li><span class="opt-tag wrong">Option D</span> <strong>Terminal Network</strong>: This is close in meaning, but the correct expansion is Teletype Network.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Telnet = Teletype Network.</li><li>SSH (Secure Shell) = Secure Shell.</li><li>The exam asks for both expansions.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 42 Flashcards - SSH)</div></div></div>' WHERE question_no = 'Anki-IPS-4213';

-- Anki-IPS-4215 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Telnet transport protocol</div><p>Telnet is a TCP (Transmission Control Protocol)-based application. It needs a reliable, connection-oriented transport because every keystroke and every character of output must arrive in order.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>TCP</strong>: TCP: Telnet runs over TCP, which gives it the reliable, ordered delivery a terminal session needs.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>SCTP</strong>: SCTP is a different transport protocol and is not used by Telnet.</li><li><span class="opt-tag wrong">Option B</span> <strong>UDP</strong>: Telnet does not use UDP (User Datagram Protocol); it needs the reliability and ordering that only TCP provides.</li><li><span class="opt-tag wrong">Option D</span> <strong>ICMP</strong>: ICMP (Internet Control Message Protocol) is a control and error-reporting protocol, not a transport protocol for terminal sessions.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Telnet = TCP port 23.</li><li>SSH (Secure Shell) = TCP port 22.</li><li>Both are TCP because terminal sessions need reliability.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 42 Flashcards - SSH)</div></div></div>' WHERE question_no = 'Anki-IPS-4215';

-- Anki-IPS-4223 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: SSH transport protocol</div><p>Like Telnet, SSH (Secure Shell) is a TCP (Transmission Control Protocol)-based application. It needs reliable, ordered delivery for an interactive terminal session, and it adds encryption on top of TCP.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>TCP</strong>: TCP: SSH runs over TCP, which provides the reliable, ordered transport a secure terminal session needs.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>SCTP</strong>: SCTP is a different transport protocol and is not used by SSH.</li><li><span class="opt-tag wrong">Option C</span> <strong>UDP</strong>: SSH does not use UDP (User Datagram Protocol); it needs the reliability and ordering of TCP.</li><li><span class="opt-tag wrong">Option D</span> <strong>DCCP</strong>: DCCP is a different transport protocol and is not used by SSH.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>SSH = TCP port 22.</li><li>Telnet = TCP port 23.</li><li>Both are TCP applications.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 42 Flashcards - SSH)</div></div></div>' WHERE question_no = 'Anki-IPS-4223';

-- Anki-IPS-4234 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: What SSH stands for</div><p>SSH (Secure Shell) is the secure replacement for Telnet. Its name, Secure Shell, describes exactly what it does: it provides a secure shell session over the network.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Secure Shell</strong>: SSH stands for Secure Shell, the encrypted remote-access protocol that replaced Telnet.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Safe Shell</strong>: Safe Shell is not the expansion; the correct word is Secure.</li><li><span class="opt-tag wrong">Option B</span> <strong>Secure Socket Shell</strong>: Secure Socket is part of SSL/TLS terminology, not the expansion of SSH.</li><li><span class="opt-tag wrong">Option D</span> <strong>System Shell</strong>: System Shell is not the expansion; the word is Secure.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>SSH = Secure Shell.</li><li>Telnet = Teletype Network.</li><li>Know both expansions.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 42 Flashcards - SSH)</div></div></div>' WHERE question_no = 'Anki-IPS-4234';

-- Anki-IPS-4245 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: FTP versus TFTP functionality</div><p>FTP (File Transfer Protocol) supports authentication, directory listings, renaming, deleting and resuming files. TFTP (Trivial File Transfer Protocol) can only read and write whole files, so FTP is the protocol with more functionality.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>FTP</strong>: FTP: FTP provides more functionality than TFTP, including authentication, directory listings and file management.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>TFTP</strong>: TFTP is deliberately minimal; it cannot list directories or manage files.</li><li><span class="opt-tag wrong">Option B</span> <strong>HTTP</strong>: HTTP (Hypertext Transfer Protocol) is a web protocol, not a file transfer protocol in this comparison.</li><li><span class="opt-tag wrong">Option D</span> <strong>SFTP</strong>: SFTP is a different, SSH (Secure Shell)-based protocol and is not part of the FTP versus TFTP comparison.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>FTP = more functionality.</li><li>TFTP = more simplicity.</li><li>The trade-off is the whole point of having both protocols.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 43 Flashcards - FTP&amp;TFTP)</div></div></div>' WHERE question_no = 'Anki-IPS-4245';

-- Anki-IPS-4247 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: FTP control connection transport</div><p>The FTP (File Transfer Protocol) control connection must be reliable, because commands and replies cannot be lost or reordered. That is why it runs over TCP (Transmission Control Protocol).</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>TCP</strong>: TCP: FTP control connections use TCP, which provides the reliable delivery that commands need.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>UDP</strong>: FTP control does not use UDP (User Datagram Protocol); it needs the reliability of TCP.</li><li><span class="opt-tag wrong">Option B</span> <strong>ICMP</strong>: ICMP (Internet Control Message Protocol) is a control and error-reporting protocol, not a transport protocol for FTP.</li><li><span class="opt-tag wrong">Option C</span> <strong>SCTP</strong>: SCTP is a different transport protocol and is not used by FTP.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>FTP control = TCP port 21.</li><li>FTP data = TCP port 20.</li><li>Both are TCP.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 43 Flashcards - FTP&amp;TFTP)</div></div></div>' WHERE question_no = 'Anki-IPS-4247';

-- Anki-IPS-4250 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: FTP data connection transport</div><p>The FTP (File Transfer Protocol) data connection carries file contents and must deliver them reliably and in order, so it runs over TCP (Transmission Control Protocol) just like the control connection.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>TCP</strong>: TCP: FTP data connections use TCP, which provides the reliable, ordered delivery that file transfers need.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>SCTP</strong>: SCTP is a different transport protocol and is not used by FTP.</li><li><span class="opt-tag wrong">Option C</span> <strong>ICMP</strong>: ICMP (Internet Control Message Protocol) is a control and error-reporting protocol, not a transport protocol for FTP.</li><li><span class="opt-tag wrong">Option D</span> <strong>UDP</strong>: FTP data does not use UDP (User Datagram Protocol); it needs the reliability of TCP.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>FTP control = TCP port 21.</li><li>FTP data = TCP port 20.</li><li>Both are TCP.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 43 Flashcards - FTP&amp;TFTP)</div></div></div>' WHERE question_no = 'Anki-IPS-4250';

-- Anki-IPS-4252 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: TFTP transport protocol</div><p>TFTP (Trivial File Transfer Protocol) is a lightweight protocol that runs over UDP (User Datagram Protocol). It uses UDP port 69 and implements its own simple reliability with lock-step acknowledgements instead of relying on TCP (Transmission Control Protocol).</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>UDP</strong>: UDP: TFTP servers listen on UDP port 69; TFTP is a UDP-based protocol.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>TCP</strong>: TFTP does not use TCP; it runs over UDP and handles reliability itself with lock-step acknowledgements.</li><li><span class="opt-tag wrong">Option C</span> <strong>SCTP</strong>: SCTP is a different transport protocol and is not used by TFTP.</li><li><span class="opt-tag wrong">Option D</span> <strong>ICMP</strong>: ICMP (Internet Control Message Protocol) is a control and error-reporting protocol, not a transport protocol for TFTP.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>TFTP = UDP port 69.</li><li>FTP (File Transfer Protocol) = TCP ports 20 and 21.</li><li>The transport protocol is part of what makes them different.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 43 Flashcards - FTP&amp;TFTP)</div></div></div>' WHERE question_no = 'Anki-IPS-4252';

-- Anki-IPS-4257 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IOS file system types</div><p>IOS classifies file systems by type. The disk type is used for storage devices such as flash memory, where the IOS image and configuration files live.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>disk</strong>: disk: the disk file system type is used for storage devices such as flash memory.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>network</strong>: The network type represents external file systems such as FTP (File Transfer Protocol) or TFTP (Trivial File Transfer Protocol) servers, not local flash.</li><li><span class="opt-tag wrong">Option C</span> <strong>nvram</strong>: The nvram type represents the device''s internal NVRAM, not flash storage.</li><li><span class="opt-tag wrong">Option D</span> <strong>opaque</strong>: The opaque type represents logical systems used for internal functions, not flash storage.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>disk = flash memory.</li><li>opaque = internal logical systems.</li><li>nvram = NVRAM.</li><li>network = remote servers.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 43 Flashcards - FTP&amp;TFTP)</div></div></div>' WHERE question_no = 'Anki-IPS-4257';

-- Anki-IPS-4258 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IOS file system types</div><p>IOS classifies file systems by type. The opaque type represents logical systems used for internal device functions, such as the null device, rather than real storage.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>opaque</strong>: opaque: the opaque file system type represents logical systems used for internal functions.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>nvram</strong>: The nvram type represents the device''s internal NVRAM, not logical internal systems.</li><li><span class="opt-tag wrong">Option B</span> <strong>disk</strong>: The disk type is used for storage devices such as flash memory, not for logical internal systems.</li><li><span class="opt-tag wrong">Option C</span> <strong>network</strong>: The network type represents external file systems such as FTP (File Transfer Protocol) or TFTP (Trivial File Transfer Protocol) servers, not logical internal systems.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>disk = flash memory.</li><li>opaque = internal logical systems.</li><li>nvram = NVRAM.</li><li>network = remote servers.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 43 Flashcards - FTP&amp;TFTP)</div></div></div>' WHERE question_no = 'Anki-IPS-4258';

-- Anki-IPS-4259 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IOS file system types</div><p>IOS classifies file systems by type. The nvram type represents the device''s internal NVRAM, where the startup configuration is stored.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>nvram</strong>: nvram: the nvram file system type is used for the device''s internal NVRAM.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>opaque</strong>: The opaque type represents logical systems used for internal functions, not NVRAM.</li><li><span class="opt-tag wrong">Option C</span> <strong>network</strong>: The network type represents external file systems such as FTP (File Transfer Protocol) or TFTP (Trivial File Transfer Protocol) servers, not NVRAM.</li><li><span class="opt-tag wrong">Option D</span> <strong>disk</strong>: The disk type is used for storage devices such as flash memory, not for NVRAM.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>disk = flash memory.</li><li>opaque = internal logical systems.</li><li>nvram = NVRAM.</li><li>network = remote servers.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 43 Flashcards - FTP&amp;TFTP)</div></div></div>' WHERE question_no = 'Anki-IPS-4259';

-- Anki-IPS-4260 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IOS file system types</div><p>IOS classifies file systems by type. The network type represents external file systems, such as FTP (File Transfer Protocol) and TFTP (Trivial File Transfer Protocol) servers, that the device can reach over the network.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>network</strong>: network: the network file system type represents external file systems, for example FTP and TFTP servers.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>disk</strong>: The disk type is used for storage devices such as flash memory, not for remote servers.</li><li><span class="opt-tag wrong">Option B</span> <strong>opaque</strong>: The opaque type represents logical systems used for internal functions, not for remote servers.</li><li><span class="opt-tag wrong">Option C</span> <strong>nvram</strong>: The nvram type represents the device''s internal NVRAM, not for remote servers.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>disk = flash memory.</li><li>opaque = internal logical systems.</li><li>nvram = NVRAM.</li><li>network = remote servers.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 43 Flashcards - FTP&amp;TFTP)</div></div></div>' WHERE question_no = 'Anki-IPS-4260';

-- Anki-IPS-4269 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: FTP encryption</div><p>Plain FTP (File Transfer Protocol) sends usernames, passwords and files in clear text. Encryption is only added by FTPS, which runs FTP over TLS; plain FTP itself has no encryption.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>No (FTPS does)</strong>: No (FTPS does): plain FTP does not use encryption; encryption is provided by FTPS, the TLS-secured version of FTP.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Yes, with TLS by default</strong>: TLS is not enabled by default on FTP; it is FTPS that adds TLS.</li><li><span class="opt-tag wrong">Option B</span> <strong>Yes</strong>: Plain FTP has no encryption at all; usernames, passwords and files travel in clear text.</li><li><span class="opt-tag wrong">Option C</span> <strong>No (SFTP does)</strong>: SFTP is a different, SSH (Secure Shell)-based protocol; the encrypted version of FTP is FTPS.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>FTP = authentication, no encryption.</li><li>FTPS = FTP plus TLS encryption.</li><li>SFTP is a different protocol entirely.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 43 Flashcards - FTP&amp;TFTP)</div></div></div>' WHERE question_no = 'Anki-IPS-4269';

-- Anki-IPS-4277 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Static NAT</div><p>In static NAT (Network Address Translation), the administrator manually configures a one-to-one mapping between a private address and a public address. The mapping never changes and is always available.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>Static</strong>: Static: static NAT involves statically configuring one-to-one IP (Internet Protocol) address mappings.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Overload</strong>: Overload is another name for PAT (Port Address Translation), not for static NAT.</li><li><span class="opt-tag wrong">Option B</span> <strong>PAT</strong>: PAT maps many private addresses to one public address using ports; it is not a one-to-one static mapping.</li><li><span class="opt-tag wrong">Option C</span> <strong>Dynamic</strong>: Dynamic NAT assigns public addresses from a pool automatically; it is not manually configured one-to-one.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Static = one-to-one, manual, permanent.</li><li>Dynamic = from a pool, automatic.</li><li>PAT = many-to-one with ports.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 44 Flashcards - NAT (Part 1)</div></div></div>' WHERE question_no = 'Anki-IPS-4277';

-- Anki-IPS-4279 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Cisco NAT terminology</div><p>Cisco NAT (Network Address Translation) has four address terms. Inside Local is the IP (Internet Protocol) address of the inside host as seen from the inside network. In other words, its real private address.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>Inside Local</strong>: Inside Local: the inside local address is the inside host''s address from the perspective of the inside network.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Outside Local</strong>: Outside Local is the outside host''s address from the perspective of the inside network.</li><li><span class="opt-tag wrong">Option C</span> <strong>Inside Global</strong>: Inside Global is the same host''s address from the perspective of the outside network, its public address.</li><li><span class="opt-tag wrong">Option D</span> <strong>Outside Global</strong>: Outside Global is the outside host''s address from the perspective of the outside network.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Local = how the address looks from the inside.</li><li>Global = how it looks from the outside.</li><li>Inside = the inside host.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 44 Flashcards - NAT (Part 1)</div></div></div>' WHERE question_no = 'Anki-IPS-4279';

-- Anki-IPS-4287 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Showing NAT translations</div><p>The NAT (Network Address Translation) translation table shows every active mapping: the protocol, the inside local and global addresses, and the outside local and global addresses. It is the first command to run when NAT is not working.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>show ip nat translations</strong>: show ip nat translations shows the NAT translation table with all active mappings.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>show nat translations</strong>: There is no show nat translations command; the command starts with show ip nat.</li><li><span class="opt-tag wrong">Option C</span> <strong>show ip nat table</strong>: There is no show ip nat table command; the translation table is shown with show ip nat translations.</li><li><span class="opt-tag wrong">Option D</span> <strong>show ip nat statistics</strong>: This shows NAT statistics and counters, not the translation table.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>show ip nat translations = the mappings.</li><li>show ip nat statistics = the counters.</li><li>Know which one shows what.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 44 Flashcards - NAT (Part 1)</div></div></div>' WHERE question_no = 'Anki-IPS-4287';

-- Anki-IPS-4288 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Showing NAT statistics</div><p>The show ip nat statistics command displays NAT (Network Address Translation) counters: how many translations are active, how many addresses are in the pool, and how many translations have been created in total.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>show ip nat statistics</strong>: show ip nat statistics shows the NAT statistics, including active translations and pool usage.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>show nat statistics</strong>: There is no show nat statistics command; the command starts with show ip nat.</li><li><span class="opt-tag wrong">Option B</span> <strong>show ip nat pool</strong>: There is no show ip nat pool command; pool information appears in show ip nat statistics.</li><li><span class="opt-tag wrong">Option C</span> <strong>show ip nat translations</strong>: This shows the translation table, not the statistics.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>show ip nat translations = the mappings.</li><li>show ip nat statistics = the counters.</li><li>Know which one shows what.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - IP Services (CCNA / Day 44 Flashcards - NAT (Part 1)</div></div></div>' WHERE question_no = 'Anki-IPS-4288';

-- Anki-NA-2035 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: MAC Address Table</div><p>A switch builds its MAC (Media Access Control) address table by watching traffic. Entries it creates on its own, without any manual configuration, have a specific name.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Dynamic MAC address (Dynamically learned MAC address)</strong>: A MAC address learned by a switch without manual configuration is called a Dynamic MAC address (Dynamically learned MAC address). The switch learns it from the Source MAC of incoming frames.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Sticky MAC address</strong>: A sticky MAC address is a dynamic address that port security converts into a static entry, not a plain learned address.</li><li><span class="opt-tag wrong">Option B</span> <strong>Secure MAC address</strong>: A secure MAC address is tied to port security, not to normal dynamic learning.</li><li><span class="opt-tag wrong">Option D</span> <strong>Static MAC address</strong>: A static MAC address is manually configured by an administrator, the opposite of learned automatically.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Dynamic = learned from traffic.</li><li>Static = typed in by hand.</li><li>Sticky = learned, then kept by port security.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 05 Flashcards - Ethernet LAN Switching (Part 1)</div></div></div>' WHERE question_no = 'Anki-NA-2035';

-- Anki-NA-2036 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Switch Forwarding Behaviour</div><p>When a switch receives a frame whose destination MAC (Media Access Control) is not in its MAC address table, it does not know which port leads to that device. It must still try to deliver the frame.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>Floods it out all ports (except the one it was received on)</strong>: A switch floods an unknown unicast frame out all ports (except the one it was received on), so that whichever port the destination is on will receive it.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Drops the frame</strong>: A switch does not drop an unknown unicast frame; it floods it so the destination can still be reached.</li><li><span class="opt-tag wrong">Option B</span> <strong>Sends it to the default gateway</strong>: A Layer 2 switch does not use a default gateway for forwarding frames; it floods the frame.</li><li><span class="opt-tag wrong">Option C</span> <strong>Forwards it only out the uplink port</strong>: The switch does not know which port leads to the destination, so it cannot pick just one port.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Unknown unicast = flood.</li><li>Known unicast = forward out one port.</li><li>Broadcast = flood.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 05 Flashcards - Ethernet LAN Switching (Part 1)</div></div></div>' WHERE question_no = 'Anki-NA-2036';

-- Anki-NA-2065 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Duplex Modes</div><p>Duplex describes whether an interface can send and receive at the same time. The two main modes are full and half.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>full</strong>: In full duplex mode, an interface can send and receive data at the same time.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>simplex</strong>: Simplex means one-way communication only, which is not how Ethernet interfaces operate.</li><li><span class="opt-tag wrong">Option C</span> <strong>auto</strong>: Auto is the negotiation setting, not a duplex mode that describes simultaneous sending and receiving.</li><li><span class="opt-tag wrong">Option D</span> <strong>half</strong>: In half duplex mode an interface can only send or receive at one time, not both.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Full = both directions at once.</li><li>Half = one direction at a time.</li><li>Modern switch links run full duplex.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 09 Flashcards - Switch Interfaces)</div></div></div>' WHERE question_no = 'Anki-NA-2065';

-- Anki-NA-2067 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Hubs and Switches</div><p>A hub is a very simple device: it takes a signal in on one port and repeats it out of all other ports. It does not read MAC (Media Access Control) addresses or make forwarding decisions.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>1</strong>: Ethernet hubs operate at Layer 1 of the OSI model. The Physical layer. They only repeat electrical signals.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>7</strong>: Layer 7 is the Application layer; a hub has nothing to do with applications.</li><li><span class="opt-tag wrong">Option C</span> <strong>3</strong>: Layer 3 is where routers operate; a hub does not read IP (Internet Protocol) addresses.</li><li><span class="opt-tag wrong">Option D</span> <strong>2</strong>: Layer 2 is where switches operate; a hub does not read MAC addresses or make forwarding decisions.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Hub = Layer 1 (repeats signals).</li><li>Switch = Layer 2 (forwards by MAC).</li><li>Router = Layer 3 (routes by IP).</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 09 Flashcards - Switch Interfaces)</div></div></div>' WHERE question_no = 'Anki-NA-2067';

-- Anki-NA-2068 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Collision Handling</div><p>On a half-duplex shared medium, two devices can transmit at the same time and collide. Ethernet has a mechanism to detect collisions and recover from them.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>CSMA/CD</strong>: Ethernet devices use CSMA/CD (Carrier Sense Multiple Access with Collision Detection) to detect and prevent collisions on half-duplex interfaces.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>CSMA/CA</strong>: CSMA/CA (Carrier Sense Multiple Access with Collision Avoidance) (Collision Avoidance) is used by Wi-Fi, not by wired Ethernet.</li><li><span class="opt-tag wrong">Option B</span> <strong>STP (Spanning Tree Protocol)</strong>: STP prevents Layer 2 loops; it has nothing to do with detecting collisions.</li><li><span class="opt-tag wrong">Option C</span> <strong>Token passing</strong>: Token passing is used by Token Ring networks, not by Ethernet.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Wired Ethernet = CSMA/CD.</li><li>Wireless = CSMA/CA.</li><li>Do not mix them up.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 09 Flashcards - Switch Interfaces)</div></div></div>' WHERE question_no = 'Anki-NA-2068';

-- Anki-NA-2077 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Interface Error Counters</div><p>The show interfaces output has counters for different kinds of receive errors. One counter tracks frames whose structure itself is wrong. An illegal or malformed format.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>frame</strong>: The frame counter counts frames that have an incorrect/illegal format.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>giants</strong>: Giants are frames larger than the maximum frame size, not frames with an illegal format.</li><li><span class="opt-tag wrong">Option C</span> <strong>runts</strong>: Runts are frames smaller than the minimum frame size, not frames with an illegal format.</li><li><span class="opt-tag wrong">Option D</span> <strong>CRC</strong>: The CRC (Cyclic Redundancy Check) counter counts frames that failed the FCS (Frame Check Sequence) error check, not frames with an illegal format.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Frame errors = bad format.</li><li>Runts = too small.</li><li>Giants = too big.</li><li>CRC = bad checksum.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 09 Flashcards - Switch Interfaces)</div></div></div>' WHERE question_no = 'Anki-NA-2077';

-- Anki-NA-2079 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Interface Error Counters</div><p>The show interfaces output has a summary counter for the transmit side, counting frames the device attempted to send but could not.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>output errors</strong>: The output errors counter counts frames the switch tried to send, but failed due to an error.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>giants</strong>: Giants are oversized frames received, a receive-side counter, not a transmit failure.</li><li><span class="opt-tag wrong">Option B</span> <strong>runts</strong>: Runts are undersized frames received, a receive-side counter, not a transmit failure.</li><li><span class="opt-tag wrong">Option C</span> <strong>input errors</strong>: Input errors count errors on frames received, not frames the device tried to send.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Output errors = transmit failures.</li><li>Input errors = receive errors.</li><li>Read the direction in the name.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 09 Flashcards - Switch Interfaces)</div></div></div>' WHERE question_no = 'Anki-NA-2079';

-- Anki-NA-2092 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: VLAN Tagging</div><p>When a frame leaves a switch port carrying multiple VLANs, the switch must mark which VLAN (Virtual Local Area Network) the frame belongs to. Ports that do this are called tagged ports.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>Trunk</strong>: Trunk ports are known as "tagged" ports, because frames leaving them carry an 802.1Q tag with the VLAN number.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Voice</strong>: A voice VLAN rides on an access port; the port itself is not called a tagged port.</li><li><span class="opt-tag wrong">Option B</span> <strong>Dynamic</strong>: Dynamic is a DTP (Dynamic Trunking Protocol) negotiation mode, not a port type that tags frames.</li><li><span class="opt-tag wrong">Option C</span> <strong>Access</strong>: Access ports are untagged. Frames leave them without any VLAN tag.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Trunk = tagged.</li><li>Access = untagged.</li><li>The tag is a 4-byte 802.1Q header.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 17 Flashcards - VLANs (Part 2)</div></div></div>' WHERE question_no = 'Anki-NA-2092';

-- Anki-NA-2093 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: VLAN Tagging</div><p>When a frame leaves a switch port that belongs to a single VLAN (Virtual Local Area Network), the end host does not need to know about VLANs, so the frame leaves without any marking.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Access</strong>: Access ports are known as "untagged" ports, because frames leaving them carry no VLAN tag.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Voice</strong>: A voice VLAN rides on an access port; the port itself is not called an untagged port type.</li><li><span class="opt-tag wrong">Option B</span> <strong>Trunk</strong>: Trunk ports are tagged. Frames leaving them carry an 802.1Q tag.</li><li><span class="opt-tag wrong">Option D</span> <strong>Dynamic</strong>: Dynamic is a DTP (Dynamic Trunking Protocol) negotiation mode, not a port type.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Access = untagged.</li><li>Trunk = tagged.</li><li>End hosts never see VLAN tags.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 17 Flashcards - VLANs (Part 2)</div></div></div>' WHERE question_no = 'Anki-NA-2093';

-- Anki-NA-2095 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: VLAN Trunking Protocols</div><p>There are two VLAN (Virtual Local Area Network) trunking protocols: one is an open industry standard and the other is Cisco proprietary. The Cisco one wraps the whole Ethernet frame in its own header.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>ISL (Inter-Switch Link)</strong>: ISL (Inter-Switch Link) is the Cisco proprietary VLAN trunking protocol.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>DTP (Dynamic Trunking Protocol)</strong>: DTP (Dynamic Trunking Protocol) negotiates whether a link becomes a trunk; it is not itself a trunking encapsulation protocol.</li><li><span class="opt-tag wrong">Option C</span> <strong>VTP (VLAN Trunking Protocol)</strong>: VTP (VLAN Trunking Protocol) synchronizes the VLAN database between switches; it is not a trunking encapsulation protocol.</li><li><span class="opt-tag wrong">Option D</span> <strong>IEEE 802.1Q (dot1q)</strong>: 802.1Q is the industry standard trunking protocol, not the Cisco proprietary one.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>ISL = Cisco proprietary.</li><li>802.1Q = industry standard.</li><li>Modern networks use 802.1Q.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 17 Flashcards - VLANs (Part 2)</div></div></div>' WHERE question_no = 'Anki-NA-2095';

-- Anki-NA-2138 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: DTP Modes</div><p>The default DTP (Dynamic Trunking Protocol) mode changed over the years: older switches defaulted to desirable, newer ones to auto.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>auto</strong>: Interfaces on newer Cisco switches default to switchport mode dynamic auto.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>desirable</strong>: Desirable is the default on older switches; newer switches default to auto.</li><li><span class="opt-tag wrong">Option B</span> <strong>access</strong>: Access is a forced mode, not the DTP default on newer switches.</li><li><span class="opt-tag wrong">Option D</span> <strong>trunk</strong>: Trunk is a forced mode, not the DTP default on newer switches.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Newer = auto (passive).</li><li>Older = desirable (active).</li><li>Two autos will NOT form a trunk.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 19 Flashcards - DTP &amp; VTP)</div></div></div>' WHERE question_no = 'Anki-NA-2138';

-- Anki-NA-2142 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: DTP Negotiation</div><p>When two DTP (Dynamic Trunking Protocol) modes meet, the result depends on the combination. Desirable actively initiates, so two desirables form a trunk.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>trunk</strong>: Both ends are dynamic desirable, so both actively try to form a trunk. The operational mode is trunk.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>access</strong>: The ports do not stay access. Two desirable ports negotiate a trunk.</li><li><span class="opt-tag wrong">Option C</span> <strong>static access</strong>: Static access only results when neither side initiates a trunk; here both sides initiate.</li><li><span class="opt-tag wrong">Option D</span> <strong>down</strong>: The link is up and negotiating; the result is a trunk, not a down link.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Desirable + desirable = trunk.</li><li>Desirable + auto = trunk.</li><li>Desirable + trunk = trunk.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 19 Flashcards - DTP &amp; VTP)</div></div></div>' WHERE question_no = 'Anki-NA-2142';

-- Anki-NA-2156 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: VLAN Trunking Protocol</div><p>VTP (VLAN Trunking Protocol) lets you configure VLANs once on a central switch and have the VLAN (Virtual Local Area Network) database synchronised to other switches in the same VTP domain.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>VTP</strong>: VTP (VLAN Trunking Protocol) allows you to configure VLANs on a central server switch, and client switches synchronise their VLAN database to the server.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>DTP</strong>: DTP (Dynamic Trunking Protocol) negotiates trunking between two switches; it does not synchronise VLAN databases.</li><li><span class="opt-tag wrong">Option B</span> <strong>STP</strong>: STP prevents loops; it does not synchronise VLAN databases.</li><li><span class="opt-tag wrong">Option C</span> <strong>CDP</strong>: CDP (Cisco Discovery Protocol) discovers neighbouring Cisco devices; it does not synchronise VLAN databases.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>VTP = VLAN database synchronisation.</li><li>DTP = trunk negotiation.</li><li>Don&#x27;t mix them up.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 19 Flashcards - DTP &amp; VTP)</div></div></div>' WHERE question_no = 'Anki-NA-2156';

-- Anki-NA-2163 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: VTP Modes</div><p>VTP (VLAN Trunking Protocol) servers are the only mode (with transparent) that can create, change and delete VLANs.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>can</strong>: VTP servers can add, modify and delete VLANs.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>can&#x27;t</strong>: Servers can change VLANs. That is their job. Clients are the ones that cannot.</li><li><span class="opt-tag wrong">Option C</span> <strong>only with VTPv3</strong>: Servers can change VLANs in every VTP version, not only v3.</li><li><span class="opt-tag wrong">Option D</span> <strong>only in transparent mode</strong>: Transparent switches can also change VLANs, but servers can too.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Server = can change VLANs.</li><li>Client = cannot.</li><li>Transparent = can change, but does not sync.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 19 Flashcards - DTP &amp; VTP)</div></div></div>' WHERE question_no = 'Anki-NA-2163';

-- Anki-NA-2180 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Spanning Tree Protocol</div><p>Classic STP is defined by an IEEE standard. Later versions (RSTP, MSTP) have their own numbers.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>802.1D</strong>: &#x27;Classic&#x27; Spanning Tree Protocol is IEEE 802.1D.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>802.1w</strong>: 802.1w is Rapid STP (RSTP), not classic STP.</li><li><span class="opt-tag wrong">Option C</span> <strong>802.1Q</strong>: 802.1Q is the VLAN (Virtual Local Area Network) tagging standard, not STP.</li><li><span class="opt-tag wrong">Option D</span> <strong>802.3</strong>: 802.3 is the Ethernet standard, not STP.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>802.1D = classic STP.</li><li>802.1w = RSTP (Rapid Spanning Tree Protocol).</li><li>802.1s = MSTP (Multiple Spanning Tree Protocol).</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 20 Flashcards - STP (Part 1)</div></div></div>' WHERE question_no = 'Anki-NA-2180';

-- Anki-NA-2198 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: STP Port States</div><p>STP puts ports into states that decide whether they forward traffic. Designated ports are the ones that forward.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>forwarding</strong>: STP designated ports are in a forwarding state.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>listening</strong>: Listening is a transitional state where the port does not forward yet; designated ports are forwarding.</li><li><span class="opt-tag wrong">Option C</span> <strong>blocking</strong>: Blocking ports do not forward; designated ports forward.</li><li><span class="opt-tag wrong">Option D</span> <strong>learning</strong>: Learning is a transitional state where the port learns MAC (Media Access Control) addresses but does not forward yet; designated ports are forwarding.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Designated = forwarding.</li><li>Root = forwarding.</li><li>Alternate/blocking = not forwarding.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 20 Flashcards - STP (Part 1)</div></div></div>' WHERE question_no = 'Anki-NA-2198';

-- Anki-NA-2236 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: PVST+ BPDU Destination MAC</div><p>PVST+ (Per-VLAN Spanning Tree Plus) sends its BPDUs to the Cisco multicast MAC (Media Access Control) address 0100.0ccc.cccd. The extra ''d'' is the giveaway. It is the Cisco-proprietary per-VLAN (Virtual Local Area Network) spanning tree, so it uses a Cisco multicast address instead of the IEEE one.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>0100.0ccc.cccd</strong>: PVST+ BPDUs go to 0100.0ccc.cccd.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>0180.c200.0000</strong>: That is the IEEE multicast address used by standard (common) STP, not by Cisco''s PVST+.</li><li><span class="opt-tag wrong">Option B</span> <strong>0100.0ccc.ccce</strong>: That is not a PVST+ address. PVST+ uses 0100.0ccc.cccd, ending in ''d''.</li><li><span class="opt-tag wrong">Option C</span> <strong>0100.0ccc.cccc</strong>: That address is used by Cisco''s CDP (Cisco Discovery Protocol) and VTP (VLAN Trunking Protocol), not by PVST+ BPDUs.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>PVST+ = 0100.0ccc.cccd.</li><li>Standard STP = 0180.c200.0000.</li><li>The ''cccd'' ending is the Cisco one.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 21 Flashcards - STP (Part 2)</div></div></div>' WHERE question_no = 'Anki-NA-2236';

-- Anki-NA-2237 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Standard STP BPDU Destination MAC</div><p>Standard (common) STP sends its BPDUs to the IEEE multicast MAC (Media Access Control) address 0180.c200.0000. Cisco''s PVST+ (Per-VLAN Spanning Tree Plus) uses a different address, 0100.0ccc.cccd, so the two can be told apart.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>0180.c200.0000</strong>: Standard STP BPDUs go to 0180.c200.0000.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>0100.0ccc.cccd</strong>: That is the Cisco multicast address used by PVST+, not by standard IEEE STP.</li><li><span class="opt-tag wrong">Option C</span> <strong>0100.0ccc.cccc</strong>: That address is used by Cisco''s CDP (Cisco Discovery Protocol) and VTP (VLAN Trunking Protocol), not by standard STP BPDUs.</li><li><span class="opt-tag wrong">Option D</span> <strong>0180.c200.0001</strong>: That is not the STP address. Standard STP uses 0180.c200.0000, ending in four zeros.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Standard STP = 0180.c200.0000.</li><li>PVST+ = 0100.0ccc.cccd.</li><li>Mix them up and the question is lost.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 21 Flashcards - STP (Part 2)</div></div></div>' WHERE question_no = 'Anki-NA-2237';

-- Anki-NA-2249 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: STP Root Bridge Configuration</div><p>The global command spanning-tree vlan vlan-id root primary makes the switch the root bridge for that VLAN (Virtual Local Area Network) by setting its priority to 24576, or to 4096 less than the current root''s priority if that is lower.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>spanning-tree vlan vlan-id root primary</strong>: spanning-tree vlan vlan-id root primary configures the switch as the primary root for a VLAN.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>spanning-tree vlan vlan-id root secondary</strong>: That configures the switch as the secondary (backup) root, with priority 28672. Not the primary root.</li><li><span class="opt-tag wrong">Option B</span> <strong>spanning-tree vlan vlan-id cost 0</strong>: There is no cost command at global level. Cost is set per interface, and it does not make a switch the root.</li><li><span class="opt-tag wrong">Option D</span> <strong>spanning-tree vlan vlan-id priority 4096</strong>: That sets the priority directly, but it is a different command. The root primary command is the macro that does it for you.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>root primary = 24576.</li><li>root secondary = 28672.</li><li>Default priority = 32768.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 21 Flashcards - STP (Part 2)</div></div></div>' WHERE question_no = 'Anki-NA-2249';

-- Anki-NA-2278 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: RSTP Link Types</div><p>The RSTP (Rapid Spanning Tree Protocol) point-to-point link type is used for full-duplex connections between switches. Because a full-duplex link has no collisions, the two switches can negotiate a rapid transition to forwarding.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>point-to-point</strong>: The point-to-point link type is used for full-duplex connections.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>designated</strong>: Designated is a port role, not a link type.</li><li><span class="opt-tag wrong">Option B</span> <strong>shared</strong>: Shared is the link type for half-duplex connections, not full-duplex.</li><li><span class="opt-tag wrong">Option C</span> <strong>edge</strong>: Edge is the link type for a connection to an end device, not for a full-duplex switch-to-switch link.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Full-duplex = point-to-point.</li><li>Half-duplex = shared.</li><li>End device = edge.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 22 Flashcards - Rapid STP)</div></div></div>' WHERE question_no = 'Anki-NA-2278';

-- Anki-NA-2279 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: RSTP Link Types</div><p>The RSTP (Rapid Spanning Tree Protocol) shared link type is used for half-duplex connections, such as a link through a hub. Because the medium is shared and collisions are possible, rapid transition cannot be negotiated and the slow STP timers apply.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>shared</strong>: The shared link type is used for half-duplex connections.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>edge</strong>: Edge is the link type for a connection to an end device, not for a half-duplex switch link.</li><li><span class="opt-tag wrong">Option C</span> <strong>designated</strong>: Designated is a port role, not a link type.</li><li><span class="opt-tag wrong">Option D</span> <strong>point-to-point</strong>: Point-to-point is the link type for full-duplex connections, not half-duplex.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Half-duplex = shared.</li><li>Full-duplex = point-to-point.</li><li>End device = edge.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 22 Flashcards - Rapid STP)</div></div></div>' WHERE question_no = 'Anki-NA-2279';

-- Anki-NA-2283 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: EtherChannel Load Balancing</div><p>The global command port-channel load-balance method configures the EtherChannel load-balancing method on the switch. For example, port-channel load-balance src-dst-ip.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>port-channel load-balance method</strong>: port-channel load-balance method configures the EtherChannel load-balancing method.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>etherchannel load-balance method</strong>: The command starts with ''port-channel'', not ''etherchannel''. The show command uses etherchannel, the config command uses port-channel.</li><li><span class="opt-tag wrong">Option C</span> <strong>port-channel load-balance</strong>: The method keyword is missing. The command needs the method argument to say which balancing method to use.</li><li><span class="opt-tag wrong">Option D</span> <strong>channel-group load-balance method</strong>: channel-group is the interface command that adds a port to a group. It does not configure load balancing.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Show = show etherchannel load-balance.</li><li>Configure = port-channel load-balance.</li><li>Do not mix the two.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 23 Flashcards - EtherChannel)</div></div></div>' WHERE question_no = 'Anki-NA-2283';

-- Anki-NA-2284 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: PAgP</div><p>PAgP (Port Aggregation Protocol) stands for Port Aggregation Protocol. It is Cisco''s proprietary EtherChannel negotiation protocol. The two ends negotiate to form the channel automatically.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>Port Aggregation Protocol</strong>: PAgP stands for Port Aggregation Protocol.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Port Access Group Protocol</strong>: The middle words are Aggregation Protocol, not Access Group. PAgP aggregates ports.</li><li><span class="opt-tag wrong">Option C</span> <strong>Packet Aggregation Protocol</strong>: It aggregates ports, not packets. The first word is Port.</li><li><span class="opt-tag wrong">Option D</span> <strong>Port Aggregation Group Protocol</strong>: There is no ''Group'' in the expansion. It is Port Aggregation Protocol.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>PAgP = Cisco proprietary.</li><li>LACP (Link Aggregation Control Protocol) = industry standard.</li><li>That contrast is a favourite exam question.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 23 Flashcards - EtherChannel)</div></div></div>' WHERE question_no = 'Anki-NA-2284';

-- Anki-NA-2285 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: LACP</div><p>LACP (Link Aggregation Control Protocol) stands for Link Aggregation Control Protocol. It is the IEEE 802.3ad industry-standard EtherChannel negotiation protocol, so it works between Cisco and non-Cisco switches.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>Link Aggregation Control Protocol</strong>: LACP stands for Link Aggregation Control Protocol.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Link Access Control Protocol</strong>: The middle word is Aggregation, not Access. LACP aggregates links.</li><li><span class="opt-tag wrong">Option B</span> <strong>Link Aggregation Configuration Protocol</strong>: The last word is Control, not Configuration. LACP controls the negotiation of the channel.</li><li><span class="opt-tag wrong">Option C</span> <strong>Layer Aggregation Control Protocol</strong>: The first word is Link, not Layer. LACP aggregates links.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>LACP = industry standard (802.3ad).</li><li>PAgP (Port Aggregation Protocol) = Cisco proprietary.</li><li>Know both expansions word for word.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 23 Flashcards - EtherChannel)</div></div></div>' WHERE question_no = 'Anki-NA-2285';

-- Anki-NA-2286 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: EtherChannel Protocols</div><p>PAgP (Port Aggregation Protocol) is Cisco''s proprietary EtherChannel negotiation protocol. It only works between Cisco devices. LACP (Link Aggregation Control Protocol) is the open standard alternative.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>PAgP</strong>: PAgP is the Cisco proprietary EtherChannel protocol.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>LACP</strong>: LACP is the IEEE 802.3ad industry standard. It works between any vendors, so it is the opposite of proprietary.</li><li><span class="opt-tag wrong">Option B</span> <strong>802.3ad</strong>: 802.3ad is the IEEE standard number for LACP. The open standard, not a Cisco proprietary protocol.</li><li><span class="opt-tag wrong">Option C</span> <strong>Static EtherChannel</strong>: Static EtherChannel uses no negotiation protocol at all. The channel is forced on with mode ''on''.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Proprietary = PAgP.</li><li>Standard = LACP (802.3ad).</li><li>Static = no protocol, mode on.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 23 Flashcards - EtherChannel)</div></div></div>' WHERE question_no = 'Anki-NA-2286';

-- Anki-NA-2287 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: EtherChannel Protocols</div><p>LACP (Link Aggregation Control Protocol) is the IEEE 802.3ad industry-standard EtherChannel negotiation protocol, so it works between Cisco switches and other vendors'' switches.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>LACP</strong>: LACP is the industry-standard EtherChannel protocol.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>PAgP</strong>: PAgP (Port Aggregation Protocol) is Cisco''s proprietary protocol. It only works between Cisco devices.</li><li><span class="opt-tag wrong">Option B</span> <strong>Static EtherChannel</strong>: Static EtherChannel uses no negotiation protocol at all. The channel is forced on with mode ''on''.</li><li><span class="opt-tag wrong">Option C</span> <strong>802.1Q</strong>: 802.1Q is the VLAN (Virtual Local Area Network) trunking standard, not an EtherChannel protocol.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Standard = LACP (802.3ad).</li><li>Proprietary = PAgP.</li><li>Static = no protocol, mode on.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 23 Flashcards - EtherChannel)</div></div></div>' WHERE question_no = 'Anki-NA-2287';

-- Anki-NA-2288 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: LACP Standard</div><p>LACP (Link Aggregation Control Protocol) is defined in IEEE 802.3ad (now part of 802.1AX). It is the industry-standard protocol for negotiating an EtherChannel between switches.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>802.3ad</strong>: LACP is IEEE 802.3ad.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>802.3ab</strong>: 802.3ab is the 1000BASE-T Gigabit Ethernet over copper standard, not LACP.</li><li><span class="opt-tag wrong">Option C</span> <strong>802.1w</strong>: 802.1w is Rapid STP, not LACP.</li><li><span class="opt-tag wrong">Option D</span> <strong>802.1s</strong>: 802.1s is Multiple STP (MST), not LACP.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>802.3ad = LACP.</li><li>802.1w = RSTP (Rapid Spanning Tree Protocol).</li><li>802.1s = MST (Multiple Spanning Tree).</li><li>Do not mix the 802 numbers.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 23 Flashcards - EtherChannel)</div></div></div>' WHERE question_no = 'Anki-NA-2288';

-- Anki-NA-2328 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: CDP Configuration</div><p>CDP (Cisco Discovery Protocol) is enabled globally by default on Cisco devices, but it can be turned off globally and back on again from global configuration mode.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>cdp run</strong>: cdp run enables CDP globally (from global configuration mode).</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>no cdp run</strong>: cdp enable is the interface-level command, not the global one.</li><li><span class="opt-tag wrong">Option C</span> <strong>cdp start</strong>: no cdp run disables CDP globally. The opposite of what the question asks.</li><li><span class="opt-tag wrong">Option D</span> <strong>cdp enable</strong>: There is no cdp start command; the global command is cdp run.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Global = cdp run.</li><li>Interface = cdp enable.</li><li>Keep the two apart.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 36 Flashcards - CDP &amp; LLDP)</div></div></div>' WHERE question_no = 'Anki-NA-2328';

-- Anki-NA-2330 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: CDP Configuration</div><p>The CDP (Cisco Discovery Protocol) timer sets how often a device sends CDP advertisements. The default is 60 seconds, but it can be changed globally.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>cdp timer seconds</strong>: cdp timer seconds configures the CDP message timer (from global configuration mode).</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>cdp holdtime seconds</strong>: cdp holdtime seconds sets how long neighbours keep the information, not how often it is sent.</li><li><span class="opt-tag wrong">Option C</span> <strong>cdp timer interval</strong>: The command uses the keyword seconds, not interval.</li><li><span class="opt-tag wrong">Option D</span> <strong>cdp interval seconds</strong>: The command is cdp timer seconds, not cdp interval seconds.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>timer = how often we send.</li><li>holdtime = how long neighbours keep it.</li><li>The keywords match the words in the question.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 36 Flashcards - CDP &amp; LLDP)</div></div></div>' WHERE question_no = 'Anki-NA-2330';

-- Anki-NA-2331 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: CDP Configuration</div><p>The CDP (Cisco Discovery Protocol) holdtime tells neighbours how long to keep CDP information before discarding it. The default is 180 seconds.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>cdp holdtime seconds</strong>: cdp holdtime seconds configures the CDP hold time (from global configuration mode).</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>cdp timer seconds</strong>: cdp timer seconds sets how often advertisements are sent, not how long they are kept.</li><li><span class="opt-tag wrong">Option B</span> <strong>cdp hold seconds</strong>: The command uses the keyword seconds, not interval.</li><li><span class="opt-tag wrong">Option D</span> <strong>cdp holdtime interval</strong>: The command is cdp holdtime seconds; hold alone is not a valid keyword.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>holdtime = how long neighbours remember us.</li><li>timer = how often we speak.</li><li>Do not mix the two commands.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 36 Flashcards - CDP &amp; LLDP)</div></div></div>' WHERE question_no = 'Anki-NA-2331';

-- Anki-NA-2336 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: LLDP Multicast Address</div><p>LLDP (Link Layer Discovery Protocol) advertisements are sent as Layer 2 multicast frames to a fixed IEEE multicast MAC (Media Access Control) address, so every LLDP-capable neighbour on the segment receives them.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>0180.C200.000E</strong>: LLDP messages are sent to the multicast MAC address 0180.C200.000E.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>0100.0CCC.CCCC</strong>: 0100.0CCC.CCCC is the CDP (Cisco Discovery Protocol) multicast address, not the LLDP one.</li><li><span class="opt-tag wrong">Option C</span> <strong>0100.0CCC.CCCD</strong>: 0180.C200.000F is a different IEEE reserved multicast address; LLDP uses .000E.</li><li><span class="opt-tag wrong">Option D</span> <strong>0180.C200.000F</strong>: 0100.0CCC.CCCD is a Cisco multicast address used by other protocols, not LLDP.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>LLDP = 0180.C200.000E.</li><li>CDP = 0100.0CCC.CCCC.</li><li>The 0180 start is the LLDP giveaway.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 36 Flashcards - CDP &amp; LLDP)</div></div></div>' WHERE question_no = 'Anki-NA-2336';

-- Anki-NA-2344 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: LLDP Configuration</div><p>The LLDP (Link Layer Discovery Protocol) holdtime tells neighbours how long to keep LLDP information before discarding it. The default is 120 seconds.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>lldp holdtime seconds</strong>: lldp holdtime seconds configures the LLDP hold time (from global configuration mode).</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>lldp hold seconds</strong>: lldp timer seconds sets how often advertisements are sent, not how long they are kept.</li><li><span class="opt-tag wrong">Option B</span> <strong>lldp timer seconds</strong>: The command uses the keyword seconds, not interval.</li><li><span class="opt-tag wrong">Option C</span> <strong>lldp holdtime interval</strong>: The command is lldp holdtime seconds; hold alone is not a valid keyword.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>holdtime = how long neighbours remember us.</li><li>timer = how often we speak.</li><li>Same pair as CDP (Cisco Discovery Protocol).</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 36 Flashcards - CDP &amp; LLDP)</div></div></div>' WHERE question_no = 'Anki-NA-2344';

-- Anki-NA-2363 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Wave Properties</div><p>Frequency counts how often a wave repeats: the number of complete up/down cycles in one second. Higher frequency means more cycles per second.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Frequency</strong>: Frequency measures the number of up/down cycles per a given unit of time.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Wavelength</strong>: Amplitude is the maximum strength of the wave, not how often it cycles.</li><li><span class="opt-tag wrong">Option B</span> <strong>Amplitude</strong>: Wavelength is the distance between two peaks, not the number of cycles per second.</li><li><span class="opt-tag wrong">Option D</span> <strong>Period</strong>: Period is the time for one cycle. The inverse of frequency, not the count of cycles.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Frequency = cycles per second.</li><li>Period is its opposite: seconds per cycle.</li><li>Frequency = 1 / Period.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 55 Flashcards - Wireless Fundamentals)</div></div></div>' WHERE question_no = 'Anki-NA-2363';

-- Anki-NA-2366 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Frequency Units</div><p>Frequency units use metric prefixes: kilo means one thousand. A kilohertz is one thousand cycles per second.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>Kilohertz</strong>: kHz stands for Kilohertz. 1,000 cycles per second.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>Kilohertzs</strong>: Kilobertz is a misspelling; the correct spelling is Kilohertz.</li><li><span class="opt-tag wrong">Option C</span> <strong>Kilobertz</strong>: Kiloherz is a misspelling; the correct spelling is Kilohertz, with a ''t''.</li><li><span class="opt-tag wrong">Option D</span> <strong>Kiloherz</strong>: Kilohertzs is not a word; the plural of Hertz is still Hertz.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>k = kilo = 1,000.</li><li>kHz = 1,000 Hz.</li><li>The spelling is Hertz with a ''t''.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 55 Flashcards - Wireless Fundamentals)</div></div></div>' WHERE question_no = 'Anki-NA-2366';

-- Anki-NA-2367 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Frequency Units</div><p>Frequency units use metric prefixes: mega means one million. A megahertz is one million cycles per second.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>Megahertz</strong>: MHz stands for Megahertz. 1,000,000 cycles per second.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Megabertz</strong>: Megabertz is a misspelling; the correct spelling is Megahertz.</li><li><span class="opt-tag wrong">Option C</span> <strong>Megaherz</strong>: Megaherz is a misspelling; the correct spelling is Megahertz, with a ''t''.</li><li><span class="opt-tag wrong">Option D</span> <strong>Megahertzs</strong>: Megahertzs is not a word; the plural of Hertz is still Hertz.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>M = mega = 1,000,000.</li><li>MHz = 1,000,000 Hz.</li><li>Wi-Fi channels are measured in MHz.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 55 Flashcards - Wireless Fundamentals)</div></div></div>' WHERE question_no = 'Anki-NA-2367';

-- Anki-NA-2406 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Basic Service Area</div><p>The area around an AP (Access Point) where its signal is usable is the Basic Service Area (BSA). The coverage footprint of one AP.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>BSA (Basic Service Area)</strong>: The usable signal area around an AP is called its BSA (Basic Service Area).</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>BSS (Basic Service Set)</strong>: The BSS (Basic Service Set) is the AP plus its clients, not the physical coverage area; the area itself is the BSA.</li><li><span class="opt-tag wrong">Option C</span> <strong>ESS (Extended Service Set)</strong>: An ESS (Extended Service Set) is several BSSs joined together, not the coverage area of a single AP.</li><li><span class="opt-tag wrong">Option D</span> <strong>cell</strong>: ''Cell'' is a cellular-network term; in 802.11 the coverage area is called a BSA.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>BSA = coverage area.</li><li>BSS = AP + clients.</li><li>ESS = multiple BSSs.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 55 Flashcards - Wireless Fundamentals)</div></div></div>' WHERE question_no = 'Anki-NA-2406';

-- Anki-NA-2448 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: CAPWAP Control Tunnel</div><p>CAPWAP (Control and Provisioning of Wireless Access Points) control tunnels use UDP (User Datagram Protocol) port 5246. The control tunnel carries management traffic between the AP (Access Point) and the WLC (Wireless LAN Controller) and is encrypted by default.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>Control</strong>: The control tunnel uses UDP port 5246.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option D</span> <strong>Data</strong>: Data tunnels use UDP port 5247; the control tunnel uses 5246.</li><li><span class="opt-tag wrong">Option C</span> <strong>Management</strong>: There is no separate CAPWAP management tunnel; the two tunnels are control (5246) and data (5247).</li><li><span class="opt-tag wrong">Option B</span> <strong>Control and Data</strong>: Only the control tunnel uses 5246; the data tunnel uses 5247.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>5246 = Control.</li><li>5247 = Data.</li><li>Remember: control comes first, lower number.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 56 Flashcards - Wireless Architectures)</div></div></div>' WHERE question_no = 'Anki-NA-2448';

-- Anki-NA-2451 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: CAPWAP Data Tunnel</div><p>CAPWAP (Control and Provisioning of Wireless Access Points) data tunnels use UDP (User Datagram Protocol) port 5247. The data tunnel carries client traffic between the AP (Access Point) and the WLC (Wireless LAN Controller) and is not encrypted by default.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Data</strong>: The data tunnel uses UDP port 5247.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>Control</strong>: Control tunnels use UDP port 5246; the data tunnel uses 5247.</li><li><span class="opt-tag wrong">Option A</span> <strong>Management</strong>: There is no separate CAPWAP management tunnel; the two tunnels are control (5246) and data (5247).</li><li><span class="opt-tag wrong">Option D</span> <strong>Control and Data</strong>: Only the data tunnel uses 5247; the control tunnel uses 5246.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>5247 = Data.</li><li>5246 = Control.</li><li>Lower number, control; higher number, data.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 56 Flashcards - Wireless Architectures)</div></div></div>' WHERE question_no = 'Anki-NA-2451';

-- Anki-NA-2459 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Lightweight AP Switch Port</div><p>Lightweight APs connect to a switch via access ports, because client traffic is carried inside the CAPWAP (Control and Provisioning of Wireless Access Points) tunnels to the WLC (Wireless LAN Controller), so the switch port only needs one VLAN (Virtual Local Area Network).</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>access</strong>: Lightweight APs use access ports; their traffic is tunnelled to the WLC over CAPWAP.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option C</span> <strong>trunk</strong>: Trunk ports are for autonomous APs, which need several VLANs for several SSIDs; lightweight APs tunnel everything to the WLC.</li><li><span class="opt-tag wrong">Option D</span> <strong>access and trunk</strong>: Lightweight APs connect via access ports only; they do not need trunk ports.</li><li><span class="opt-tag wrong">Option A</span> <strong>native</strong>: The native VLAN is a trunk concept; a lightweight AP (Access Point) link is a plain access port.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Lightweight AP = access port.</li><li>Autonomous AP = trunk port.</li><li>A favourite exam contrast.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 56 Flashcards - Wireless Architectures)</div></div></div>' WHERE question_no = 'Anki-NA-2459';

-- Anki-NA-2464 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Rogue Detector AP Mode</div><p>Rogue Detector mode is dedicated to listening to traffic on the wired network to detect rogue APs that are plugged into the LAN.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Rogue Detector</strong>: Rogue Detector mode watches the wired network for rogue devices.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>Monitor</strong>: Monitor mode listens on the wireless side; Rogue Detector listens on the wired side.</li><li><span class="opt-tag wrong">Option A</span> <strong>Sniffer</strong>: Sniffer mode captures wireless frames for analysis; Rogue Detector watches wired traffic.</li><li><span class="opt-tag wrong">Option D</span> <strong>SE-Connect</strong>: SE-Connect is for RF spectrum analysis, not rogue detection on the wired network.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Rogue Detector = wired side.</li><li>Monitor = wireless side.</li><li>Both hunt rogues, from opposite directions.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 56 Flashcards - Wireless Architectures)</div></div></div>' WHERE question_no = 'Anki-NA-2464';

-- Anki-NA-2490 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: 802.1X Supplicant</div><p>In 802.1X, the supplicant is the device that wants to connect to the network. The client asking for access.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>Supplicant</strong>: The supplicant is the device requesting network access.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option D</span> <strong>Authenticator</strong>: The authenticator is the device that provides access (the switch or AP), not the one asking for it.</li><li><span class="opt-tag wrong">Option C</span> <strong>Authentication Server</strong>: The authentication server receives credentials and decides to permit or deny; it is not the device asking for access.</li><li><span class="opt-tag wrong">Option B</span> <strong>RADIUS server</strong>: A RADIUS (Remote Authentication Dial-In User Service) server usually plays the authentication-server role; the device asking for access is the supplicant.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Supplicant = the client asking in.</li><li>Authenticator = the gate.</li><li>Authentication server = the judge.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 57 Flashcards - Wireless Security)</div></div></div>' WHERE question_no = 'Anki-NA-2490';

-- Anki-NA-2491 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: 802.1X Authenticator</div><p>In 802.1X, the authenticator is the device that provides access to the network. Typically the switch port or the AP (Access Point) the client connects to.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Authenticator</strong>: The authenticator is the device that grants (or blocks) access to the network.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Supplicant</strong>: The supplicant is the device that wants to connect, not the one providing access.</li><li><span class="opt-tag wrong">Option D</span> <strong>Authentication Server</strong>: The authentication server decides permit or deny; the authenticator is the device enforcing that decision at the port.</li><li><span class="opt-tag wrong">Option B</span> <strong>RADIUS server</strong>: A RADIUS (Remote Authentication Dial-In User Service) server usually plays the authentication-server role; the authenticator is the switch or AP.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Authenticator = the gate (switch/AP).</li><li>Supplicant = the client.</li><li>Authentication server = the judge.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 57 Flashcards - Wireless Security)</div></div></div>' WHERE question_no = 'Anki-NA-2491';

-- Anki-NA-2501 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: PEAP Certificates</div><p>PEAP only requires a certificate on the authentication server. The server proves its identity with the certificate, and the client then authenticates with a username and password inside the TLS tunnel.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>AS only</strong>: In PEAP only the AS (Authentication Server) requires a certificate; the supplicant does not need one.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Supplicant only</strong>: The supplicant (client) does not need a certificate in PEAP; it authenticates with credentials.</li><li><span class="opt-tag wrong">Option B</span> <strong>Neither - PEAP uses a pre-shared key</strong>: PEAP does not use a pre-shared key; it uses a server certificate plus client credentials.</li><li><span class="opt-tag wrong">Option C</span> <strong>AS and supplicant</strong>: Both sides needing a certificate is EAP (Extensible Authentication Protocol)-TLS, not PEAP.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>PEAP = server certificate only.</li><li>EAP-TLS = certificates on both sides.</li><li>That contrast is a classic exam question.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 57 Flashcards - Wireless Security)</div></div></div>' WHERE question_no = 'Anki-NA-2501';

-- Anki-NA-2522 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: DHCP Option 43</div><p>When a lightweight AP (Access Point) boots, it needs to find its WLC (Wireless LAN Controller). DHCP (Dynamic Host Configuration Protocol) option 43 (vendor-specific information) can carry the WLC&#x27;s IP (Internet Protocol) address to the AP so it can join the controller without manual configuration.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>43</strong>: DHCP option 43 can be used to tell APs the IP address of their WLC.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Option 66</strong>: Option 66 gives a TFTP (Trivial File Transfer Protocol) server name, not the WLC address.</li><li><span class="opt-tag wrong">Option B</span> <strong>Option 60</strong>: Option 60 is the vendor class identifier the AP sends to the DHCP server, not the option that carries the WLC address.</li><li><span class="opt-tag wrong">Option C</span> <strong>Option 150</strong>: Option 150 gives the TFTP server address (used for AP image downloads), not the WLC address.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Option 43 = WLC address for APs.</li><li>Option 150 = TFTP server.</li><li>Do not mix them up.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 58 Flashcards - Wireless Configuration)</div></div></div>' WHERE question_no = 'Anki-NA-2522';

-- Anki-NA-2541 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Web Authentication Layer</div><p>Web authentication redirects the user to a web page where they log in with a browser. That login happens over IP (Internet Protocol)/HTTP (Hypertext Transfer Protocol), so it operates at Layer 3, unlike WPA (Wi-Fi Protected Access) and 802.1X which work at Layer 2.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>3</strong>: Web Authentication is a Layer 3 security mechanism.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>4</strong>: Layer 4 security is things like TLS/SSL; web authentication itself is classified as Layer 3.</li><li><span class="opt-tag wrong">Option C</span> <strong>7</strong>: Layer 7 is the application layer; web authentication is classified as a Layer 3 mechanism on the WLC (Wireless LAN Controller).</li><li><span class="opt-tag wrong">Option D</span> <strong>2</strong>: Layer 2 security is WPA, WEP and 802.1X; web authentication happens over IP, so it is Layer 3.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Web auth = Layer 3.</li><li>WPA/802.1X/WEP = Layer 2.</li><li>That contrast is a favourite exam question.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 58 Flashcards - Wireless Configuration)</div></div></div>' WHERE question_no = 'Anki-NA-2541';

-- Anki-NA-2577 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: BPDU Filter</div><p>BPDU (Bridge Protocol Data Unit) Filter prevents a switch port from sending BPDUs at all. It is used on ports where BPDUs should never go out, for example a PortFast port facing an end device that might react badly to BPDUs.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>BPDU Filter</strong>: BPDU Filter prevents a switch port from sending BPDUs.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>Root Guard</strong>: Root Guard blocks a port that receives a superior BPDU; it does not stop BPDUs being sent.</li><li><span class="opt-tag wrong">Option C</span> <strong>BPDU Guard</strong>: BPDU Guard err-disables a port that receives a BPDU; it does not stop BPDUs being sent.</li><li><span class="opt-tag wrong">Option D</span> <strong>PortFast</strong>: PortFast skips STP states; it still sends BPDUs.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>BPDU Filter = no BPDUs out.</li><li>BPDU Guard = err-disable if a BPDU comes in.</li><li>They are opposites in direction.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Access (CCNA / Day 21-2 Flashcards - BPDU Guard &amp; BPDU Filter)</div></div></div>' WHERE question_no = 'Anki-NA-2577';

-- Anki-NF-1001 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: What Is a Computer Network</div><p>A computer network is a group of interconnected devices that communicate with each other to share resources such as files, printers and internet access.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>nodes</strong>: The devices connected to a network are called nodes. Every node, whether it is a PC, a phone, a printer or a router, can share and use resources on the network.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>hosts</strong>: A host is an end device on a network, but not every node is a host. Routers and switches are nodes too.</li><li><span class="opt-tag wrong">Option A</span> <strong>clients</strong>: A client is only one role a device can play (requesting a service); a network is made of all connected devices, not just clients.</li><li><span class="opt-tag wrong">Option C</span> <strong>packets</strong>: Packets are the units of data that travel across a network, not the devices that make up the network.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Node = any device connected to the network.</li><li>Host = an end device.</li><li>Every host is a node, but not every node is a host.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 01 Flashcards - Network Devices)</div></div>
</div>' WHERE question_no = 'Anki-NF-1001';

-- Anki-NF-1006 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Network Device Symbols - Server</div><p>A server is a device that provides functions or services to clients, such as web pages, files, email or DNS (Domain Name System). It usually runs 24/7 and waits for client requests.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>Server</strong>: The symbol in the exhibit represents a server: the device that hosts a service and responds to client requests.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Client</strong>: A client requests a service; the server is the one that provides it.</li><li><span class="opt-tag wrong">Option C</span> <strong>Router</strong>: A router forwards packets between networks; it does not host services for clients.</li><li><span class="opt-tag wrong">Option B</span> <strong>Switch</strong>: A switch connects hosts inside a LAN; it does not provide application services.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Server = provides.</li><li>Client = requests.</li><li>A single device can do both at different times.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 01 Flashcards - Network Devices)</div></div>
</div>' WHERE question_no = 'Anki-NF-1006';

-- Anki-NF-1009 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Server Role</div><p>A server is a device or program that provides a function or service. Such as a website, a file share or email. To other devices (clients) that request it.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>server</strong>: By definition, a server provides functions or services for clients. It listens for requests and responds to them.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option C</span> <strong>client</strong>: A client requests a service; the server is the one that provides it.</li><li><span class="opt-tag wrong">Option B</span> <strong>host</strong>: Host is a generic name for any networked device; it does not say the device provides a service.</li><li><span class="opt-tag wrong">Option D</span> <strong>workstation</strong>: A workstation is a user PC, which normally acts as a client, not as a server.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Server = provides.</li><li>Client = requests.</li><li>Remember the direction of the request.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 01 Flashcards - Network Devices)</div></div>
</div>' WHERE question_no = 'Anki-NF-1009';

-- Anki-NF-1011 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: LAN - Local Area Network</div><p>A LAN is a network that covers a small geographic area, such as a home, an office or a campus building, and is usually owned and managed by one organisation.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>Local Area Network</strong>: LAN stands for Local Area Network. A small, local network connecting hosts in one place, typically using switches and Ethernet.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>Large Area Network</strong>: There is no such standard term; a large network spanning cities or countries is a WAN (Wide Area Network).</li><li><span class="opt-tag wrong">Option A</span> <strong>Local Access Network</strong>: This sounds similar but is not the standard expansion of LAN.</li><li><span class="opt-tag wrong">Option C</span> <strong>Linked Area Network</strong>: This is not a recognised networking term.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>LAN = Local (small area).</li><li>WAN = Wide (large area).</li><li>MAN = Metropolitan (a city).</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 01 Flashcards - Network Devices)</div></div>
</div>' WHERE question_no = 'Anki-NF-1011';

-- Anki-NF-1012 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Switch - Connecting a LAN</div><p>A switch connects end hosts inside the same LAN. It learns which MAC (Media Access Control) address lives on each port and forwards each frame only to the correct port.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>switch</strong>: A switch provides connectivity to hosts within the same LAN. That is its job. Hosts in the same LAN talk to each other through the switch.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option C</span> <strong>router</strong>: A router connects different networks together; it is not used to connect hosts inside one LAN.</li><li><span class="opt-tag wrong">Option B</span> <strong>hub</strong>: A hub is a legacy device that floods traffic out of all ports; modern LANs use switches.</li><li><span class="opt-tag wrong">Option A</span> <strong>firewall</strong>: A firewall filters traffic by rules; it does not provide basic connectivity between hosts.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Same LAN = switch.</li><li>Different networks = router.</li><li>Filtering traffic = firewall.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 01 Flashcards - Network Devices)</div></div>
</div>' WHERE question_no = 'Anki-NF-1012';

-- Anki-NF-1013 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Switch Ports</div><p>A switch is built to connect many end hosts at once, so it has many network interfaces (ports). Typically 24 or 48 on a single switch.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>switch</strong>: A switch has many network interfaces so that many end hosts can connect to the same LAN through one device.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>router</strong>: A router usually has only a few interfaces, because it connects whole networks, not individual hosts.</li><li><span class="opt-tag wrong">Option D</span> <strong>hub</strong>: A hub also had many ports, but it is an obsolete device that has been replaced by switches.</li><li><span class="opt-tag wrong">Option A</span> <strong>modem</strong>: A modem has one or two interfaces and connects a LAN to the internet, not many hosts to each other.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Many ports = switch.</li><li>Few ports = router.</li><li>That is one of the easiest ways to tell them apart.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 01 Flashcards - Network Devices)</div></div>
</div>' WHERE question_no = 'Anki-NF-1013';

-- Anki-NF-1018 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Firewall</div><p>A firewall is a security device placed at the edge of a network. It inspects traffic and allows or blocks it according to the rules an administrator configures.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>firewall</strong>: A firewall monitors and controls network traffic based on configured rules. That is its defining job.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>router</strong>: A router forwards traffic between networks; it does not inspect and filter it by security rules.</li><li><span class="opt-tag wrong">Option D</span> <strong>switch</strong>: A switch forwards frames inside a LAN; it does not control traffic by policy.</li><li><span class="opt-tag wrong">Option B</span> <strong>load balancer</strong>: A load balancer spreads traffic across several servers; it does not block traffic by security rules.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Firewall = traffic cop with a rulebook.</li><li>Router = postman between networks.</li><li>Switch = postman inside one LAN.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 01 Flashcards - Network Devices)</div></div>
</div>' WHERE question_no = 'Anki-NF-1018';

-- Anki-NF-1019 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Host-Based Firewall</div><p>Firewalls come in two main forms: network-based firewalls sit at the network edge and protect a whole network, while host-based firewalls run as software on one machine and protect just that host.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>Host-based</strong>: Host-based firewalls are software applications that run on a single host, such as a PC, and filter the traffic entering and exiting that machine.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option C</span> <strong>Network-based</strong>: A network-based firewall is a separate device protecting a whole network, not software on one PC.</li><li><span class="opt-tag wrong">Option B</span> <strong>Cloud-based</strong>: A cloud-based firewall runs in a provider''s cloud; it does not run on the host itself.</li><li><span class="opt-tag wrong">Option A</span> <strong>Application-based</strong>: This describes what is filtered (applications), not where the firewall runs.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Host-based = on the host (e.g.</li><li>Windows Firewall).</li><li>Network-based = on the network edge (e.g.</li><li>Cisco ASA).</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 01 Flashcards - Network Devices)</div></div>
</div>' WHERE question_no = 'Anki-NF-1019';

-- Anki-NF-1021 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Cisco Firepower</div><p>Cisco Firepower is Cisco''s next-generation firewall (NGFW) platform. It combines a traditional firewall with intrusion prevention, application awareness and URL (Uniform Resource Locator) filtering.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>Firewall</strong>: Cisco Firepower is a firewall. Specifically a next-generation firewall that adds deep inspection to classic firewall filtering.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option D</span> <strong>Router</strong>: Cisco routers are ISR and ASR; Firepower is a security device, not a router.</li><li><span class="opt-tag wrong">Option B</span> <strong>Switch</strong>: Cisco switches are Catalyst; Firepower does not switch LAN traffic.</li><li><span class="opt-tag wrong">Option C</span> <strong>Intrusion prevention system</strong>: Firepower includes IPS as one of its features, but the device itself is a next-generation firewall.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Firepower = Cisco''s NGFW.</li><li>ASA = Cisco''s classic firewall.</li><li>Both are firewalls.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 01 Flashcards - Network Devices)</div></div>
</div>' WHERE question_no = 'Anki-NF-1021';

-- Anki-NF-1023 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: RJ45 Connector</div><p>Ethernet UTP (Unshielded Twisted Pair) cables use the RJ45 connector. The familiar 8-pin plug that clicks into the Ethernet port of a PC, switch or router.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>RJ45</strong>: The connector on the end of an Ethernet UTP cable is an RJ45. It has 8 pins, one for each wire in the cable.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>RJ11</strong>: RJ11 is the smaller 6-pin connector used for telephone cables, not Ethernet.</li><li><span class="opt-tag wrong">Option C</span> <strong>BNC</strong>: BNC is a bayonet connector used with old coaxial cable, not UTP.</li><li><span class="opt-tag wrong">Option B</span> <strong>LC</strong>: LC is a small connector used for fiber-optic cables, not copper UTP.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>RJ45 = 8 pins, Ethernet copper.</li><li>RJ11 = 6 pins, telephone.</li><li>LC = fiber.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1023';

-- Anki-NF-1025 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Bits and Bytes</div><p>A byte is the basic unit of storage, and it is made of 8 bits. This is the foundation for everything else in networking: speeds are measured in bits, file sizes in bytes.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>8</strong>: There are 8 bits in 1 byte. This is a fixed standard in computing and networking.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option C</span> <strong>4</strong>: Four bits is called a nibble. Half a byte, not a full byte.</li><li><span class="opt-tag wrong">Option A</span> <strong>10</strong>: Ten is the base of the decimal system, but a byte is defined as 8 bits, not 10.</li><li><span class="opt-tag wrong">Option D</span> <strong>16</strong>: Sixteen bits is 2 bytes, not 1 byte.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>1 byte = 8 bits.</li><li>4 bits = 1 nibble.</li><li>Never confuse bits (b) with bytes (B).</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1025';

-- Anki-NF-1026 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Measuring Network Speed</div><p>Network speed is always measured in bits per second (bps), not bytes. A 100 Mbps link moves 100 million bits per second. Which is only 12.5 megabytes per second.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>bits</strong>: Network speeds are measured in bits per second. Bandwidth is about how many individual bits travel across the link each second.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>bytes</strong>: Bytes measure storage and file sizes; link speed is measured in bits, and 1 byte = 8 bits.</li><li><span class="opt-tag wrong">Option D</span> <strong>packets</strong>: Packets are units of data, not a unit of speed. You cannot measure a link in packets per second as its rated speed.</li><li><span class="opt-tag wrong">Option B</span> <strong>frames</strong>: Frames are Layer 2 data units; speed is measured in bits per second, not frames.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Speed = bits per second (bps).</li><li>File size = bytes (B).</li><li>A 100 Mbps link downloads at about 12.5 MB/s.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1026';

-- Anki-NF-1027 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Kilobit</div><p>In networking, metric prefixes are decimal: kilo means 1,000, mega means 1,000,000 and giga means 1,000,000,000. This is different from computer memory, where 1 KB is often 1,024 bytes.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>1,000 (one thousand)</strong>: 1 kilobit is 1,000 bits (one thousand). Networking uses the decimal definition, not the binary 1,024 used for memory.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option C</span> <strong>1,024</strong>: 1,024 is the binary value used for memory (1 KiB = 1,024 bytes); network speeds use decimal 1,000.</li><li><span class="opt-tag wrong">Option B</span> <strong>100</strong>: One hundred bits is far too small. Kilo means one thousand.</li><li><span class="opt-tag wrong">Option A</span> <strong>10,000</strong>: Ten thousand bits is 10 kilobits, not 1 kilobit.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Networking = decimal: 1 kb = 1,000 bits.</li><li>Memory = binary: 1 KiB = 1,024 bytes.</li><li>The exam tests this difference.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1027';

-- Anki-NF-1031 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IEEE 802.3 - Ethernet Standard</div><p>Ethernet is defined by the IEEE 802.3 standard, first published in 1983. It covers the physical cabling, signalling and the frame format used on wired LANs.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>802.3</strong>: Ethernet was originally defined in the IEEE 802.3 standard in 1983. The 802.3 family still defines every wired Ethernet variant today.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option D</span> <strong>802.11</strong>: 802.11 is the Wi-Fi (wireless LAN) standard, not wired Ethernet.</li><li><span class="opt-tag wrong">Option A</span> <strong>802.1Q</strong>: 802.1Q defines VLAN (Virtual Local Area Network) tagging, not the Ethernet standard itself.</li><li><span class="opt-tag wrong">Option C</span> <strong>802.1X</strong>: 802.1X defines port-based network access control (authentication), not Ethernet.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>802.3 = Ethernet (wired).</li><li>802.11 = Wi-Fi (wireless).</li><li>802.1Q = VLANs.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1031';

-- Anki-NF-1039 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IEEE 802.3ab - 1000BASE-T</div><p>IEEE 802.3ab defines Gigabit Ethernet over copper twisted pair (1000BASE-T), running at 1 Gbps using all four wire pairs.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>802.3ab</strong>: IEEE 802.3ab defines 1 Gbps Ethernet over copper (1000BASE-T).</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>802.3u</strong>: 802.3u defines 100 Mbps Ethernet (100BASE-T), not Gigabit.</li><li><span class="opt-tag wrong">Option D</span> <strong>802.3z</strong>: 802.3z defines 1 Gbps Ethernet over fiber, not over copper.</li><li><span class="opt-tag wrong">Option C</span> <strong>802.3an</strong>: 802.3an defines 10 Gbps Ethernet over copper (10GBASE-T).</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>ab = 1 Gbps copper (uses all 4 pairs).</li><li>z = 1 Gbps fiber.</li><li>Do not mix them up.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1039';

-- Anki-NF-1040 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IEEE 802.3an - 10GBASE-T</div><p>IEEE 802.3an defines 10 Gigabit Ethernet over copper twisted pair (10GBASE-T), running at 10 Gbps over Cat6a cabling.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>802.3an</strong>: IEEE 802.3an defines 10 Gbps Ethernet over copper (10GBASE-T).</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>802.3ab</strong>: 802.3ab defines 1 Gbps Ethernet over copper (1000BASE-T).</li><li><span class="opt-tag wrong">Option C</span> <strong>802.3ae</strong>: 802.3ae defines 10 Gigabit Ethernet over fiber, not over copper.</li><li><span class="opt-tag wrong">Option A</span> <strong>802.3z</strong>: 802.3z defines 1 Gbps Ethernet over fiber.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>an = 10 Gbps copper.</li><li>ae = 10 Gbps fiber.</li><li>The "T" in 10GBASE-T means twisted pair (copper).</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1040';

-- Anki-NF-1041 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: UTP - Unshielded Twisted Pair</div><p>UTP (Unshielded Twisted Pair) is the common copper cable in LANs: four pairs of wires, twisted to cancel interference, with no metal shielding around them. That makes it cheap and easy to install.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Unshielded Twisted Pair</strong>: UTP stands for Unshielded Twisted Pair. The pairs are twisted, and there is no shielding around them.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>Shielded Twisted Pair</strong>: Shielded Twisted Pair is STP, the version that does have a metal shield. The opposite of UTP.</li><li><span class="opt-tag wrong">Option D</span> <strong>Unshielded Twin Pair</strong>: The correct word is "Twisted", not "Twin". The pairs are twisted together.</li><li><span class="opt-tag wrong">Option A</span> <strong>Universal Twisted Pair</strong>: There is no such standard term; the U stands for Unshielded.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>UTP = Unshielded Twisted Pair.</li><li>STP = Shielded Twisted Pair.</li><li>The first letter tells you about the shield.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1041';

-- Anki-NF-1047 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Full-Duplex Communication</div><p>Duplex describes whether a link can send and receive at the same time. Full-duplex means both directions at once; half-duplex means one direction at a time; simplex means one direction only.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>full-duplex</strong>: A full-duplex connection allows both devices to send and receive data at the same time. That is the definition of full-duplex.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>half-duplex</strong>: Half-duplex allows sending OR receiving, but not both at the same time. Devices must take turns.</li><li><span class="opt-tag wrong">Option C</span> <strong>simplex</strong>: Simplex is one-way only, like a radio broadcast. The receiver can never send back.</li><li><span class="opt-tag wrong">Option A</span> <strong>auto-duplex</strong>: There is no duplex mode called auto-duplex; auto-negotiation is what agrees the speed and duplex.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Full = both ways at once.</li><li>Half = one way at a time.</li><li>Modern switched Ethernet is always full-duplex.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1047';

-- Anki-NF-1049 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: FastEthernet Pins - Router Receive</div><p>A router is an MDI device: it transmits on pins 1-2 and receives on pins 3-6. The device at the other end must do the opposite, which is why a straight-through cable works between a router and a switch.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>3 and 6</strong>: A router receives data on pins 3 and 6 in a FastEthernet connection.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option C</span> <strong>1 and 2</strong>: Pins 1 and 2 are the router''s transmit pins, not its receive pins.</li><li><span class="opt-tag wrong">Option D</span> <strong>4 and 5</strong>: Pins 4 and 5 are not used at all in 10/100 Mbps Ethernet.</li><li><span class="opt-tag wrong">Option A</span> <strong>7 and 8</strong>: Pins 7 and 8 are not used at all in 10/100 Mbps Ethernet.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><p>Router:</p><ul><li>TX = 1-2, RX = 3-6.</li><li>Switch: TX = 3-6, RX = 1-2.</li><li>Opposite pairs make straight-through cables work.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1049';

-- Anki-NF-1058 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Crossover Cable - Like Devices</div><p>A crossover cable connects each pin pair to the opposite pair on the other end. It is used between like devices. Two MDI devices or two MDI-X devices. Because both would otherwise transmit on the same pins.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>crossover cable</strong>: Two routers are like devices (both MDI, both transmit on 1-2), so a crossover cable is needed to cross the transmit and receive pairs.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>straight-through cable</strong>: A straight-through cable between two routers would connect transmit to transmit, and the link would not work.</li><li><span class="opt-tag wrong">Option B</span> <strong>rollover cable</strong>: A rollover cable is for console connections, not for connecting two routers.</li><li><span class="opt-tag wrong">Option C</span> <strong>fiber-optic cable</strong>: Fiber-optic is a cable type (glass), not a pinout. The question is about the UTP (Unshielded Twisted Pair) wiring pattern.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Like devices = crossover.</li><li>Unlike devices = straight-through.</li><li>Router-router, switch-switch, PC-PC are all like pairs.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1058';

-- Anki-NF-1060 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Straight-Through Cable Definition</div><p>A straight-through cable wires each pin pair to the same pair on the other end (pin 1 to pin 1, pin 2 to pin 2, and so on). It connects unlike devices, such as a PC to a switch.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>straight-through cable</strong>: A straight-through cable connects a pin pair on one end to the same pair on the other end. That is its definition.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option D</span> <strong>crossover cable</strong>: A crossover cable connects a pair to the opposite pair on the other end, not the same pair.</li><li><span class="opt-tag wrong">Option C</span> <strong>rollover cable</strong>: A rollover cable reverses the whole pin order (pin 1 to pin 8) and is used for console connections.</li><li><span class="opt-tag wrong">Option A</span> <strong>console cable</strong>: A console cable is a type of rollover cable used for management access, not a same-pair Ethernet cable.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Straight-through = same to same.</li><li>Crossover = crossed over.</li><li>Rollover = fully reversed.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1060';

-- Anki-NF-1065 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: SFP Transceiver</div><p>Fiber-optic cables connect to a router or switch through a small hot-swappable transceiver called an SFP (Small Form-Factor Pluggable). The SFP converts between the optical signal and the electrical signal.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>SFP (Small Form-Factor Pluggable)</strong>: Fiber-optic cables plug into SFP transceivers in a router or switch. The SFP is the small module that the fiber connector clicks into.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option D</span> <strong>GBIC</strong>: GBIC is the older, larger transceiver that SFP replaced; modern devices use SFP, not GBIC.</li><li><span class="opt-tag wrong">Option C</span> <strong>RJ45</strong>: RJ45 is the copper Ethernet connector; fiber-optic cables do not use RJ45.</li><li><span class="opt-tag wrong">Option A</span> <strong>BNC</strong>: BNC is a coaxial cable connector; it has nothing to do with fiber-optic connections.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Fiber = SFP (small, hot-swappable).</li><li>Copper = RJ45.</li><li>GBIC is the old big version of SFP.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1065';

-- Anki-NF-1068 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Multimode Fiber - Multiple Light Modes</div><p>In multimode fiber, the wide core lets light waves enter at multiple angles, so several modes (paths) of light travel down the core at the same time.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>Multimode</strong>: Multimode fiber cables allow multiple angles (modes) of light waves to enter the fiberglass core. That is what "multimode" means.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>Single-mode</strong>: Single-mode fiber allows only one angle of light, travelling straight down the core.</li><li><span class="opt-tag wrong">Option C</span> <strong>Hybrid-mode</strong>: There is no standard fiber type called hybrid-mode.</li><li><span class="opt-tag wrong">Option A</span> <strong>Dual-mode</strong>: There is no standard fiber type called dual-mode.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Multi = many modes.</li><li>Single = one mode.</li><li>The name tells you the answer.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1068';

-- Anki-NF-1069 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Single-Mode vs Multimode Distance</div><p>Single-mode fiber carries one beam of light straight down a narrow core, so the signal stays clean over very long distances. Up to tens of kilometres. Multimode light bounces around and disperses, limiting it to hundreds of metres.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>single-mode</strong>: Single-mode fiber allows longer cables than multimode, because its single straight light path suffers far less dispersion over distance.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option C</span> <strong>multimode</strong>: Multimode is limited to shorter runs (typically up to 550 metres) because its many light modes spread out over distance.</li><li><span class="opt-tag wrong">Option D</span> <strong>plastic fiber</strong>: Plastic fiber is a different, short-range medium and is not one of the two main fiber kinds.</li><li><span class="opt-tag wrong">Option B</span> <strong>hybrid fiber</strong>: There is no standard fiber type called hybrid fiber.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Long distance = single-mode.</li><li>Short distance = multimode.</li><li>Single-mode wins on distance, multimode wins on price.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1069';

-- Anki-NF-1073 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IEEE 802.3z - 1000BASE-LX</div><p>IEEE 802.3z defines Gigabit Ethernet over fiber, including 1000BASE-SX (short wavelength, multimode) and 1000BASE-LX (long wavelength, single-mode or multimode).</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>802.3z</strong>: 1000BASE-LX was defined in the IEEE 802.3z standard.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option D</span> <strong>802.3ab</strong>: 802.3ab defines 1 Gigabit Ethernet over copper (1000BASE-T), not fiber.</li><li><span class="opt-tag wrong">Option A</span> <strong>802.3an</strong>: 802.3an defines 10 Gigabit Ethernet over copper (10GBASE-T).</li><li><span class="opt-tag wrong">Option B</span> <strong>802.3ae</strong>: 802.3ae defines 10 Gigabit Ethernet over fiber, not 1 Gigabit.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>z = 1 Gig fiber.</li><li>LX = long wavelength.</li><li>SX = short wavelength.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1073';

-- Anki-NF-1075 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: 10GBASE-SR Maximum Length</div><p>10GBASE-SR is the short-range 10 Gigabit fiber standard, designed for data-centre links over multimode fiber. Its maximum reach is 400 metres.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>400 meters</strong>: 10GBASE-SR has a maximum cable length of 400 meters (over multimode fiber).</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option C</span> <strong>100 meters</strong>: 100 metres is the UTP (Unshielded Twisted Pair) copper limit, not the 10GBASE-SR reach.</li><li><span class="opt-tag wrong">Option D</span> <strong>550 meters</strong>: 550 metres is the 1000BASE-LX / 1000BASE-SX multimode reach, not 10GBASE-SR.</li><li><span class="opt-tag wrong">Option A</span> <strong>10 kilometers</strong>: 10 kilometres is the 10GBASE-LR reach, the long-range version, not SR.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>SR = Short Range (400 m).</li><li>LR = Long Range (10 km).</li><li>ER = Extended Range (30 km).</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1075';

-- Anki-NF-1092 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: OSI Layer 4 - Host-to-Host Communication</div><p>Layer 4, the Transport layer, provides end-to-end (host-to-host) communication: it moves data from a process on one host to a process on another host, reliably (TCP) or quickly (UDP).</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>Layer 4 - Transport</strong>: Layer 4. The Transport layer. Provides host-to-host communication between end hosts.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option C</span> <strong>Layer 3 - Network</strong>: Layer 3 provides network-to-network communication (routing between networks), not host-to-host delivery.</li><li><span class="opt-tag wrong">Option B</span> <strong>Layer 5 - Session</strong>: Layer 5 manages sessions between applications, not host-to-host transport.</li><li><span class="opt-tag wrong">Option A</span> <strong>Layer 2 - Data Link</strong>: Layer 2 provides node-to-node delivery on a single local link, not host-to-host across a network.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Host-to-host = Transport (Layer 4).</li><li>Network-to-network = Network (Layer 3).</li><li>Node-to-node = Data Link (Layer 2).</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 03 Flashcards - OSI Model, TCP/IP Suite)</div></div>
</div>' WHERE question_no = 'Anki-NF-1092';

-- Anki-NF-1096 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Routers Operate at Layer 3</div><p>A router forwards packets between networks using logical IP (Internet Protocol) addressing, which is a Layer 3 function. That is why routers are called Layer 3 devices.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>3</strong>: Routers operate at Layer 3 of the OSI model. The Network layer. Because they route packets using IP addresses.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option C</span> <strong>2</strong>: Layer 2 is the Data Link layer, where switches operate using MAC (Media Access Control) addresses.</li><li><span class="opt-tag wrong">Option A</span> <strong>4</strong>: Layer 4 is the Transport layer, where TCP (Transmission Control Protocol) and UDP (User Datagram Protocol) operate. Not routers.</li><li><span class="opt-tag wrong">Option D</span> <strong>7</strong>: Layer 7 is the Application layer, where user applications operate. Not routers.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Router = Layer 3.</li><li>Switch = Layer 2.</li><li>Firewall = usually Layer 3/4 (or higher for NGFW).</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 03 Flashcards - OSI Model, TCP/IP Suite)</div></div>
</div>' WHERE question_no = 'Anki-NF-1096';

-- Anki-NF-1097 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: OSI Layer 3 - Logical Addressing</div><p>Layer 3, the Network layer, provides logical addressing. IP (Internet Protocol) addresses. Unlike MAC (Media Access Control) addresses, which are fixed to the hardware, IP addresses are logical and can change with the network.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>Layer 3 - Network</strong>: Layer 3. The Network layer. Provides logical addressing (IP addresses) used to identify hosts across networks.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option C</span> <strong>Layer 2 - Data Link</strong>: Layer 2 provides physical addressing (MAC addresses) on a local link, not logical IP addressing.</li><li><span class="opt-tag wrong">Option A</span> <strong>Layer 4 - Transport</strong>: Layer 4 uses port numbers to identify processes, not IP addresses.</li><li><span class="opt-tag wrong">Option B</span> <strong>Layer 7 - Application</strong>: Layer 7 provides services to applications; it does not define addressing.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Logical addressing = IP = Layer 3.</li><li>Physical addressing = MAC = Layer 2.</li><li>Ports = Layer 4.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 03 Flashcards - OSI Model, TCP/IP Suite)</div></div>
</div>' WHERE question_no = 'Anki-NF-1097';

-- Anki-NF-1174 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
<div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv4 Special Addresses - Network Address</div><p>In any IPv4 (Internet Protocol version 4) network, the address with all host bits set to 0 is the network address. It identifies the network itself and cannot be assigned to a host.</p></div>
<div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>network address</strong>: network address is correct because an address with the host portion all 0s identifies the network itself.</li></ul></div>
<div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>broadcast address</strong>: A broadcast address has all host bits set to 1, not 0. It is the opposite of the network address.</li><li><span class="opt-tag wrong">Option B</span> <strong>multicast address</strong>: A multicast address is in the Class D range (224-239); it is not defined by the host bits being all 0s.</li><li><span class="opt-tag wrong">Option C</span> <strong>host address</strong>: A host address has a mix of 0s and 1s in the host portion; all 0s is reserved as the network address.</li></ul></div>
<div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>All 0s in the host part = network address.</li><li>All 1s in the host part = broadcast address.</li><li>These two are never assigned to hosts.</li></ul></div>
<div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 07 Flashcards - IPv4 Addresses (Part 1)</div></div>
</div>' WHERE question_no = 'Anki-NF-1174';

-- Anki-NF-1175 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
<div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv4 Special Addresses - Broadcast Address</div><p>In any IPv4 (Internet Protocol version 4) network, the address with all host bits set to 1 is the broadcast address. Traffic sent to it reaches every host on that network.</p></div>
<div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>broadcast address</strong>: broadcast address is correct because an address with the host portion all 1s is the broadcast address of the network.</li></ul></div>
<div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>host address</strong>: A host address has a mix of 0s and 1s in the host portion; all 1s is reserved as the broadcast address.</li><li><span class="opt-tag wrong">Option B</span> <strong>network address</strong>: A network address has all host bits set to 0, not 1. It is the opposite of the broadcast address.</li><li><span class="opt-tag wrong">Option C</span> <strong>loopback address</strong>: A loopback address is in the 127.0.0.0/8 range; it is not defined by the host bits being all 1s.</li></ul></div>
<div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>All 0s in the host part = network address.</li><li>All 1s in the host part = broadcast address.</li><li>These two are never assigned to hosts.</li></ul></div>
<div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 07 Flashcards - IPv4 Addresses (Part 1)</div></div>
</div>' WHERE question_no = 'Anki-NF-1175';

-- Anki-NF-1188 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
<div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Cisco Interfaces - Administratively Down by Default</div><p>On Cisco routers, interfaces are administratively down (shutdown) by default. You must issue &quot;no shutdown&quot; to bring them up. On Cisco switches, interfaces are up by default.</p></div>
<div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>routers</strong>: routers is correct because router interfaces are administratively down by default.</li></ul></div>
<div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>switches</strong>: Switch interfaces are up by default, not administratively down. It is router interfaces that start shut down.</li><li><span class="opt-tag wrong">Option B</span> <strong>wireless access points</strong>: Wireless access points do not have the same default shutdown behaviour as router interfaces.</li><li><span class="opt-tag wrong">Option D</span> <strong>firewalls</strong>: Firewalls are not the device type in this rule. The rule is about Cisco router interfaces.</li></ul></div>
<div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Router = down by default (needs &quot;no shutdown&quot;).</li><li>Switch = up by default.</li><li>This difference is a classic exam question.</li></ul></div>
<div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 08 Flashcards - IPv4 Addresses (Part 2)</div></div>
</div>' WHERE question_no = 'Anki-NF-1188';

-- Anki-NF-1189 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
<div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Cisco Interfaces - NOT Down by Default</div><p>On Cisco switches, interfaces are up by default. They come up as soon as a cable is connected. On Cisco routers, interfaces are administratively down by default and need &quot;no shutdown&quot;.</p></div>
<div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>switches</strong>: switches is correct because switch interfaces are NOT administratively down by default. They are up by default.</li></ul></div>
<div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>routers</strong>: Router interfaces are administratively down by default. The opposite of switches.</li><li><span class="opt-tag wrong">Option B</span> <strong>firewalls</strong>: Firewalls are not the device type in this rule. The rule is about Cisco switch interfaces.</li><li><span class="opt-tag wrong">Option C</span> <strong>hubs</strong>: Hubs are simple Layer 1 repeaters with no configuration or shutdown state; the rule is about switches.</li></ul></div>
<div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Router = down by default (needs &quot;no shutdown&quot;).</li><li>Switch = up by default.</li><li>This difference is a classic exam question.</li></ul></div>
<div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 08 Flashcards - IPv4 Addresses (Part 2)</div></div>
</div>' WHERE question_no = 'Anki-NF-1189';

-- Anki-NF-1198 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv4 Header: IHL Units</div><p>The IHL (Internet Header Length) value is not a byte count; it is a count of 32-bit words. You multiply the IHL value by 4 to get the header length in bytes.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>4-byte (32 bit)</strong>: IHL measures the header length in 4-byte (32-bit) increments, so an IHL of 5 means 5 x 4 = 20 bytes, the minimum IPv4 (Internet Protocol version 4) header.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>1-byte (8 bit)</strong>: IHL is not counted in single bytes; it counts 32-bit words.</li><li><span class="opt-tag wrong">Option B</span> <strong>2-byte (16 bit)</strong>: IHL is not counted in 16-bit units; the unit is 32 bits.</li><li><span class="opt-tag wrong">Option C</span> <strong>8-byte (64 bit)</strong>: IHL is not counted in 64-bit units; the unit is 32 bits.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><p>Exam shortcut:</p><ul><li>header bytes = IHL value x 4.</li><li>IHL 5 = 20 bytes, IHL 15 = 60 bytes.</li><li>You will use this on almost every header question.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📋 IPv4 Header - Full Reference (Memorize This):</div><table style="width:100%;border-collapse:collapse;margin-top:8px;font-size:13px;"><tr><td colspan="4" style="border:1px solid #4a5568;padding:6px;text-align:center;">Version<br><span style="font-size:12px;">4 bits</span></td><td colspan="4" style="border:1px solid #4a5568;padding:6px;text-align:center;">IHL<br><span style="font-size:12px;">4 bits</span></td><td colspan="6" style="border:1px solid #4a5568;padding:6px;text-align:center;">DSCP<br><span style="font-size:12px;">6 bits</span></td><td colspan="2" style="border:1px solid #4a5568;padding:6px;text-align:center;">ECN<br><span style="font-size:12px;">2 bits</span></td><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Total Length<br><span style="font-size:12px;">16 bits</span></td></tr><tr><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Identification<br><span style="font-size:12px;">16 bits</span></td><td colspan="3" style="border:1px solid #4a5568;padding:6px;text-align:center;">Flags<br><span style="font-size:12px;">3 bits</span></td><td colspan="13" style="border:1px solid #4a5568;padding:6px;text-align:center;">Fragment Offset<br><span style="font-size:12px;">13 bits</span></td></tr><tr><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">TTL<br><span style="font-size:12px;">8 bits</span></td><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">Protocol<br><span style="font-size:12px;">8 bits</span></td><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Header Checksum<br><span style="font-size:12px;">16 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Source Address<br><span style="font-size:12px;">32 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Destination Address<br><span style="font-size:12px;">32 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Options + Padding<br><span style="font-size:12px;">0-40 bytes</span></td></tr></table><div style="font-size:14px;line-height:1.7;margin-top:10px;"><div style="margin-bottom:7px;"><strong>Version</strong> <span style="opacity:0.75;">(4 bits)</span>: IP version (4)</div><div style="margin-bottom:7px;"><strong>IHL (Internet Header Length)</strong> <span style="opacity:0.75;">(4 bits)</span>: Header length in 32-bit words (5-15); IHL × 4 = header bytes (20-60)</div><div style="margin-bottom:7px;"><strong>DSCP (Differentiated Services Code Point)</strong> <span style="opacity:0.75;">(6 bits)</span>: QoS marking (0-63)</div><div style="margin-bottom:7px;"><strong>ECN (Explicit Congestion Notification)</strong> <span style="opacity:0.75;">(2 bits)</span>: Congestion notification (0-3)</div><div style="margin-bottom:7px;"><strong>Total Length</strong> <span style="opacity:0.75;">(16 bits)</span>: Whole packet length in bytes, header + data (max 65,535)</div><div style="margin-bottom:7px;"><strong>Identification</strong> <span style="opacity:0.75;">(16 bits)</span>: Same ID for all fragments of one packet</div><div style="margin-bottom:7px;"><strong>Flags</strong> <span style="opacity:0.75;">(3 bits)</span>: Reserved (0), DF (Don''t Fragment), MF (More Fragments)</div><div style="margin-bottom:7px;"><strong>Fragment Offset</strong> <span style="opacity:0.75;">(13 bits)</span>: Position of this fragment in the original packet (in 8-byte units)</div><div style="margin-bottom:7px;"><strong>TTL (Time to Live)</strong> <span style="opacity:0.75;">(8 bits)</span>: Max hops; each router subtracts 1, drops the packet at 0</div><div style="margin-bottom:7px;"><strong>Protocol</strong> <span style="opacity:0.75;">(8 bits)</span>: Next protocol: 1 = ICMP (Internet Control Message Protocol), 6 = TCP (Transmission Control Protocol), 17 = UDP (User Datagram Protocol), 89 = OSPF (Open Shortest Path First)</div><div style="margin-bottom:7px;"><strong>Header Checksum</strong> <span style="opacity:0.75;">(16 bits)</span>: Error check on the header only (recalculated at each hop)</div><div style="margin-bottom:7px;"><strong>Source Address</strong> <span style="opacity:0.75;">(32 bits)</span>: Sender IPv4 (Internet Protocol version 4) address</div><div style="margin-bottom:7px;"><strong>Destination Address</strong> <span style="opacity:0.75;">(32 bits)</span>: Receiver IPv4 address</div><div style="margin-bottom:7px;"><strong>Options</strong> <span style="opacity:0.75;">(0-40 bytes)</span>: Rarely used (e.g. Record Route, Timestamp); Padding pads the header to a multiple of 32 bits</div></div><p style="margin-top:8px;">Total: 20 bytes minimum, up to 60 bytes with Options. IHL × 4 = header length in bytes.</p></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 10 Flashcards - IPv4 Header)</div></div></div>' WHERE question_no = 'Anki-NF-1198';

-- Anki-NF-1208 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv4 Header: Congestion Notification</div><p>ECN (Explicit Congestion Notification) provides end-to-end notification of network congestion: a router marks the packet instead of dropping it, and the receiver tells the sender to slow down.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>ECN</strong>: ECN is the field that provides end-to-end notification of network congestion.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Header Checksum</strong>: The checksum only detects header errors; it does not report congestion.</li><li><span class="opt-tag wrong">Option B</span> <strong>DSCP</strong>: DSCP (Differentiated Services Code Point) marks traffic priority for QoS (Quality of Service); it does not signal congestion.</li><li><span class="opt-tag wrong">Option C</span> <strong>Total Length</strong>: Total Length only states the packet size; it carries no congestion signal.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Congestion notification = ECN.</li><li>Priority marking = DSCP.</li><li>Keep the two jobs separate.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📋 IPv4 Header - Full Reference (Memorize This):</div><table style="width:100%;border-collapse:collapse;margin-top:8px;font-size:13px;"><tr><td colspan="4" style="border:1px solid #4a5568;padding:6px;text-align:center;">Version<br><span style="font-size:12px;">4 bits</span></td><td colspan="4" style="border:1px solid #4a5568;padding:6px;text-align:center;">IHL<br><span style="font-size:12px;">4 bits</span></td><td colspan="6" style="border:1px solid #4a5568;padding:6px;text-align:center;">DSCP<br><span style="font-size:12px;">6 bits</span></td><td colspan="2" style="border:1px solid #4a5568;padding:6px;text-align:center;">ECN<br><span style="font-size:12px;">2 bits</span></td><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Total Length<br><span style="font-size:12px;">16 bits</span></td></tr><tr><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Identification<br><span style="font-size:12px;">16 bits</span></td><td colspan="3" style="border:1px solid #4a5568;padding:6px;text-align:center;">Flags<br><span style="font-size:12px;">3 bits</span></td><td colspan="13" style="border:1px solid #4a5568;padding:6px;text-align:center;">Fragment Offset<br><span style="font-size:12px;">13 bits</span></td></tr><tr><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">TTL<br><span style="font-size:12px;">8 bits</span></td><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">Protocol<br><span style="font-size:12px;">8 bits</span></td><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Header Checksum<br><span style="font-size:12px;">16 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Source Address<br><span style="font-size:12px;">32 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Destination Address<br><span style="font-size:12px;">32 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Options + Padding<br><span style="font-size:12px;">0-40 bytes</span></td></tr></table><div style="font-size:14px;line-height:1.7;margin-top:10px;"><div style="margin-bottom:7px;"><strong>Version</strong> <span style="opacity:0.75;">(4 bits)</span>: IP version (4)</div><div style="margin-bottom:7px;"><strong>IHL (Internet Header Length)</strong> <span style="opacity:0.75;">(4 bits)</span>: Header length in 32-bit words (5-15); IHL × 4 = header bytes (20-60)</div><div style="margin-bottom:7px;"><strong>DSCP (Differentiated Services Code Point)</strong> <span style="opacity:0.75;">(6 bits)</span>: QoS marking (0-63)</div><div style="margin-bottom:7px;"><strong>ECN (Explicit Congestion Notification)</strong> <span style="opacity:0.75;">(2 bits)</span>: Congestion notification (0-3)</div><div style="margin-bottom:7px;"><strong>Total Length</strong> <span style="opacity:0.75;">(16 bits)</span>: Whole packet length in bytes, header + data (max 65,535)</div><div style="margin-bottom:7px;"><strong>Identification</strong> <span style="opacity:0.75;">(16 bits)</span>: Same ID for all fragments of one packet</div><div style="margin-bottom:7px;"><strong>Flags</strong> <span style="opacity:0.75;">(3 bits)</span>: Reserved (0), DF (Don''t Fragment), MF (More Fragments)</div><div style="margin-bottom:7px;"><strong>Fragment Offset</strong> <span style="opacity:0.75;">(13 bits)</span>: Position of this fragment in the original packet (in 8-byte units)</div><div style="margin-bottom:7px;"><strong>TTL (Time to Live)</strong> <span style="opacity:0.75;">(8 bits)</span>: Max hops; each router subtracts 1, drops the packet at 0</div><div style="margin-bottom:7px;"><strong>Protocol</strong> <span style="opacity:0.75;">(8 bits)</span>: Next protocol: 1 = ICMP (Internet Control Message Protocol), 6 = TCP (Transmission Control Protocol), 17 = UDP (User Datagram Protocol), 89 = OSPF (Open Shortest Path First)</div><div style="margin-bottom:7px;"><strong>Header Checksum</strong> <span style="opacity:0.75;">(16 bits)</span>: Error check on the header only (recalculated at each hop)</div><div style="margin-bottom:7px;"><strong>Source Address</strong> <span style="opacity:0.75;">(32 bits)</span>: Sender IPv4 (Internet Protocol version 4) address</div><div style="margin-bottom:7px;"><strong>Destination Address</strong> <span style="opacity:0.75;">(32 bits)</span>: Receiver IPv4 address</div><div style="margin-bottom:7px;"><strong>Options</strong> <span style="opacity:0.75;">(0-40 bytes)</span>: Rarely used (e.g. Record Route, Timestamp); Padding pads the header to a multiple of 32 bits</div></div><p style="margin-top:8px;">Total: 20 bytes minimum, up to 60 bytes with Options. IHL × 4 = header length in bytes.</p></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 10 Flashcards - IPv4 Header)</div></div></div>' WHERE question_no = 'Anki-NF-1208';

-- Anki-NF-1210 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv4 Header: Total Length Field</div><p>The Total Length field records the size of the entire IPv4 (Internet Protocol version 4) packet (header plus data) in bytes, so a receiver knows exactly where the packet ends.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>Total Length</strong>: Total Length is the field that indicates the total length of the packet.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Identification</strong>: Identification groups fragments together; it does not state packet size.</li><li><span class="opt-tag wrong">Option B</span> <strong>IHL</strong>: IHL (Internet Header Length) records the header length only, not the whole packet length.</li><li><span class="opt-tag wrong">Option C</span> <strong>Fragment Offset</strong>: Fragment Offset records a fragment position; it does not state packet size.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Total Length = whole packet size in bytes.</li><li>IHL = header size only.</li><li>The exam often tests the difference.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📋 IPv4 Header - Full Reference (Memorize This):</div><table style="width:100%;border-collapse:collapse;margin-top:8px;font-size:13px;"><tr><td colspan="4" style="border:1px solid #4a5568;padding:6px;text-align:center;">Version<br><span style="font-size:12px;">4 bits</span></td><td colspan="4" style="border:1px solid #4a5568;padding:6px;text-align:center;">IHL<br><span style="font-size:12px;">4 bits</span></td><td colspan="6" style="border:1px solid #4a5568;padding:6px;text-align:center;">DSCP<br><span style="font-size:12px;">6 bits</span></td><td colspan="2" style="border:1px solid #4a5568;padding:6px;text-align:center;">ECN<br><span style="font-size:12px;">2 bits</span></td><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Total Length<br><span style="font-size:12px;">16 bits</span></td></tr><tr><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Identification<br><span style="font-size:12px;">16 bits</span></td><td colspan="3" style="border:1px solid #4a5568;padding:6px;text-align:center;">Flags<br><span style="font-size:12px;">3 bits</span></td><td colspan="13" style="border:1px solid #4a5568;padding:6px;text-align:center;">Fragment Offset<br><span style="font-size:12px;">13 bits</span></td></tr><tr><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">TTL<br><span style="font-size:12px;">8 bits</span></td><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">Protocol<br><span style="font-size:12px;">8 bits</span></td><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Header Checksum<br><span style="font-size:12px;">16 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Source Address<br><span style="font-size:12px;">32 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Destination Address<br><span style="font-size:12px;">32 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Options + Padding<br><span style="font-size:12px;">0-40 bytes</span></td></tr></table><div style="font-size:14px;line-height:1.7;margin-top:10px;"><div style="margin-bottom:7px;"><strong>Version</strong> <span style="opacity:0.75;">(4 bits)</span>: IP version (4)</div><div style="margin-bottom:7px;"><strong>IHL (Internet Header Length)</strong> <span style="opacity:0.75;">(4 bits)</span>: Header length in 32-bit words (5-15); IHL × 4 = header bytes (20-60)</div><div style="margin-bottom:7px;"><strong>DSCP (Differentiated Services Code Point)</strong> <span style="opacity:0.75;">(6 bits)</span>: QoS marking (0-63)</div><div style="margin-bottom:7px;"><strong>ECN (Explicit Congestion Notification)</strong> <span style="opacity:0.75;">(2 bits)</span>: Congestion notification (0-3)</div><div style="margin-bottom:7px;"><strong>Total Length</strong> <span style="opacity:0.75;">(16 bits)</span>: Whole packet length in bytes, header + data (max 65,535)</div><div style="margin-bottom:7px;"><strong>Identification</strong> <span style="opacity:0.75;">(16 bits)</span>: Same ID for all fragments of one packet</div><div style="margin-bottom:7px;"><strong>Flags</strong> <span style="opacity:0.75;">(3 bits)</span>: Reserved (0), DF (Don''t Fragment), MF (More Fragments)</div><div style="margin-bottom:7px;"><strong>Fragment Offset</strong> <span style="opacity:0.75;">(13 bits)</span>: Position of this fragment in the original packet (in 8-byte units)</div><div style="margin-bottom:7px;"><strong>TTL (Time to Live)</strong> <span style="opacity:0.75;">(8 bits)</span>: Max hops; each router subtracts 1, drops the packet at 0</div><div style="margin-bottom:7px;"><strong>Protocol</strong> <span style="opacity:0.75;">(8 bits)</span>: Next protocol: 1 = ICMP (Internet Control Message Protocol), 6 = TCP (Transmission Control Protocol), 17 = UDP (User Datagram Protocol), 89 = OSPF (Open Shortest Path First)</div><div style="margin-bottom:7px;"><strong>Header Checksum</strong> <span style="opacity:0.75;">(16 bits)</span>: Error check on the header only (recalculated at each hop)</div><div style="margin-bottom:7px;"><strong>Source Address</strong> <span style="opacity:0.75;">(32 bits)</span>: Sender IPv4 (Internet Protocol version 4) address</div><div style="margin-bottom:7px;"><strong>Destination Address</strong> <span style="opacity:0.75;">(32 bits)</span>: Receiver IPv4 address</div><div style="margin-bottom:7px;"><strong>Options</strong> <span style="opacity:0.75;">(0-40 bytes)</span>: Rarely used (e.g. Record Route, Timestamp); Padding pads the header to a multiple of 32 bits</div></div><p style="margin-top:8px;">Total: 20 bytes minimum, up to 60 bytes with Options. IHL × 4 = header length in bytes.</p></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 10 Flashcards - IPv4 Header)</div></div></div>' WHERE question_no = 'Anki-NF-1210';

-- Anki-NF-1219 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv4 Header: Flags Field Size</div><p>The Flags field is 3 bits long and holds three single-bit flags: Reserved (always 0), DF (Do not Fragment), and MF (More Fragments).</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>3</strong>: The Flags field is 3 bits in length.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>1</strong>: 1 bit is the size of each individual flag, but the whole Flags field is 3 bits.</li><li><span class="opt-tag wrong">Option C</span> <strong>13</strong>: 13 bits is the size of the Fragment Offset field, not the Flags field.</li><li><span class="opt-tag wrong">Option D</span> <strong>2</strong>: 2 bits is the size of the ECN (Explicit Congestion Notification) field, not the Flags field.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Flags = 3 bits, holding Reserved + DF + MF.</li><li>Fragment Offset = 13 bits.</li><li>Together they make 16 bits.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📋 IPv4 Header - Full Reference (Memorize This):</div><table style="width:100%;border-collapse:collapse;margin-top:8px;font-size:13px;"><tr><td colspan="4" style="border:1px solid #4a5568;padding:6px;text-align:center;">Version<br><span style="font-size:12px;">4 bits</span></td><td colspan="4" style="border:1px solid #4a5568;padding:6px;text-align:center;">IHL<br><span style="font-size:12px;">4 bits</span></td><td colspan="6" style="border:1px solid #4a5568;padding:6px;text-align:center;">DSCP<br><span style="font-size:12px;">6 bits</span></td><td colspan="2" style="border:1px solid #4a5568;padding:6px;text-align:center;">ECN<br><span style="font-size:12px;">2 bits</span></td><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Total Length<br><span style="font-size:12px;">16 bits</span></td></tr><tr><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Identification<br><span style="font-size:12px;">16 bits</span></td><td colspan="3" style="border:1px solid #4a5568;padding:6px;text-align:center;">Flags<br><span style="font-size:12px;">3 bits</span></td><td colspan="13" style="border:1px solid #4a5568;padding:6px;text-align:center;">Fragment Offset<br><span style="font-size:12px;">13 bits</span></td></tr><tr><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">TTL<br><span style="font-size:12px;">8 bits</span></td><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">Protocol<br><span style="font-size:12px;">8 bits</span></td><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Header Checksum<br><span style="font-size:12px;">16 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Source Address<br><span style="font-size:12px;">32 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Destination Address<br><span style="font-size:12px;">32 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Options + Padding<br><span style="font-size:12px;">0-40 bytes</span></td></tr></table><div style="font-size:14px;line-height:1.7;margin-top:10px;"><div style="margin-bottom:7px;"><strong>Version</strong> <span style="opacity:0.75;">(4 bits)</span>: IP version (4)</div><div style="margin-bottom:7px;"><strong>IHL (Internet Header Length)</strong> <span style="opacity:0.75;">(4 bits)</span>: Header length in 32-bit words (5-15); IHL × 4 = header bytes (20-60)</div><div style="margin-bottom:7px;"><strong>DSCP (Differentiated Services Code Point)</strong> <span style="opacity:0.75;">(6 bits)</span>: QoS marking (0-63)</div><div style="margin-bottom:7px;"><strong>ECN (Explicit Congestion Notification)</strong> <span style="opacity:0.75;">(2 bits)</span>: Congestion notification (0-3)</div><div style="margin-bottom:7px;"><strong>Total Length</strong> <span style="opacity:0.75;">(16 bits)</span>: Whole packet length in bytes, header + data (max 65,535)</div><div style="margin-bottom:7px;"><strong>Identification</strong> <span style="opacity:0.75;">(16 bits)</span>: Same ID for all fragments of one packet</div><div style="margin-bottom:7px;"><strong>Flags</strong> <span style="opacity:0.75;">(3 bits)</span>: Reserved (0), DF (Don''t Fragment), MF (More Fragments)</div><div style="margin-bottom:7px;"><strong>Fragment Offset</strong> <span style="opacity:0.75;">(13 bits)</span>: Position of this fragment in the original packet (in 8-byte units)</div><div style="margin-bottom:7px;"><strong>TTL (Time to Live)</strong> <span style="opacity:0.75;">(8 bits)</span>: Max hops; each router subtracts 1, drops the packet at 0</div><div style="margin-bottom:7px;"><strong>Protocol</strong> <span style="opacity:0.75;">(8 bits)</span>: Next protocol: 1 = ICMP (Internet Control Message Protocol), 6 = TCP (Transmission Control Protocol), 17 = UDP (User Datagram Protocol), 89 = OSPF (Open Shortest Path First)</div><div style="margin-bottom:7px;"><strong>Header Checksum</strong> <span style="opacity:0.75;">(16 bits)</span>: Error check on the header only (recalculated at each hop)</div><div style="margin-bottom:7px;"><strong>Source Address</strong> <span style="opacity:0.75;">(32 bits)</span>: Sender IPv4 (Internet Protocol version 4) address</div><div style="margin-bottom:7px;"><strong>Destination Address</strong> <span style="opacity:0.75;">(32 bits)</span>: Receiver IPv4 address</div><div style="margin-bottom:7px;"><strong>Options</strong> <span style="opacity:0.75;">(0-40 bytes)</span>: Rarely used (e.g. Record Route, Timestamp); Padding pads the header to a multiple of 32 bits</div></div><p style="margin-top:8px;">Total: 20 bytes minimum, up to 60 bytes with Options. IHL × 4 = header length in bytes.</p></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 10 Flashcards - IPv4 Header)</div></div></div>' WHERE question_no = 'Anki-NF-1219';

-- Anki-NF-1225 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv4 Flags: MF Bit Meaning</div><p>MF stands for More Fragments. A set MF bit tells the receiver that more fragments of this packet are still on their way; only the last fragment has MF cleared.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>More Fragments bit</strong>: MF stands for the More Fragments bit.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Many Fragments bit</strong>: The correct expansion is More Fragments.</li><li><span class="opt-tag wrong">Option C</span> <strong>Most Fragments bit</strong>: MF means More Fragments, not Most Fragments.</li><li><span class="opt-tag wrong">Option D</span> <strong>Missing Fragment bit</strong>: MF does not mean a fragment is missing; it means more fragments are coming.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>MF = More Fragments.</li><li>The last fragment of a packet always has MF = 0.</li><li>That is how the receiver knows reassembly is complete.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📋 IPv4 Header - Full Reference (Memorize This):</div><table style="width:100%;border-collapse:collapse;margin-top:8px;font-size:13px;"><tr><td colspan="4" style="border:1px solid #4a5568;padding:6px;text-align:center;">Version<br><span style="font-size:12px;">4 bits</span></td><td colspan="4" style="border:1px solid #4a5568;padding:6px;text-align:center;">IHL<br><span style="font-size:12px;">4 bits</span></td><td colspan="6" style="border:1px solid #4a5568;padding:6px;text-align:center;">DSCP<br><span style="font-size:12px;">6 bits</span></td><td colspan="2" style="border:1px solid #4a5568;padding:6px;text-align:center;">ECN<br><span style="font-size:12px;">2 bits</span></td><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Total Length<br><span style="font-size:12px;">16 bits</span></td></tr><tr><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Identification<br><span style="font-size:12px;">16 bits</span></td><td colspan="3" style="border:1px solid #4a5568;padding:6px;text-align:center;">Flags<br><span style="font-size:12px;">3 bits</span></td><td colspan="13" style="border:1px solid #4a5568;padding:6px;text-align:center;">Fragment Offset<br><span style="font-size:12px;">13 bits</span></td></tr><tr><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">TTL<br><span style="font-size:12px;">8 bits</span></td><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">Protocol<br><span style="font-size:12px;">8 bits</span></td><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Header Checksum<br><span style="font-size:12px;">16 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Source Address<br><span style="font-size:12px;">32 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Destination Address<br><span style="font-size:12px;">32 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Options + Padding<br><span style="font-size:12px;">0-40 bytes</span></td></tr></table><div style="font-size:14px;line-height:1.7;margin-top:10px;"><div style="margin-bottom:7px;"><strong>Version</strong> <span style="opacity:0.75;">(4 bits)</span>: IP version (4)</div><div style="margin-bottom:7px;"><strong>IHL (Internet Header Length)</strong> <span style="opacity:0.75;">(4 bits)</span>: Header length in 32-bit words (5-15); IHL × 4 = header bytes (20-60)</div><div style="margin-bottom:7px;"><strong>DSCP (Differentiated Services Code Point)</strong> <span style="opacity:0.75;">(6 bits)</span>: QoS marking (0-63)</div><div style="margin-bottom:7px;"><strong>ECN (Explicit Congestion Notification)</strong> <span style="opacity:0.75;">(2 bits)</span>: Congestion notification (0-3)</div><div style="margin-bottom:7px;"><strong>Total Length</strong> <span style="opacity:0.75;">(16 bits)</span>: Whole packet length in bytes, header + data (max 65,535)</div><div style="margin-bottom:7px;"><strong>Identification</strong> <span style="opacity:0.75;">(16 bits)</span>: Same ID for all fragments of one packet</div><div style="margin-bottom:7px;"><strong>Flags</strong> <span style="opacity:0.75;">(3 bits)</span>: Reserved (0), DF (Don''t Fragment), MF (More Fragments)</div><div style="margin-bottom:7px;"><strong>Fragment Offset</strong> <span style="opacity:0.75;">(13 bits)</span>: Position of this fragment in the original packet (in 8-byte units)</div><div style="margin-bottom:7px;"><strong>TTL (Time to Live)</strong> <span style="opacity:0.75;">(8 bits)</span>: Max hops; each router subtracts 1, drops the packet at 0</div><div style="margin-bottom:7px;"><strong>Protocol</strong> <span style="opacity:0.75;">(8 bits)</span>: Next protocol: 1 = ICMP (Internet Control Message Protocol), 6 = TCP (Transmission Control Protocol), 17 = UDP (User Datagram Protocol), 89 = OSPF (Open Shortest Path First)</div><div style="margin-bottom:7px;"><strong>Header Checksum</strong> <span style="opacity:0.75;">(16 bits)</span>: Error check on the header only (recalculated at each hop)</div><div style="margin-bottom:7px;"><strong>Source Address</strong> <span style="opacity:0.75;">(32 bits)</span>: Sender IPv4 (Internet Protocol version 4) address</div><div style="margin-bottom:7px;"><strong>Destination Address</strong> <span style="opacity:0.75;">(32 bits)</span>: Receiver IPv4 address</div><div style="margin-bottom:7px;"><strong>Options</strong> <span style="opacity:0.75;">(0-40 bytes)</span>: Rarely used (e.g. Record Route, Timestamp); Padding pads the header to a multiple of 32 bits</div></div><p style="margin-top:8px;">Total: 20 bytes minimum, up to 60 bytes with Options. IHL × 4 = header length in bytes.</p></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 10 Flashcards - IPv4 Header)</div></div></div>' WHERE question_no = 'Anki-NF-1225';

-- Anki-NF-1227 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv4 Header: Fragment Offset Field</div><p>The Fragment Offset field tells the receiver the position of a fragment within the original unfragmented packet, so the pieces can be put back together in the right order.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Fragment Offset</strong>: Fragment Offset is the field that indicates the position of a fragment within the original packet.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Flags</strong>: Flags say whether fragmentation is allowed and whether more fragments follow.</li><li><span class="opt-tag wrong">Option B</span> <strong>Identification</strong>: Identification says which packet a fragment belongs to, not where it sits inside it.</li><li><span class="opt-tag wrong">Option D</span> <strong>Total Length</strong>: Total Length states the size of the fragment, not its position.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Fragment Offset = position.</li><li>Identification = which packet.</li><li>Together they make reassembly work.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📋 IPv4 Header - Full Reference (Memorize This):</div><table style="width:100%;border-collapse:collapse;margin-top:8px;font-size:13px;"><tr><td colspan="4" style="border:1px solid #4a5568;padding:6px;text-align:center;">Version<br><span style="font-size:12px;">4 bits</span></td><td colspan="4" style="border:1px solid #4a5568;padding:6px;text-align:center;">IHL<br><span style="font-size:12px;">4 bits</span></td><td colspan="6" style="border:1px solid #4a5568;padding:6px;text-align:center;">DSCP<br><span style="font-size:12px;">6 bits</span></td><td colspan="2" style="border:1px solid #4a5568;padding:6px;text-align:center;">ECN<br><span style="font-size:12px;">2 bits</span></td><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Total Length<br><span style="font-size:12px;">16 bits</span></td></tr><tr><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Identification<br><span style="font-size:12px;">16 bits</span></td><td colspan="3" style="border:1px solid #4a5568;padding:6px;text-align:center;">Flags<br><span style="font-size:12px;">3 bits</span></td><td colspan="13" style="border:1px solid #4a5568;padding:6px;text-align:center;">Fragment Offset<br><span style="font-size:12px;">13 bits</span></td></tr><tr><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">TTL<br><span style="font-size:12px;">8 bits</span></td><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">Protocol<br><span style="font-size:12px;">8 bits</span></td><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Header Checksum<br><span style="font-size:12px;">16 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Source Address<br><span style="font-size:12px;">32 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Destination Address<br><span style="font-size:12px;">32 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Options + Padding<br><span style="font-size:12px;">0-40 bytes</span></td></tr></table><div style="font-size:14px;line-height:1.7;margin-top:10px;"><div style="margin-bottom:7px;"><strong>Version</strong> <span style="opacity:0.75;">(4 bits)</span>: IP version (4)</div><div style="margin-bottom:7px;"><strong>IHL (Internet Header Length)</strong> <span style="opacity:0.75;">(4 bits)</span>: Header length in 32-bit words (5-15); IHL × 4 = header bytes (20-60)</div><div style="margin-bottom:7px;"><strong>DSCP (Differentiated Services Code Point)</strong> <span style="opacity:0.75;">(6 bits)</span>: QoS marking (0-63)</div><div style="margin-bottom:7px;"><strong>ECN (Explicit Congestion Notification)</strong> <span style="opacity:0.75;">(2 bits)</span>: Congestion notification (0-3)</div><div style="margin-bottom:7px;"><strong>Total Length</strong> <span style="opacity:0.75;">(16 bits)</span>: Whole packet length in bytes, header + data (max 65,535)</div><div style="margin-bottom:7px;"><strong>Identification</strong> <span style="opacity:0.75;">(16 bits)</span>: Same ID for all fragments of one packet</div><div style="margin-bottom:7px;"><strong>Flags</strong> <span style="opacity:0.75;">(3 bits)</span>: Reserved (0), DF (Don''t Fragment), MF (More Fragments)</div><div style="margin-bottom:7px;"><strong>Fragment Offset</strong> <span style="opacity:0.75;">(13 bits)</span>: Position of this fragment in the original packet (in 8-byte units)</div><div style="margin-bottom:7px;"><strong>TTL (Time to Live)</strong> <span style="opacity:0.75;">(8 bits)</span>: Max hops; each router subtracts 1, drops the packet at 0</div><div style="margin-bottom:7px;"><strong>Protocol</strong> <span style="opacity:0.75;">(8 bits)</span>: Next protocol: 1 = ICMP (Internet Control Message Protocol), 6 = TCP (Transmission Control Protocol), 17 = UDP (User Datagram Protocol), 89 = OSPF (Open Shortest Path First)</div><div style="margin-bottom:7px;"><strong>Header Checksum</strong> <span style="opacity:0.75;">(16 bits)</span>: Error check on the header only (recalculated at each hop)</div><div style="margin-bottom:7px;"><strong>Source Address</strong> <span style="opacity:0.75;">(32 bits)</span>: Sender IPv4 (Internet Protocol version 4) address</div><div style="margin-bottom:7px;"><strong>Destination Address</strong> <span style="opacity:0.75;">(32 bits)</span>: Receiver IPv4 address</div><div style="margin-bottom:7px;"><strong>Options</strong> <span style="opacity:0.75;">(0-40 bytes)</span>: Rarely used (e.g. Record Route, Timestamp); Padding pads the header to a multiple of 32 bits</div></div><p style="margin-top:8px;">Total: 20 bytes minimum, up to 60 bytes with Options. IHL × 4 = header length in bytes.</p></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 10 Flashcards - IPv4 Header)</div></div></div>' WHERE question_no = 'Anki-NF-1227';

-- Anki-NF-1271 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Well-Known Ports: TCP 20</div><p>TCP (Transmission Control Protocol) port 20 is the FTP (File Transfer Protocol) data port, used to transfer the actual files while port 21 handles the control commands.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>FTP data</strong>: TCP port 20 is FTP data.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>FTP control</strong>: FTP control uses TCP port 21, not 20.</li><li><span class="opt-tag wrong">Option B</span> <strong>SMTP</strong>: SMTP uses TCP port 25, not 20.</li><li><span class="opt-tag wrong">Option C</span> <strong>SSH</strong>: SSH (Secure Shell) uses TCP port 22, not 20.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Port 20 = FTP data.</li><li>Port 21 = FTP control.</li><li>The exam asks both directions, so learn the pair.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 30 Flashcards - TCP &amp; UDP)</div></div></div>' WHERE question_no = 'Anki-NF-1271';

-- Anki-NF-1273 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Well-Known Ports: TCP 21</div><p>TCP (Transmission Control Protocol) port 21 is the FTP (File Transfer Protocol) control port, used to send commands like login, list and get, while the data moves on port 20.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>FTP control</strong>: TCP port 21 is FTP control.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Telnet</strong>: Telnet uses TCP port 23, not 21.</li><li><span class="opt-tag wrong">Option C</span> <strong>FTP data</strong>: FTP data uses TCP port 20, not 21.</li><li><span class="opt-tag wrong">Option D</span> <strong>SSH</strong>: SSH (Secure Shell) uses TCP port 22, not 21.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Port 21 = FTP control.</li><li>Port 20 = FTP data.</li><li>Control is the higher number of the pair.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 30 Flashcards - TCP &amp; UDP)</div></div></div>' WHERE question_no = 'Anki-NF-1273';

-- Anki-NF-1275 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Well-Known Ports: FTP Control Port Number</div><p>FTP (File Transfer Protocol) control uses TCP (Transmission Control Protocol) port 21, while FTP data uses TCP port 20.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>21</strong>: FTP control uses TCP port 21.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>20</strong>: Port 20 is FTP data, not FTP control.</li><li><span class="opt-tag wrong">Option B</span> <strong>22</strong>: Port 22 is SSH (Secure Shell), not FTP control.</li><li><span class="opt-tag wrong">Option D</span> <strong>25</strong>: Port 25 is SMTP, not FTP control.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>FTP control = 21.</li><li>Data = 20, control = 21.</li><li>Keep the pair straight.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 30 Flashcards - TCP &amp; UDP)</div></div></div>' WHERE question_no = 'Anki-NF-1275';

-- Anki-NF-1281 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Well-Known Ports: TCP 25</div><p>TCP (Transmission Control Protocol) port 25 is SMTP (Simple Mail Transfer Protocol), used to send email between mail servers.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>SMTP</strong>: TCP port 25 is SMTP.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>FTP control</strong>: FTP (File Transfer Protocol) control uses TCP port 21, not 25.</li><li><span class="opt-tag wrong">Option C</span> <strong>POP3</strong>: POP3 uses TCP port 110, not 25.</li><li><span class="opt-tag wrong">Option D</span> <strong>HTTP</strong>: HTTP (Hypertext Transfer Protocol) uses TCP port 80, not 25.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Port 25 = SMTP (sending mail).</li><li>Port 110 = POP3 (receiving mail).</li><li>Keep sending and receiving separate.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 30 Flashcards - TCP &amp; UDP)</div></div></div>' WHERE question_no = 'Anki-NF-1281';

-- Anki-NF-1284 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Well-Known Ports: TCP 80</div><p>TCP (Transmission Control Protocol) port 80 is HTTP (Hypertext Transfer Protocol), the protocol web browsers use to fetch unencrypted web pages.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>HTTP</strong>: TCP port 80 is HTTP.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>HTTPS</strong>: HTTPS (Hypertext Transfer Protocol Secure) uses TCP port 443, not 80.</li><li><span class="opt-tag wrong">Option C</span> <strong>POP3</strong>: POP3 uses TCP port 110, not 80.</li><li><span class="opt-tag wrong">Option D</span> <strong>SMTP</strong>: SMTP uses TCP port 25, not 80.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Port 80 = HTTP (plain web).</li><li>Port 443 = HTTPS (secure web).</li><li>The pair is one of the most tested in the exam.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 30 Flashcards - TCP &amp; UDP)</div></div></div>' WHERE question_no = 'Anki-NF-1284';

-- Anki-NF-1286 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Well-Known Ports: HTTP Port Number</div><p>HTTP (Hypertext Transfer Protocol) listens on TCP (Transmission Control Protocol) port 80 by default.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>80</strong>: HTTP uses TCP port 80.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>110</strong>: Port 110 is POP3, not HTTP.</li><li><span class="opt-tag wrong">Option B</span> <strong>443</strong>: Port 443 is HTTPS (Hypertext Transfer Protocol Secure), not plain HTTP.</li><li><span class="opt-tag wrong">Option C</span> <strong>25</strong>: Port 25 is SMTP, not HTTP.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Port 80 = HTTP.</li><li>Port 443 = HTTPS.</li><li>If the question says plain HTTP, the answer is always 80.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 30 Flashcards - TCP &amp; UDP)</div></div></div>' WHERE question_no = 'Anki-NF-1286';

-- Anki-NF-1287 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Well-Known Ports: TCP 110</div><p>TCP (Transmission Control Protocol) port 110 is POP3 (Post Office Protocol version 3), used to download email from a mail server to a local client.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>POP3</strong>: TCP port 110 is POP3.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>SMTP</strong>: SMTP uses TCP port 25, not 110.</li><li><span class="opt-tag wrong">Option C</span> <strong>HTTP</strong>: HTTP (Hypertext Transfer Protocol) uses TCP port 80, not 110.</li><li><span class="opt-tag wrong">Option D</span> <strong>IMAP</strong>: IMAP uses TCP port 143, not 110.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Port 110 = POP3 (mail download).</li><li>Port 25 = SMTP (mail sending).</li><li>Port 143 = IMAP (the other mail retrieval protocol).</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 30 Flashcards - TCP &amp; UDP)</div></div></div>' WHERE question_no = 'Anki-NF-1287';

-- Anki-NF-1290 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Well-Known Ports: TCP 443</div><p>TCP (Transmission Control Protocol) port 443 is HTTPS (Hypertext Transfer Protocol Secure) (HTTP Secure), the encrypted version of HTTP (Hypertext Transfer Protocol) used for secure web browsing.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>HTTPS</strong>: TCP port 443 is HTTPS.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>HTTP</strong>: HTTP uses TCP port 80, not 443.</li><li><span class="opt-tag wrong">Option C</span> <strong>SSH</strong>: SSH (Secure Shell) uses TCP port 22, not 443.</li><li><span class="opt-tag wrong">Option D</span> <strong>SMTP</strong>: SMTP uses TCP port 25, not 443.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Port 443 = HTTPS (secure web).</li><li>Port 80 = HTTP (plain web).</li><li>The secure version is always 443.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 30 Flashcards - TCP &amp; UDP)</div></div></div>' WHERE question_no = 'Anki-NF-1290';

-- Anki-NF-1331 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Connection-Oriented Transport</div><p>TCP (Transmission Control Protocol) is connection-oriented. Before any data is sent, the two hosts establish a connection with the three-way handshake, and the connection is tracked until it is closed.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>TCP</strong>: TCP is connection-oriented. It sets up a session with SYN, SYN-ACK, ACK before data flows, and tears it down with the four-way handshake afterwards.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Both TCP and UDP</strong>: Only TCP is connection-oriented. UDP (User Datagram Protocol) has no connection at all.</li><li><span class="opt-tag wrong">Option C</span> <strong>UDP</strong>: UDP is connectionless. It sends datagrams with no setup and no session.</li><li><span class="opt-tag wrong">Option D</span> <strong>Neither TCP nor UDP</strong>: TCP is connection-oriented, so this cannot be the answer.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Connection-oriented = TCP.</li><li>Connectionless = UDP.</li><li>This is one of the most tested TCP vs UDP facts.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 30 Flashcards - TCP &amp; UDP)</div></div>
</div>' WHERE question_no = 'Anki-NF-1331';

-- Anki-NF-1356 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: MAC Addresses - LAA</div><p>LAA stands for Locally Administered Address. It is a MAC (Media Access Control) address set locally by an administrator, with the U/L bit set to 1.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>Locally Administered Address</strong>: LAA is the Locally Administered Address. It is a MAC address an administrator overrides locally, and its U/L bit is 1.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Link Administered Address</strong>: The word is Locally, not Link. LAA has nothing to do with link-local addressing.</li><li><span class="opt-tag wrong">Option C</span> <strong>Locally Assigned Address</strong>: The word is Administered, not Assigned. The address is administered locally, not merely assigned.</li><li><span class="opt-tag wrong">Option D</span> <strong>Local Administered Address</strong>: The word is Locally, not Local. The full expansion is Locally Administered Address.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>LAA = Locally Administered Address.</li><li>Set by the admin, U/L bit = 1.</li><li>The opposite of UAA.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 32 Flashcards - IPv6 (Part 2)</div></div>
</div>' WHERE question_no = 'Anki-NF-1356';

-- Anki-NF-1357 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: MAC Address - U/L Bit</div><p>The 7th bit of a MAC (Media Access Control) address is called the U/L bit (Universal/Local bit). It tells you whether the address is universally administered (0) or locally administered (1).</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>U/L bit (Universal/Local bit)</strong>: The 7th bit is the U/L bit, short for Universal/Local bit. It is the bit EUI-64 (Extended Unique Identifier, 64-bit) inverts when building an interface identifier.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>I/G bit (Individual/Group bit)</strong>: The I/G bit is the 8th bit (the first bit transmitted), not the 7th. It marks unicast vs multicast.</li><li><span class="opt-tag wrong">Option B</span> <strong>G/L bit (Global/Local bit)</strong>: There is no G/L bit. The correct name is the U/L bit, Universal/Local.</li><li><span class="opt-tag wrong">Option C</span> <strong>U/M bit (Unicast/Multicast bit)</strong>: There is no U/M bit. Unicast vs multicast is the job of the I/G bit, the 8th bit.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>7th bit = U/L bit.</li><li>8th bit = I/G bit.</li><li>The exam loves asking which bit is which.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 32 Flashcards - IPv6 (Part 2)</div></div>
</div>' WHERE question_no = 'Anki-NF-1357';

-- Anki-NF-1362 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv6 Global Unicast Addresses</div><p>IPv6 (Internet Protocol version 6) global unicast addresses are like public IPv4 (Internet Protocol version 4) addresses. They are globally unique and routable on the internet, so any host with one can be reached from anywhere.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>global unicast</strong>: Global unicast addresses are like public IPv4 addresses. They are unique worldwide and routable across the internet.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>unique local</strong>: Unique local addresses are like private IPv4 addresses. They are only used inside an organisation, not on the internet.</li><li><span class="opt-tag wrong">Option B</span> <strong>link-local</strong>: Link-local addresses only work on one local link. They are never routed.</li><li><span class="opt-tag wrong">Option C</span> <strong>multicast</strong>: Multicast addresses identify a group of hosts, not one single host, so they are not like a public address.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Global unicast = public.</li><li>Unique local = private.</li><li>Link-local = one link only.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 32 Flashcards - IPv6 (Part 2)</div></div>
</div>' WHERE question_no = 'Anki-NF-1362';

-- Anki-NF-1370 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv6 Unique Local Addresses</div><p>IPv6 (Internet Protocol version 6) unique local addresses are like private IPv4 (Internet Protocol version 4) addresses. They are used only inside an organisation and are never routed on the public internet.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>unique local</strong>: Unique local addresses are like private IPv4 addresses. They give a site addresses that are unique within that site but not reachable from the internet.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>global unicast</strong>: Global unicast addresses are like public IPv4 addresses. They are routable on the internet.</li><li><span class="opt-tag wrong">Option B</span> <strong>multicast</strong>: Multicast addresses identify a group of hosts, not one private host.</li><li><span class="opt-tag wrong">Option C</span> <strong>link-local</strong>: Link-local addresses only work on one local link. They are not the private-address equivalent.</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Unique local = private.</li><li>Global unicast = public.</li><li>Same idea as IPv4, new names.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 32 Flashcards - IPv6 (Part 2)</div></div>
</div>' WHERE question_no = 'Anki-NF-1370';

-- Anki-NF-1426 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
<div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv6 Header Fields</div><p>The Traffic Class field in the IPv6 (Internet Protocol version 6) header is the equivalent of the IPv4 (Internet Protocol version 4) ToS/DSCP (Differentiated Services Code Point) field. It carries the QoS (Quality of Service) marking so routers can prioritise delay-sensitive traffic such as voice and video.</p></div>
<div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>Traffic Class</strong>: Traffic Class is the QoS field of the IPv6 header.</li></ul></div>
<div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Next Header</strong>: This identifies the encapsulated Layer 4 protocol, not QoS.</li><li><span class="opt-tag wrong">Option B</span> <strong>Flow Label</strong>: This identifies a specific traffic flow, not the QoS marking.</li><li><span class="opt-tag wrong">Option C</span> <strong>Hop Limit</strong>: This limits how many routers a packet can cross, like IPv4 TTL (Time to Live), not QoS.</li></ul></div>
<div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Traffic Class = QoS/DSCP.</li><li>Flow Label = which flow.</li><li>Next Header = what protocol follows.</li></ul></div>
<div class="expl-card concept-card"><div class="section-title-concept">📋 IPv6 Header - Full Reference (Memorize This):</div><table style="width:100%;border-collapse:collapse;margin-top:8px;font-size:13px;"><tr><td colspan="4" style="border:1px solid #4a5568;padding:6px;text-align:center;">Version<br><span style="font-size:12px;">4 bits</span></td><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">Traffic Class<br><span style="font-size:12px;">8 bits</span></td><td colspan="20" style="border:1px solid #4a5568;padding:6px;text-align:center;">Flow Label<br><span style="font-size:12px;">20 bits</span></td></tr><tr><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Payload Length<br><span style="font-size:12px;">16 bits</span></td><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">Next Header<br><span style="font-size:12px;">8 bits</span></td><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">Hop Limit<br><span style="font-size:12px;">8 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Source Address<br><span style="font-size:12px;">128 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Destination Address<br><span style="font-size:12px;">128 bits</span></td></tr></table><div style="font-size:14px;line-height:1.7;margin-top:10px;"><div style="margin-bottom:7px;"><strong>Version</strong> <span style="opacity:0.75;">(4 bits)</span>: IP version (6)</div><div style="margin-bottom:7px;"><strong>Traffic Class</strong> <span style="opacity:0.75;">(8 bits)</span>: QoS (Quality of Service), like DSCP (Differentiated Services Code Point) + ECN (Explicit Congestion Notification) in IPv4</div><div style="margin-bottom:7px;"><strong>Flow Label</strong> <span style="opacity:0.75;">(20 bits)</span>: Identifies one flow so routers treat its packets the same</div><div style="margin-bottom:7px;"><strong>Payload Length</strong> <span style="opacity:0.75;">(16 bits)</span>: Length of everything after the header (max 65,535)</div><div style="margin-bottom:7px;"><strong>Next Header</strong> <span style="opacity:0.75;">(8 bits)</span>: Next header type (like Protocol: 6 = TCP (Transmission Control Protocol), 17 = UDP (User Datagram Protocol), 58 = ICMPv6 (Internet Control Message Protocol version 6))</div><div style="margin-bottom:7px;"><strong>Hop Limit</strong> <span style="opacity:0.75;">(8 bits)</span>: Like TTL (Time to Live); each router subtracts 1, drops the packet at 0</div><div style="margin-bottom:7px;"><strong>Source Address</strong> <span style="opacity:0.75;">(128 bits)</span>: Sender IPv6 (Internet Protocol version 6) address, spans 4 × 32-bit words</div><div style="margin-bottom:7px;"><strong>Destination Address</strong> <span style="opacity:0.75;">(128 bits)</span>: Receiver IPv6 address, spans 4 × 32-bit words</div></div><p style="margin-top:8px;">Total: always 40 bytes. No header checksum, no fragmentation fields (handled by extension headers).</p></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 33 Flashcards - IPv6 (Part 3)</div></div>
</div>' WHERE question_no = 'Anki-NF-1426';

-- Anki-NF-1429 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
<div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv6 Header Fields</div><p>The IPv6 (Internet Protocol version 6) header is a fixed 40 bytes long, with no options field and no header-length field. That is double the 20-byte IPv4 (Internet Protocol version 4) header, because each IPv6 address is 16 bytes instead of 4.</p></div>
<div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>40 bytes</strong>: The IPv6 header is always 40 bytes.</li></ul></div>
<div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>60 bytes</strong>: That is the maximum IPv4 header size with options, not the IPv6 header.</li><li><span class="opt-tag wrong">Option C</span> <strong>20 bytes</strong>: That is the size of an IPv4 header with no options, not an IPv6 header.</li><li><span class="opt-tag wrong">Option D</span> <strong>32 bytes</strong>: That is the combined size of the two 16-byte IPv6 addresses alone, not the whole header.</li></ul></div>
<div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>IPv6 header = 40 bytes, fixed.</li><li>IPv4 header = 20 bytes minimum.</li><li>The exam tests this pair often.</li></ul></div>
<div class="expl-card concept-card"><div class="section-title-concept">📋 IPv6 Header - Full Reference (Memorize This):</div><table style="width:100%;border-collapse:collapse;margin-top:8px;font-size:13px;"><tr><td colspan="4" style="border:1px solid #4a5568;padding:6px;text-align:center;">Version<br><span style="font-size:12px;">4 bits</span></td><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">Traffic Class<br><span style="font-size:12px;">8 bits</span></td><td colspan="20" style="border:1px solid #4a5568;padding:6px;text-align:center;">Flow Label<br><span style="font-size:12px;">20 bits</span></td></tr><tr><td colspan="16" style="border:1px solid #4a5568;padding:6px;text-align:center;">Payload Length<br><span style="font-size:12px;">16 bits</span></td><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">Next Header<br><span style="font-size:12px;">8 bits</span></td><td colspan="8" style="border:1px solid #4a5568;padding:6px;text-align:center;">Hop Limit<br><span style="font-size:12px;">8 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Source Address<br><span style="font-size:12px;">128 bits</span></td></tr><tr><td colspan="32" style="border:1px solid #4a5568;padding:6px;text-align:center;">Destination Address<br><span style="font-size:12px;">128 bits</span></td></tr></table><div style="font-size:14px;line-height:1.7;margin-top:10px;"><div style="margin-bottom:7px;"><strong>Version</strong> <span style="opacity:0.75;">(4 bits)</span>: IP version (6)</div><div style="margin-bottom:7px;"><strong>Traffic Class</strong> <span style="opacity:0.75;">(8 bits)</span>: QoS (Quality of Service), like DSCP (Differentiated Services Code Point) + ECN (Explicit Congestion Notification) in IPv4</div><div style="margin-bottom:7px;"><strong>Flow Label</strong> <span style="opacity:0.75;">(20 bits)</span>: Identifies one flow so routers treat its packets the same</div><div style="margin-bottom:7px;"><strong>Payload Length</strong> <span style="opacity:0.75;">(16 bits)</span>: Length of everything after the header (max 65,535)</div><div style="margin-bottom:7px;"><strong>Next Header</strong> <span style="opacity:0.75;">(8 bits)</span>: Next header type (like Protocol: 6 = TCP (Transmission Control Protocol), 17 = UDP (User Datagram Protocol), 58 = ICMPv6 (Internet Control Message Protocol version 6))</div><div style="margin-bottom:7px;"><strong>Hop Limit</strong> <span style="opacity:0.75;">(8 bits)</span>: Like TTL (Time to Live); each router subtracts 1, drops the packet at 0</div><div style="margin-bottom:7px;"><strong>Source Address</strong> <span style="opacity:0.75;">(128 bits)</span>: Sender IPv6 (Internet Protocol version 6) address, spans 4 × 32-bit words</div><div style="margin-bottom:7px;"><strong>Destination Address</strong> <span style="opacity:0.75;">(128 bits)</span>: Receiver IPv6 address, spans 4 × 32-bit words</div></div><p style="margin-top:8px;">Total: always 40 bytes. No header checksum, no fragmentation fields (handled by extension headers).</p></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 33 Flashcards - IPv6 (Part 3)</div></div>
</div>' WHERE question_no = 'Anki-NF-1429';

-- Anki-NF-1460 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
<div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv6 Static Routes</div><p>In a directly attached static route the router forwards the packet out of the named interface and resolves the next hop itself, so only the exit interface is specified in the command.</p></div>
<div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>exit interface (only)</strong>: In a directly attached static route only the exit interface is specified.</li></ul></div>
<div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>exit interface and next hop</strong>: That is the fully specified form, not the directly attached form.</li><li><span class="opt-tag wrong">Option B</span> <strong>the administrative distance</strong>: Administrative distance is a separate, optional value, not what is specified instead of the interface.</li><li><span class="opt-tag wrong">Option D</span> <strong>next hop (only)</strong>: That is the recursive form, not the directly attached form.</li></ul></div>
<div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Directly attached = exit interface only.</li><li>Recursive = next hop only.</li><li>Fully specified = both.</li></ul></div>
<div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 33 Flashcards - IPv6 (Part 3)</div></div>
</div>' WHERE question_no = 'Anki-NF-1460';

-- Anki-NF-1480 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
<div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Campus LAN Design</div><p>The distribution layer is where a campus LAN moves from Layer 2 to Layer 3. Access switches forward by MAC (Media Access Control) address, and the distribution switches route between VLANs, so the distribution layer is the border between the two.</p></div>
<div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>distribution</strong>: The distribution layer is typically the border between Layer 2 and Layer 3.</li></ul></div>
<div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>core</strong>: The core forwards between distribution blocks; the L2/L3 border sits below it.</li><li><span class="opt-tag wrong">Option C</span> <strong>spine</strong>: Spine is a data-centre spine-leaf term, not a campus LAN layer.</li><li><span class="opt-tag wrong">Option D</span> <strong>access</strong>: The access layer is pure Layer 2; it does not route.</li></ul></div>
<div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Access = Layer 2.</li><li>Distribution = where routing starts.</li><li>That is the L2/L3 border.</li></ul></div>
<div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 52  Flashcards - LAN Architectures)</div></div>
</div>' WHERE question_no = 'Anki-NF-1480';

-- Anki-NF-1491 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
<div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Leased Lines (WAN)</div><p>A T1 leased line provides 1.544 Mbps. It is made of 24 DS0 channels of 64 kbps each, and it is the standard North American digital leased line.</p></div>
<div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>T1</strong>: T1 provides 1.544 Mbps of bandwidth, which is the rate of 24 DS0 channels at 64 kbps each.</li></ul></div>
<div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>T3</strong>: T3 provides 44.736 Mbps, far faster than 1.544 Mbps.</li><li><span class="opt-tag wrong">Option B</span> <strong>E1</strong>: E1 provides 2.048 Mbps and is the European standard, not 1.544 Mbps.</li><li><span class="opt-tag wrong">Option D</span> <strong>T2</strong>: T2 provides 6.312 Mbps, not 1.544 Mbps.</li></ul></div>
<div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>T1 = 1.544 Mbps.</li><li>E1 = 2.048 Mbps.</li><li>Learn the pair together.</li></ul></div>
<div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 53 Flashcards - WAN Architectures)</div></div>
</div>' WHERE question_no = 'Anki-NF-1491';

-- Anki-NF-1498 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
<div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: MPLS Router Roles</div><p>In an MPLS (Multiprotocol Label Switching) network there are three router roles: the CE (Customer Edge) on the customer site, the PE (Provider Edge) on the provider edge, and the P (Provider) router in the provider core.</p></div>
<div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Customer Edge</strong>: CE stands for Customer Edge. It is the customer router that connects a customer site to the provider PE router.</li></ul></div>
<div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Carrier Edge</strong>: Carrier Edge is not a standard MPLS role; the customer-side router is the Customer Edge.</li><li><span class="opt-tag wrong">Option B</span> <strong>Central Exchange</strong>: Central Exchange is not an MPLS term at all.</li><li><span class="opt-tag wrong">Option D</span> <strong>Core Edge</strong>: Core Edge mixes two roles; the core router is the P router, and the edge router is the CE or PE.</li></ul></div>
<div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>CE = Customer Edge (customer side).</li><li>PE = Provider Edge (provider side).</li><li>P = Provider core.</li></ul></div>
<div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 53 Flashcards - WAN Architectures)</div></div>
</div>' WHERE question_no = 'Anki-NF-1498';

-- Anki-NF-1505 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
<div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: WAN Access Technologies</div><p>DSL provides Internet connectivity over telephone lines. Other access technologies use different media: cable Internet uses TV coaxial cable, fiber uses optical glass, and satellite uses a dish link.</p></div>
<div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>DSL</strong>: DSL provides Internet connectivity via phone lines, using the existing telephone wiring.</li></ul></div>
<div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Fiber broadband</strong>: Fiber broadband runs over optical glass fiber, not phone lines.</li><li><span class="opt-tag wrong">Option B</span> <strong>Satellite Internet</strong>: Satellite Internet uses a dish and a space link, not phone lines.</li><li><span class="opt-tag wrong">Option D</span> <strong>Cable (CATV) Internet</strong>: Cable Internet runs over TV coaxial lines, not phone lines.</li></ul></div>
<div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Phone line = DSL.</li><li>TV cable = cable Internet.</li><li>Glass fiber = fiber broadband.</li></ul></div>
<div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 53 Flashcards - WAN Architectures)</div></div>
</div>' WHERE question_no = 'Anki-NF-1505';

-- Anki-NF-1508 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
<div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: WAN Access Technologies</div><p>A DSL modem converts data into a signal suitable for the phone line. A router forwards packets between networks, a switch forwards frames inside a LAN, and a splitter only separates voice and data frequencies.</p></div>
<div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>modem</strong>: A DSL modem is required to convert data into a format suitable to be sent over the phone lines.</li></ul></div>
<div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>switch</strong>: A switch forwards frames inside a LAN; it does not convert data for the phone line.</li><li><span class="opt-tag wrong">Option C</span> <strong>router</strong>: A router forwards packets between networks; it does not modulate data for the phone line.</li><li><span class="opt-tag wrong">Option D</span> <strong>splitter</strong>: A splitter only separates voice and data frequencies on the line; it does not convert the data itself.</li></ul></div>
<div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Converting data for the line = modem.</li><li>Forwarding packets = router.</li><li>Forwarding frames = switch.</li></ul></div>
<div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 53 Flashcards - WAN Architectures)</div></div>
</div>' WHERE question_no = 'Anki-NF-1508';

-- Anki-SEC-5007 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Vulnerability, Threat, Exploit and Mitigation</div><p>A vulnerability is any potential weakness in a system that could be used to compromise its security, for example an unpatched service or a weak password policy.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>vulnerability</strong>: A weakness that can compromise security is the definition of a vulnerability.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option D</span> <strong>threat</strong>: A threat is the potential that a vulnerability will be exploited, not the weakness itself.</li><li><span class="opt-tag wrong">Option A</span> <strong>exploit</strong>: An exploit is the tool or technique used to take advantage of a vulnerability, not the weakness itself.</li><li><span class="opt-tag wrong">Option C</span> <strong>risk</strong>: Risk is the overall likelihood and impact of a threat exploiting a vulnerability, not the weakness itself.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Vulnerability = the hole.</li><li>Threat = the danger it could be used.</li><li>Exploit = the tool that uses it.</li><li>Keep the three separate in exam questions.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Security Fundamentals (CCNA / Day 48 Flashcards - Security Fundamentals)</div></div></div>' WHERE question_no = 'Anki-SEC-5007';

-- Anki-SEC-5028 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Phishing</div><p>Phishing is social engineering using fraudulent emails that try to appear legitimate, usually to steal credentials or trick the user into clicking a malicious link.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>Phishing</strong>: Fraudulent emails that appear legitimate are phishing.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Spear phishing</strong>: Spear phishing is a targeted form of phishing aimed at specific people, not the general email-based attack.</li><li><span class="opt-tag wrong">Option C</span> <strong>Whaling</strong>: Whaling is phishing targeted at high-profile individuals such as executives, not the general form.</li><li><span class="opt-tag wrong">Option D</span> <strong>Smishing</strong>: Smishing is phishing performed over SMS text messages, not email.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Phishing = email.</li><li>Vishing = voice/phone.</li><li>Smishing = SMS.</li><li>The channel in the question tells you the answer.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Security Fundamentals (CCNA / Day 48 Flashcards - Security Fundamentals)</div></div></div>' WHERE question_no = 'Anki-SEC-5028';

-- Anki-SEC-5031 (mapping, 4 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Phishing Types</div><p>Vishing is phishing performed over the phone, using voice calls to trick the victim into revealing information or taking an action.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>Vishing</strong>: Phishing performed over the phone is vishing, from voice phishing.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option C</span> <strong>Smishing</strong>: Smishing is phishing using SMS text messages, not phone calls.</li><li><span class="opt-tag wrong">Option D</span> <strong>Phishing</strong>: Phishing is the general email-based form, not the phone-based form.</li><li><span class="opt-tag wrong">Option A</span> <strong>Spear phishing</strong>: Spear phishing is targeted email phishing, not the phone-based form.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>V = voice.</li><li>Vishing = voice phishing over a phone call.</li><li>Smishing = SMS.</li><li>Phishing = email.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Security Fundamentals (CCNA / Day 48 Flashcards - Security Fundamentals)</div></div></div>' WHERE question_no = 'Anki-SEC-5031';

-- Anki-SEC-5032 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Phishing Types</div><p>Smishing is phishing using SMS text messages, where the fake message usually contains a malicious link or asks the victim to reply with information.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>Smishing</strong>: Phishing using SMS text messages is smishing, from SMS phishing.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option D</span> <strong>Vishing</strong>: Vishing is phishing performed over the phone, not over SMS.</li><li><span class="opt-tag wrong">Option A</span> <strong>Phishing</strong>: Phishing is the general email-based form, not the SMS form.</li><li><span class="opt-tag wrong">Option B</span> <strong>Whaling</strong>: Whaling is phishing targeted at high-profile individuals, not the SMS form.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>SM = SMS.</li><li>Smishing = SMS phishing.</li><li>Fake delivery or bank messages by text are classic smishing.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Security Fundamentals (CCNA / Day 48 Flashcards - Security Fundamentals)</div></div></div>' WHERE question_no = 'Anki-SEC-5032';

-- Anki-SEC-5046 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: AAA Protocols</div><p>RADIUS (Remote Authentication Dial-In User Service) is the open-standard AAA (Authentication, Authorization, and Accounting) protocol, used widely with many vendors, while TACACS+ (Terminal Access Controller Access-Control System Plus) is Cisco proprietary. RADIUS runs over UDP (User Datagram Protocol) ports 1812 and 1813.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>RADIUS</strong>: RADIUS is the open-standard AAA protocol.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option C</span> <strong>TACACS+</strong>: TACACS+ is Cisco proprietary, not the open standard.</li><li><span class="opt-tag wrong">Option A</span> <strong>Diameter</strong>: Diameter is an AAA protocol that grew out of RADIUS, but the classic open standard in CCNA is RADIUS.</li><li><span class="opt-tag wrong">Option B</span> <strong>Kerberos</strong>: Kerberos is an authentication protocol used in Windows domains, it is not the open-standard AAA protocol in CCNA.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Open standard = RADIUS.</li><li>Cisco proprietary = TACACS+.</li><li>That pairing is a very common exam question.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Security Fundamentals (CCNA / Day 48 Flashcards - Security Fundamentals)</div></div></div>' WHERE question_no = 'Anki-SEC-5046';

-- Anki-SEC-5052 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: User Awareness</div><p>User awareness programs are designed to make employees aware of potential security threats and risks, so they recognise attacks such as phishing instead of falling for them.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>User awareness</strong>: Programs that make employees aware of security threats and risks are user awareness programs.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>User training</strong>: User training is the formal sessions that educate users on policies, awareness is the broader program that keeps threats in mind.</li><li><span class="opt-tag wrong">Option B</span> <strong>User education</strong>: User education is a general term, but the specific program that builds awareness of threats is called user awareness.</li><li><span class="opt-tag wrong">Option D</span> <strong>User authentication</strong>: User authentication is verifying a user&#x27;s identity, not a program that makes employees aware of threats.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Awareness = knowing the threats exist.</li><li>Training = the formal sessions that teach the policies.</li><li>Both matter, and the exam tests the difference.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Security Fundamentals (CCNA / Day 48 Flashcards - Security Fundamentals)</div></div></div>' WHERE question_no = 'Anki-SEC-5052';

-- Anki-SEC-5054 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: Physical Access Control</div><p>Physical access control protects equipment and data by only allowing authorised users into protected areas such as network closets, using locks, badges and guards.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>Physical access control</strong>: Only allowing authorised users into protected physical areas is physical access control.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Logical access control</strong>: Logical access control restricts access to data and systems through software, not to physical rooms.</li><li><span class="opt-tag wrong">Option C</span> <strong>Biometric access control</strong>: Biometric access control is one method, such as a fingerprint reader, that can enforce physical access control, but it is not the general term.</li><li><span class="opt-tag wrong">Option B</span> <strong>Network access control</strong>: Network access control governs which devices may join the network, not who may walk into a network closet.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>Physical = doors, locks, badges.</li><li>Logical = passwords, ACLs, firewalls.</li><li>The word physical in the question is the giveaway.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Security Fundamentals (CCNA / Day 48 Flashcards - Security Fundamentals)</div></div></div>' WHERE question_no = 'Anki-SEC-5054';

-- Question #203 (mapping, 3 items)
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card">
    <div class="section-title-concept">📌 Core Concept: Wireless Encryption & Data Confidentiality</div>
    <p>Wireless transmissions propagate omnidirectionally through the air. Because physical access to radio waves cannot be blocked, encryption is essential to render captured traffic unreadable to unauthorized parties.</p>
  </div>

  <div class="expl-card correct-card">
    <h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4>
    <ul>
      <li><span class="opt-tag correct">Option D</span> <strong>Prevents intercepted data from being easily read</strong>: Strong wireless encryption protocols (like AES-CCMP in WPA2 and AES-GCMP in WPA3) mathematically transform plaintext into ciphertext. Even if an attacker captures the raw 802.11 frames using packet sniffers, they cannot read the sensitive payload without the dynamic decryption keys.</li>
    </ul>
  </div>

  <div class="expl-card incorrect-card">
    <h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4>
    <ul>
      <li><span class="opt-tag wrong">Option A</span>: Encryption protects confidentiality; firewalls, IPS, and WIPS intercept active attack threats.</li>
      <li><span class="opt-tag wrong">Option B</span>: Integrity checks (MIC / HMAC) detect tampering, but the core characteristic of encryption is confidentiality (preventing data from being read).</li>
      <li><span class="opt-tag wrong">Option C</span>: 802.11 authentication uses bidirectional multi-way handshakes (such as the 4-way handshake or Dragonfly SAE exchange), not a unidirectional handshake.</li>
    </ul>
  </div>

  <div class="expl-card tip-card">
    <h4 class="section-title-tip">💡 CCNA Exam Tip:</h4>
    <ul><li>Confidentiality = <strong>Encryption</strong> (scrambles data).</li><li>Integrity = <strong>Hashing / MIC</strong> (detects tampering).</li><li>Availability = <strong>Redundancy / RF management</strong>.</li></ul>
  </div>
</div>' WHERE question_no = 'Question #203';


-- Anki-NF-1072 (converted earlier, appended so this file covers all 210 tips):
UPDATE questions SET explanation = '<div class="explanation-rich-content">
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IEEE 802.3ae - 10 Gigabit Fiber</div><p>IEEE 802.3ae defines 10 Gigabit Ethernet over fiber, including the 10GBASE-SR (short range), 10GBASE-LR (long range) and 10GBASE-ER (extended range) variants.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class="opt-tag correct">Option C</span> <strong>802.3ae</strong>: 10GBASE-SR, 10GBASE-LR and 10GBASE-ER were defined in the IEEE 802.3ae standard.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>802.3an</strong>: 802.3an defines 10 Gigabit Ethernet over copper (10GBASE-T), not over fiber.</li><li><span class="opt-tag wrong">Option D</span> <strong>802.3ab</strong>: 802.3ab defines 1 Gigabit Ethernet over copper (1000BASE-T).</li><li><span class="opt-tag wrong">Option B</span> <strong>802.3z</strong>: 802.3z defines 1 Gigabit Ethernet over fiber (1000BASE-SX/LX).</li></ul></div>
  <div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><ul><li>ae = 10 Gig fiber.</li><li>an = 10 Gig copper.</li><li>z = 1 Gig fiber.</li><li>ab = 1 Gig copper.</li></ul></div>
  <div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>
</div>' WHERE question_no = 'Anki-NF-1072';
